let adminEditingStaffEmail = '';

function setStaffAccountFormMode(mode, email = '') {
    adminEditingStaffEmail = mode === 'edit' ? String(email || '').trim().toLowerCase() : '';
    window.adminEditingStaffEmail = adminEditingStaffEmail;

    const createBtn = document.getElementById('btnCreateStaffAccount');
    const updateBtn = document.getElementById('btnUpdateStaffAccount');
    const cancelBtn = document.getElementById('btnCancelStaffEdit');
    const note = document.getElementById('adminStaffModeNote');
    const emailEl = document.getElementById('admin_newEmail');
    const passwordEl = document.getElementById('admin_newPassword');

    const isEdit = mode === 'edit';
    if (createBtn) createBtn.style.display = isEdit ? 'none' : 'inline-block';
    if (updateBtn) updateBtn.style.display = isEdit ? 'inline-block' : 'none';
    if (cancelBtn) cancelBtn.style.display = isEdit ? 'inline-block' : 'none';
    if (note) note.textContent = isEdit ? `Edit Mode — Updating ${adminEditingStaffEmail}` : 'Create Mode';
    if (emailEl) {
        emailEl.readOnly = isEdit;
        emailEl.style.background = isEdit ? '#f7f7f7' : '';
        emailEl.title = isEdit ? 'Email is the staff record ID and is locked during update to prevent duplicate users.' : '';
    }
    if (passwordEl) {
        passwordEl.placeholder = isEdit ? '(Leave blank to keep current password)' : '(Optional) Min 6 chars';
    }
}

window.cancelStaffEditMode = function() {
    document.getElementById('admin_newName').value = '';
    document.getElementById('admin_newEmail').value = '';
    document.getElementById('admin_newPassword').value = '';
    document.querySelectorAll('.role-checkbox').forEach(cb => cb.checked = false);
    clearAdminProfileFields();
    clearStaffPhotoUpload();
    setStaffAccountFormMode('create');
};

function getLocalDateString() {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

let todayDateStr = getLocalDateString();

