function thArchiveEscape(value) {
    return String(value ?? '').replace(/[&<>"']/g, ch => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    }[ch]));
}

function thArchiveCount(value) {
    const num = Number(value);
    return Number.isFinite(num) ? num.toLocaleString() : '--';
}

function thArchiveNumber(value, fallback = 0) {
    const num = Number(value);
    return Number.isFinite(num) ? num : fallback;
}

function thArchiveDateText(value) {
    if (!value) return '';
    if (typeof value?.toDate === 'function') {
        try { return value.toDate().toLocaleString(); } catch(e) { return ''; }
    }
    if (typeof value?.seconds === 'number') {
        try { return new Date(value.seconds * 1000).toLocaleString(); } catch(e) { return ''; }
    }
    return String(value || '');
}

function thArchiveMoney(value) {
    const num = window.thFinancialEvidence.amount(value);
    return num === null ? 'Unavailable' : `${num.toFixed(2)} GHC`;
}

function thArchiveManifestRowKey(row) {
    return `${String(row?.collection || '')}::${String(row?.docId || '')}`;
}

function thArchiveIsPilotExecutionCollection(collection) {
    return TH_ARCHIVE_EXECUTION_COLLECTIONS.includes(String(collection || '').trim());
}

function thArchiveExecutionLabel(collection) {
    return String(collection || '') === 'Active_Jobs'
        ? 'synthetic Active Jobs revenue pilot'
        : 'Attendance';
}

function thArchiveCollectionLabel(collection) {
    return TH_ARCHIVE_COLLECTION_LABELS[String(collection || '').trim()]
        || String(collection || '').replace(/_/g, ' ')
        || 'Unknown';
}

function thArchiveSelectedPolicy() {
    const selected = String(document.getElementById('thArchivePolicy')?.value || 'pre_go_live_test_data').trim();
    return TH_ARCHIVE_POLICIES[selected] || TH_ARCHIVE_POLICIES.pre_go_live_test_data;
}

function thArchiveIsPreGoLivePolicy(policy = thArchiveSelectedPolicy()) {
    return String(policy?.id || policy?.reason || '').trim() === 'pre_go_live_test_data';
}

function thArchivePolicyAllowedCollections(policy = thArchiveSelectedPolicy()) {
    const allowed = Array.isArray(policy?.allowedCollections) ? policy.allowedCollections : [];
    return allowed
        .map(item => String(item || '').trim())
        .filter(item => TH_ARCHIVE_PREVIEW_COLLECTIONS.includes(item));
}

function thArchivePolicyList(items) {
    const safeItems = Array.isArray(items) ? items.filter(Boolean) : [];
    if (!safeItems.length) return 'None';
    return safeItems.map(item => String(item || '').trim()).join(', ');
}

function thArchivePopulateCollectionScope(policy = thArchiveSelectedPolicy()) {
    const select = document.getElementById('thArchiveCollection');
    if (!select) return;
    const previous = String(select.value || 'all');
    const allowed = thArchivePolicyAllowedCollections(policy);
    if (!allowed.length) {
        select.innerHTML = '<option value="all">No policy-enabled collections</option>';
        select.value = 'all';
        select.disabled = true;
        return;
    }
    select.innerHTML = [
        '<option value="all">All policy-allowed collections</option>',
        ...allowed.map(collection => `<option value="${thArchiveEscape(collection)}">${thArchiveEscape(thArchiveCollectionLabel(collection))} only</option>`)
    ].join('');
    select.value = allowed.includes(previous) ? previous : 'all';
    select.disabled = false;
}

function thArchiveSyncPolicyReason(policy = thArchiveSelectedPolicy()) {
    const reason = document.getElementById('thArchiveReason');
    if (!reason) return;
    reason.value = policy.reason || policy.id || 'pre_go_live_test_data';
    reason.disabled = true;
}

function thArchiveRenderPolicyExplanation(policy = thArchiveSelectedPolicy()) {
    const panel = document.getElementById('thArchivePolicyPanel');
    if (!panel) return;
    const allowed = thArchivePolicyList(policy.allowedCollections);
    const excluded = thArchivePolicyList(policy.excludedCollections);
    const previewLabel = policy.previewEnabled ? 'Read-only preview enabled' : 'Design only';
    const executionStatus = thArchiveIsProductionEnvironment()
        ? 'Production audit-only. Archive and rollback execution controls are hidden or disabled in the Staff App.'
        : policy.executionStatus;
    const rollbackStatus = thArchiveIsProductionEnvironment()
        ? 'Rollback backend remains available for the retained batch, but UI rollback execution is disabled unless separately approved.'
        : (policy.rollbackStatus || 'Rollback required before execution.');
    panel.innerHTML = `
        <div style="display:flex; justify-content:space-between; gap:14px; flex-wrap:wrap; align-items:flex-start;">
            <div>
                <div style="font-size:0.74rem; text-transform:uppercase; letter-spacing:0.1em; color:#777; font-weight:900;">Archive Policy</div>
                <h4 style="margin:4px 0 8px; color:var(--primary);">${thArchiveEscape(policy.label)}</h4>
                <p style="margin:0; color:#555; line-height:1.5;">${thArchiveEscape(policy.purpose)}</p>
            </div>
            <span style="display:inline-flex; align-items:center; border:1px solid var(--border); border-radius:999px; padding:7px 12px; background:${policy.previewEnabled ? '#f0fff4' : '#f7f4ec'}; color:${policy.previewEnabled ? '#1f6f3b' : 'var(--primary)'}; font-size:0.72rem; text-transform:uppercase; letter-spacing:0.08em; font-weight:900;">${thArchiveEscape(previewLabel)}</span>
        </div>
        <div class="grid-3" style="margin-top:14px; margin-bottom:0;">
            <div>
                <div style="font-size:0.72rem; text-transform:uppercase; letter-spacing:0.08em; color:#777; font-weight:900;">ID / Reason</div>
                <div style="font-family:monospace; font-size:0.82rem; color:#333; word-break:break-word;">${thArchiveEscape(policy.reason || policy.id)}</div>
            </div>
            <div>
                <div style="font-size:0.72rem; text-transform:uppercase; letter-spacing:0.08em; color:#777; font-weight:900;">Allowed Collections</div>
                <div style="font-size:0.84rem; color:#333;">${thArchiveEscape(allowed)}</div>
            </div>
            <div>
                <div style="font-size:0.72rem; text-transform:uppercase; letter-spacing:0.08em; color:#777; font-weight:900;">Excluded Collections</div>
                <div style="font-size:0.84rem; color:#333;">${thArchiveEscape(excluded)}</div>
            </div>
        </div>
        <div style="margin-top:12px; display:grid; gap:8px; color:#555; font-size:0.84rem; line-height:1.45;">
            <div><strong>Date / cutoff:</strong> ${thArchiveEscape(policy.dateRule)}</div>
            <div><strong>Manual review:</strong> ${thArchiveEscape(policy.manualReviewRequirements)}</div>
            <div><strong>Deletes:</strong> Disabled. Archive Center uses soft archive markers only.</div>
            <div><strong>Rollback:</strong> ${thArchiveEscape(rollbackStatus)}</div>
            <div><strong>Status:</strong> ${thArchiveEscape(executionStatus)}</div>
        </div>
    `;
}

function thArchiveUpdatePolicyControls(options = {}) {
    const policy = thArchiveSelectedPolicy();
    thArchivePopulateCollectionScope(policy);
    thArchiveSyncPolicyReason(policy);
    thArchiveRenderPolicyExplanation(policy);
    const preview = document.getElementById('thArchivePreviewBtn');
    if (preview) {
        preview.disabled = !!options.busy || !policy.previewEnabled || thArchiveIsProductionEnvironment();
        preview.title = thArchiveIsProductionEnvironment()
            ? 'Production Archive Center uses the Pre-Go-Live policy preview and retained batch history for audit.'
            : policy.previewEnabled
            ? 'Run read-only archive manifest preview.'
            : `${policy.label} is design-only in this phase.`;
    }
    const policyPreviewPanel = document.getElementById('thArchivePreGoLivePolicyPreviewPanel');
    const policyPreview = document.getElementById('thArchivePolicyPreviewBtn');
    const policyExecute = document.getElementById('thArchivePolicyExecuteDisabledBtn');
    const isPreGoLive = thArchiveIsPreGoLivePolicy(policy);
    if (policyPreviewPanel) policyPreviewPanel.style.display = isPreGoLive ? 'block' : 'none';
    if (policyPreview) {
        policyPreview.disabled = !!options.busy || !isPreGoLive;
        policyPreview.title = isPreGoLive
            ? 'Run owner-approved pre-go-live policy preview. Read-only only.'
            : 'Policy preview is available only for Pre-Go-Live Cleanup in DA-4C-C.';
    }
    if (policyExecute) {
        policyExecute.disabled = true;
        policyExecute.title = 'Use the gated Owner-Approved Cutoff Archive section after a successful preview.';
    }
    if (options.showStatus && !policy.previewEnabled) {
        thArchiveSetStatus(`${policy.label} is visible for policy clarity only. Preview and archive execution are disabled in this phase.`, 'info');
    }
}

function thArchiveResetPolicyPreviewResult() {
    thArchivePreviewState.policyPreviewResult = null;
    thArchivePreviewState.policyExecutionResult = null;
    const container = document.getElementById('thArchivePolicyPreviewResult');
    if (container) {
        container.innerHTML = '<p style="font-size:0.84rem; color:#777; margin:0;">Run the owner-approved cutoff preview to inspect pre-go-live targets. This lane is read-only.</p>';
    }
    const confirmation = document.getElementById('thArchivePolicyArchiveConfirmation');
    if (confirmation) confirmation.value = '';
    const archiveResult = document.getElementById('thArchivePolicyArchiveResult');
    if (archiveResult) archiveResult.innerHTML = '';
    thArchiveUpdatePreGoLiveArchiveState();
}

window.thArchivePolicyChanged = function() {
    thArchivePreviewState.basePayload = null;
    thArchivePreviewState.pageTokens = [''];
    thArchivePreviewState.pageIndex = 0;
    thArchivePreviewState.nextPageToken = '';
    thArchiveResetPreviewResults();
    thArchiveResetPolicyPreviewResult();
    thArchiveUpdatePolicyControls({ showStatus: true });
};

function thArchiveSoftConfirmationText(collection, count) {
    return String(collection || '') === 'Active_Jobs'
        ? `ARCHIVE ${count} ACTIVE JOBS`
        : `ARCHIVE ${count} RECORDS`;
}

function thArchiveBatchPilotScopeAllowed(batch) {
    const collection = String(batch?.collection || '').trim();
    const scope = String(batch?.pilotScope || '').trim();
    if (collection === 'Attendance') return !scope || scope === 'attendance_only';
    if (collection === 'Active_Jobs') return scope === 'active_jobs_revenue_pilot';
    return false;
}

function thArchiveBatchIsProductionRetained(batch) {
    const id = String(batch?.archiveBatchId || batch?.id || '').trim();
    const scope = String(batch?.scope || batch?.pilotScope || '').trim();
    return id === TH_ARCHIVE_PRODUCTION_RETAINED_BATCH_ID
        || scope === TH_ARCHIVE_PRODUCTION_RETAINED_SCOPE;
}

function thArchiveBatchShouldShow(batch) {
    return thArchiveBatchPilotScopeAllowed(batch)
        || (thArchiveIsProductionEnvironment() && thArchiveBatchIsProductionRetained(batch));
}

function thArchiveBatchDisplayCollection(batch) {
    if (thArchiveBatchIsProductionRetained(batch)) return 'Pre-Go-Live Policy';
    return String(batch?.collection || batch?.sourceCollection || '');
}

function thArchiveBatchSnapshotCount(batch) {
    if (Number.isFinite(Number(batch?.snapshotCount))) return Number(batch.snapshotCount);
    if (Number.isFinite(Number(batch?.recordCount))) return Number(batch.recordCount);
    if (Number.isFinite(Number(batch?.archivedCount))) return Number(batch.archivedCount);
    return 0;
}

function thArchiveIsSelectablePilotCandidate(row) {
    return thArchiveIsPilotExecutionCollection(row?.collection)
        && String(row?.archiveDecision || '').toLowerCase() === 'candidate'
        && String(row?.riskLevel || '').toLowerCase() === 'low'
        && !!String(row?.docId || '').trim();
}

function thArchiveIsSelectableAttendanceCandidate(row) {
    return thArchiveIsSelectablePilotCandidate(row);
}

function thArchiveSetText(id, value) {
    const el = document.getElementById(id);
    if (el) el.textContent = value;
}

function thArchiveSetStatus(message, type = 'info') {
    const el = document.getElementById('thArchivePreviewStatus');
    if (!el) return;
    el.textContent = message || '';
    const styles = {
        success: { border: '1px solid #b8e0c2', background: '#f0fff4', color: '#1f6f3b' },
        error: { border: '1px solid #e5b5aa', background: '#fff1ef', color: '#7a2d20' },
        info: { border: '1px solid var(--border)', background: '#fff', color: '#666' }
    };
    const style = styles[type] || styles.info;
    el.style.border = style.border;
    el.style.background = style.background;
    el.style.color = style.color;
}

function thArchiveSetWriteActionsDisabled() {
    ['thArchiveDownloadCsvBtn', 'thArchiveDownloadJsonBtn', 'thArchiveSoftArchiveBtn', 'thArchiveRollbackBtn', 'thArchivePolicyArchiveBtn', 'thArchivePairCreateApprovalBtn', 'thArchivePairFinalArchiveBtn'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.disabled = true;
    });
}

function thArchiveSelectedRows() {
    return Array.from(thArchivePreviewState.selectedRows.values());
}

function thArchiveSelectedPilotCollection(rows = thArchiveSelectedRows()) {
    const collections = Array.from(new Set(rows
        .map(row => String(row?.collection || '').trim())
        .filter(Boolean)));
    return collections.length === 1 ? collections[0] : '';
}

function thArchiveSelectedPilotIds() {
    return thArchiveSelectedRows()
        .filter(thArchiveIsSelectablePilotCandidate)
        .map(row => String(row.docId || '').trim())
        .filter(Boolean);
}

function thArchiveUpdateSelectionState() {
    const selectedRows = thArchiveSelectedRows();
    const selectedCount = selectedRows.length;
    const selectedIds = thArchiveSelectedPilotIds();
    const selectedCollection = thArchiveSelectedPilotCollection(selectedRows);
    const canExecute = thArchiveCenterCanExecute(currentRoles);
    const allEligible = selectedCount > 0
        && selectedCount === selectedIds.length
        && !!selectedCollection
        && selectedRows.every(thArchiveIsSelectablePilotCandidate);

    const summary = document.getElementById('thArchiveSelectionSummary');
    if (summary) {
        if (!selectedCount) {
            summary.textContent = thArchiveIsProductionEnvironment()
                ? 'Production Archive Center is audit-only. Archive execution controls are disabled.'
                : canExecute
                ? 'Select low-risk Attendance or synthetic Active Jobs pilot candidates from the preview to enable the controlled archive action.'
                : 'Archive preview and execution are restricted to System Admin.';
        } else if (!selectedCollection) {
            summary.textContent = 'Select records from one pilot collection at a time before soft archive.';
        } else {
            summary.textContent = `${selectedCount} ${thArchiveExecutionLabel(selectedCollection)} candidate${selectedCount === 1 ? '' : 's'} selected for soft archive.`;
        }
    }

    const softArchive = document.getElementById('thArchiveSoftArchiveBtn');
    if (softArchive) {
        softArchive.disabled = !(canExecute && allEligible);
        softArchive.style.background = softArchive.disabled ? '#9ca3af' : 'var(--primary)';
    }

    thArchiveUpdateDownloadState();

    thArchiveUpdateRollbackState();
}

function thArchiveUpdateDownloadState() {
    const canDownload = thArchiveCenterCanShow(currentRoles)
        && thArchivePreviewState.lastResult
        && String(thArchivePreviewState.lastResult.readOnly) === 'true'
        && Array.isArray(thArchivePreviewState.lastResult.manifestRows);
    ['thArchiveDownloadCsvBtn', 'thArchiveDownloadJsonBtn'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.disabled = !canDownload;
    });
}

function thArchiveUpdateRollbackState() {
    const canExecute = thArchiveCenterCanExecute(currentRoles);
    const batch = thArchivePreviewState.selectedBatch;
    const canRollback = canExecute
        && batch
        && thArchiveIsPilotExecutionCollection(batch.collection)
        && thArchiveBatchPilotScopeAllowed(batch)
        && String(batch.status || '').toLowerCase() === 'archived'
        && thArchiveNumber(batch.recordCount || batch.archivedCount || batch.rollbackCount, 0) > 0;

    const rollback = document.getElementById('thArchiveRollbackBtn');
    if (rollback) rollback.disabled = !canRollback;

    const summary = document.getElementById('thArchiveRollbackSummary');
    if (summary) {
        if (!batch) {
            summary.textContent = thArchiveIsProductionEnvironment()
                ? 'Production rollback remains available through the protected backend, but UI rollback execution is disabled unless separately approved.'
                : canExecute
                ? 'Select an archived pilot batch from history to enable rollback.'
                : 'Rollback execution is restricted to System Admin.';
        } else {
            const displayCollection = thArchiveBatchDisplayCollection(batch);
            const displayCount = thArchiveBatchSnapshotCount(batch);
            summary.textContent = `Selected ${batch.archiveBatchId || 'batch'} - ${displayCollection}, ${thArchiveCount(displayCount)} record${displayCount === 1 ? '' : 's'}, status ${batch.status || 'unknown'}.`;
        }
    }
}

function thArchiveSetBusy(isBusy) {
    ['thArchivePolicy', 'thArchivePreviewBtn', 'thArchivePolicyPreviewBtn', 'thArchivePolicyArchiveConfirmation', 'thArchivePolicyArchiveBtn', 'thArchivePairedReviewBtn', 'thArchivePairReviewNotes', 'thArchivePairCreateApprovalBtn', 'thArchivePairFinalConfirmation', 'thArchivePairFinalArchiveBtn', 'thArchiveCollection', 'thArchiveFrom', 'thArchiveTo', 'thArchiveReason'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.disabled = !!isBusy;
    });
    document.querySelectorAll('.th-archive-pair-approval-check').forEach(el => {
        el.disabled = !!isBusy;
    });
    ['thArchivePrevPageBtn', 'thArchiveNextPageBtn'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.disabled = true;
    });
    document.querySelectorAll('.th-archive-candidate-check').forEach(el => {
        const key = String(el.dataset.key || '');
        const row = thArchivePreviewState.currentRows.find(item => thArchiveManifestRowKey(item) === key);
        el.disabled = !!isBusy || !thArchiveIsSelectablePilotCandidate(row);
    });
    document.querySelectorAll('.th-archive-batch-radio').forEach(el => {
        const batchId = String(el.dataset.batchId || '');
        const batch = thArchivePreviewState.batches.find(item => String(item.archiveBatchId || item.id || '') === batchId);
        el.disabled = !!isBusy
            || !thArchiveCenterCanExecute(currentRoles)
            || !thArchiveIsPilotExecutionCollection(batch?.collection)
            || !thArchiveBatchPilotScopeAllowed(batch)
            || String(batch?.status || '').toLowerCase() !== 'archived';
    });
    if (isBusy) {
        thArchiveSetWriteActionsDisabled();
    } else {
        thArchiveUpdatePolicyControls();
        thArchiveUpdateSelectionState();
        thArchiveUpdatePairApprovalState();
        thArchiveUpdatePairFinalArchiveState();
        thArchiveUpdatePreGoLiveArchiveState();
    }
}

function thArchiveResetPreviewResults() {
    thArchivePreviewState.selectedRows = new Map();
    thArchivePreviewState.currentRows = [];
    thArchivePreviewState.lastResult = null;
    thArchiveSetText('thArchiveCandidateCount', '--');
    thArchiveSetText('thArchiveExcludedCount', '--');
    thArchiveSetText('thArchiveManualReviewCount', '--');
    thArchiveSetText('thArchiveHighRiskCount', '--');
    thArchiveSetText('thArchiveManifestHash', '--');
    thArchiveSetText('thArchiveRecordCount', '--');
    thArchiveSetText('thArchiveGeneratedAt', '--');
    const summary = document.getElementById('thArchiveCollectionsSummary');
    if (summary) summary.innerHTML = 'Run a preview to see scanned, candidate, excluded, manual review, and high-risk counts by collection.';
    const rows = document.getElementById('thArchiveManifestRows');
    if (rows) rows.innerHTML = '<tr><td colspan="7" style="padding:14px; color:#777;">No preview loaded.</td></tr>';
    thArchiveSetText('thArchiveManualReviewSummary', 'Records needing human review will appear here after preview.');
    thArchiveSetText('thArchiveHighRiskSummary', 'Receipt, gift card, client, and group booking risks will be listed here before any archive approval.');
    thArchiveSetText('thArchivePageInfo', 'Page 1');
    thArchiveUpdateSelectionState();
}

function thArchiveSelectedCollections() {
    const policy = thArchiveSelectedPolicy();
    const allowed = thArchivePolicyAllowedCollections(policy);
    const selected = String(document.getElementById('thArchiveCollection')?.value || 'all').trim();
    if (!allowed.length) return [];
    if (!selected || selected === 'all') return allowed.slice();
    return allowed.includes(selected) ? [selected] : allowed.slice();
}

function thArchiveReadBasePayload() {
    const policy = thArchiveSelectedPolicy();
    const dateFrom = String(document.getElementById('thArchiveFrom')?.value || '').trim();
    const dateTo = String(document.getElementById('thArchiveTo')?.value || '').trim();
    const reason = String(policy.reason || policy.id || 'pre_go_live_test_data').trim();
    if (!dateFrom || !dateTo) {
        throw new Error('Choose both From and To dates before previewing.');
    }
    if (dateFrom > dateTo) {
        throw new Error('From date must be before or equal to To date.');
    }
    if (!policy.previewEnabled) {
        throw new Error(`${policy.label} is not connected to read-only preview in this phase. Use Pre-Go-Live Cleanup for the current Archive Center preview.`);
    }
    const collections = thArchiveSelectedCollections();
    if (!collections.length) {
        throw new Error(`${policy.label} does not enable any preview collections in this phase.`);
    }
    return {
        dateFrom,
        dateTo,
        collections,
        reason,
        previewOnly: true,
        pageSize: TH_ARCHIVE_PREVIEW_PAGE_SIZE,
        summaryOnly: false
    };
}

