function thDa5a2bIsStagingHarnessRuntime() {
    try {
        const projectId = String(window.THURAYA_CONFIG?.projectId || firebase.app()?.options?.projectId || '').trim();
        const env = String(window.THURAYA_ENV || '').trim().toLowerCase();
        return projectId === TH_DA5A2B_STAGING_PREFLIGHT_HARNESS.projectId || env === 'staging';
    } catch (error) {
        return false;
    }
}

function thDa5a2bMaskEmail(email) {
    const safe = String(email || '').trim().toLowerCase();
    const parts = safe.split('@');
    if (parts.length !== 2) return safe ? '[masked]' : '';
    const [name, domain] = parts;
    const maskedName = name.length <= 1 ? '*' : `${name.charAt(0)}***`;
    return `${maskedName}@${domain}`;
}

function thDa5a2bApprovalExpectedFields() {
    const h = TH_DA5A2B_STAGING_PREFLIGHT_HARNESS;
    return {
        approvalId: h.approvalId,
        status: 'approved',
        scope: h.scope,
        harnessScope: h.harnessScope,
        harnessMode: h.harnessMode,
        policyId: h.policyId,
        cutoffDate: h.cutoffDate,
        executionEnvironment: 'staging',
        projectId: h.projectId,
        manifestHash: h.manifestHash,
        manifestGeneratedAt: h.generatedAt,
        targetCount: h.targetCount,
        activeJobsTargetCount: h.activeJobsTargetCount,
        appointmentsTargetCount: h.appointmentsTargetCount,
        attendanceTargetCount: h.attendanceTargetCount,
        alreadyArchivedPreGoLiveCount: h.alreadyArchivedPreGoLiveCount,
        protectedPostGoLiveCount: h.protectedPostGoLiveCount,
        approvalPhrase: 'DA-5A-2B STAGING PREFLIGHT ONLY',
        rollbackConfirmed: true,
        csvManifestRetained: true,
        jsonManifestRetained: true,
        receiptImpactAccepted: true,
        clientHistoryImpactAccepted: true,
        commissionImpactAccepted: true,
        linkedAppointmentFallbackAccepted: true,
        readOnlyHarness: true,
        archiveExecutionEnabled: false,
        rollbackExecutionEnabled: false
    };
}

function thDa5a2bApprovalMismatches(data) {
    const expected = thDa5a2bApprovalExpectedFields();
    return Object.keys(expected).filter(key => {
        const expectedValue = expected[key];
        const actualValue = data ? data[key] : undefined;
        if (typeof expectedValue === 'number') {
            return Number(actualValue) !== expectedValue;
        }
        if (typeof expectedValue === 'boolean') {
            return actualValue !== expectedValue;
        }
        return String(actualValue || '') !== String(expectedValue || '');
    });
}

async function thDa5a2bReadUserProfile(user) {
    const email = String(user?.email || '').trim().toLowerCase();
    if (!email) throw new Error('Signed-in user email is required.');
    let snap = await db.collection('Users').doc(email).get();
    if (!snap.exists && user?.email && user.email !== email) {
        snap = await db.collection('Users').doc(user.email).get();
    }
    if (!snap.exists) {
        throw new Error('Signed-in user profile was not found in Users.');
    }
    const data = snap.data() || {};
    const roles = [];
    if (Array.isArray(currentRoles)) roles.push(...currentRoles);
    if (Array.isArray(data.roles)) roles.push(...data.roles);
    if (data.role) roles.push(data.role);
    if (data.roleString) {
        roles.push(...String(data.roleString).split(',').map(item => item.trim()).filter(Boolean));
    }
    return {
        email,
        maskedEmail: thDa5a2bMaskEmail(email),
        roles,
        exactSystemAdmin: thArchiveHasExactSystemAdminRole(roles)
    };
}

async function thDa5a2bCreateOrVerifyApprovalRecord(userProfile) {
    const h = TH_DA5A2B_STAGING_PREFLIGHT_HARNESS;
    const ref = db.collection('Archive_Execution_Approvals').doc(h.approvalId);
    const snap = await ref.get();
    if (snap.exists) {
        const data = snap.data() || {};
        const mismatches = thDa5a2bApprovalMismatches(data);
        if (mismatches.length) {
            const now = firebase.firestore.FieldValue.serverTimestamp();
            await ref.set({
                ...thDa5a2bApprovalExpectedFields(),
                updatedAt: now,
                updatedBy: userProfile.email,
                migrationNote: 'DA-5A-2E updated staging harness approval to retained post-archive certification expectations.'
            }, { merge: true });
        }
        return {
            approvalId: h.approvalId,
            created: false,
            verified: true,
            updated: mismatches.length > 0,
            updatedFields: mismatches,
            scope: data.scope,
            harnessScope: data.harnessScope,
            harnessMode: mismatches.length ? h.harnessMode : data.harnessMode
        };
    }

    const now = firebase.firestore.FieldValue.serverTimestamp();
    const record = {
        ...thDa5a2bApprovalExpectedFields(),
        approverName: currentUserName || firebase.auth().currentUser?.displayName || 'System Admin',
        approverEmail: userProfile.email,
        approvedAt: now,
        createdAt: now,
        createdBy: userProfile.email,
        updatedAt: now,
        updatedBy: userProfile.email,
        reviewNotes: 'DA-5A-2E staging-only post_archive_certification preflight harness approval. This record enables read-only retained-state preflight validation only; archive execution remains disabled.'
    };
    await ref.set(record, { merge: false });
    return {
        approvalId: h.approvalId,
        created: true,
        verified: true,
        scope: record.scope,
        harnessScope: record.harnessScope,
        harnessMode: record.harnessMode
    };
}

async function thDa5a2bArchiveBatchIds() {
    const snap = await db.collection('Archive_Batches').get();
    const ids = [];
    snap.forEach(doc => ids.push(doc.id));
    return ids.sort();
}

async function thDa5a2bSourceArchiveMarkerCounts() {
    const collections = ['Active_Jobs', 'Appointments', 'Attendance'];
    const result = {};
    for (const collection of collections) {
        const snap = await db.collection(collection).get();
        let archivedTrue = 0;
        let withArchiveBatchId = 0;
        snap.forEach(doc => {
            const row = doc.data() || {};
            if (row.archived === true) archivedTrue += 1;
            if (String(row.archiveBatchId || '').trim()) withArchiveBatchId += 1;
        });
        result[collection] = { total: snap.size, archivedTrue, withArchiveBatchId };
    }
    return result;
}

function thDa5a2bSummarizePreflight(data) {
    return {
        ok: data?.ok === true,
        mode: data?.mode || '',
        readOnly: data?.readOnly === true,
        firestoreWrites: thArchiveNumber(data?.firestoreWrites, -1),
        firestoreDeletes: thArchiveNumber(data?.firestoreDeletes, -1),
        executionEnabled: data?.executionEnabled === true,
        executable: data?.executable === true,
        errorCode: data?.errorCode || '',
        reasonCodes: Array.isArray(data?.reasons) ? data.reasons.map(reason => reason?.code || '').filter(Boolean) : [],
        environment: data?.checks?.environment || '',
        harnessMode: data?.checks?.stagingHarnessMode || '',
        currentPreview: data?.currentPreview || {},
        approval: {
            approvalId: data?.approval?.approvalId || '',
            status: data?.approval?.status || '',
            scope: data?.approval?.scope || '',
            projectId: data?.approval?.projectId || '',
            targetCount: data?.approval?.targetCount || 0,
            activeJobsTargetCount: data?.approval?.activeJobsTargetCount || 0,
            appointmentsTargetCount: data?.approval?.appointmentsTargetCount || 0,
            attendanceTargetCount: data?.approval?.attendanceTargetCount || 0,
            protectedPostGoLiveCount: data?.approval?.protectedPostGoLiveCount || 0
        }
    };
}

function thDa5a2bSummarizeExecuteDisabled(data) {
    return {
        ok: data?.ok === true,
        mode: data?.mode || '',
        readOnly: data?.readOnly === true,
        firestoreWrites: thArchiveNumber(data?.firestoreWrites, -1),
        firestoreDeletes: thArchiveNumber(data?.firestoreDeletes, -1),
        executionEnabled: data?.executionEnabled === true,
        executable: data?.executable === true,
        errorCode: data?.errorCode || '',
        reasonCodes: Array.isArray(data?.reasons) ? data.reasons.map(reason => reason?.code || '').filter(Boolean) : []
    };
}

async function thDa5a2bRunPreflightHarness(options = {}) {
    if (!thDa5a2bIsStagingHarnessRuntime()) {
        throw new Error('DA-5A-2D harness is available only on thuraya-staging.');
    }
    const user = firebase.auth().currentUser;
    if (!user) throw new Error('Sign in is required before running the DA-5A-2D harness.');
    const userProfile = await thDa5a2bReadUserProfile(user);
    if (!userProfile.exactSystemAdmin) {
        throw new Error('Exact System Admin role is required for the DA-5A-2D harness.');
    }
    await thApprovalPinLoadFunctionsSdk();
    const functionsService = firebase.app && firebase.app().functions
        ? firebase.app().functions(TH_APPROVAL_PIN_FUNCTIONS_REGION)
        : firebase.functions(TH_APPROVAL_PIN_FUNCTIONS_REGION);
    const fn = functionsService.httpsCallable(TH_ARCHIVE_PRODUCTION_PREFLIGHT_FUNCTION);

    const archiveBatchesBefore = await thDa5a2bArchiveBatchIds();
    const sourceMarkersBefore = await thDa5a2bSourceArchiveMarkerCounts();
    const approval = await thDa5a2bCreateOrVerifyApprovalRecord(userProfile);
    const h = TH_DA5A2B_STAGING_PREFLIGHT_HARNESS;
    const preflight = await fn({
        mode: 'preflight',
        approvalId: h.approvalId,
        policyId: h.policyId,
        cutoffDate: h.cutoffDate,
        manifestHash: h.manifestHash,
        generatedAt: h.generatedAt,
        expectedCount: h.targetCount
    });
    const preflightResult = thDa5a2bSummarizePreflight(preflight && preflight.data ? preflight.data : {});

    let executeDisabledResult = null;
    if (options.testExecuteDisabled !== false) {
        const executeDisabled = await fn({
            mode: 'execute',
            approvalId: h.approvalId,
            policyId: h.policyId,
            cutoffDate: h.cutoffDate,
            manifestHash: h.manifestHash,
            generatedAt: h.generatedAt,
            expectedCount: h.targetCount
        });
        executeDisabledResult = thDa5a2bSummarizeExecuteDisabled(executeDisabled && executeDisabled.data ? executeDisabled.data : {});
    }

    const archiveBatchesAfter = await thDa5a2bArchiveBatchIds();
    const sourceMarkersAfter = await thDa5a2bSourceArchiveMarkerCounts();
    const archiveBatchesUnchanged = JSON.stringify(archiveBatchesBefore) === JSON.stringify(archiveBatchesAfter);
    const sourceMarkersUnchanged = JSON.stringify(sourceMarkersBefore) === JSON.stringify(sourceMarkersAfter);
    const result = {
        ok: true,
        harness: 'DA-5A-2D staging preflight harness',
        projectId: String(window.THURAYA_CONFIG?.projectId || firebase.app()?.options?.projectId || ''),
        environment: String(window.THURAYA_ENV || ''),
        user: { email: userProfile.maskedEmail, exactSystemAdmin: userProfile.exactSystemAdmin },
        approval,
        preflight: preflightResult,
        executeDisabled: executeDisabledResult,
        safety: {
            archiveBatchesBefore: archiveBatchesBefore.length,
            archiveBatchesAfter: archiveBatchesAfter.length,
            archiveBatchesUnchanged,
            sourceMarkersUnchanged,
            sourceMarkersBefore,
            sourceMarkersAfter,
            firestoreWritesFromCallable: preflightResult.firestoreWrites,
            firestoreDeletesFromCallable: preflightResult.firestoreDeletes,
            archiveExecuted: false,
            rollbackExecuted: false
        }
    };
    console.log('DA-5A-2D staging preflight harness result (sanitized):', result);
    return result;
}

// DA-5A-2D staging-only hidden console harness. This creates/verifies one
// approval test record and calls preflight only; it never exposes execute,
// rollback, Archive_Batches creation, source mutation, or token material.
if (thDa5a2bIsStagingHarnessRuntime()) {
    window.thDa5a2bRunPreflightHarness = thDa5a2bRunPreflightHarness;
} else if (window.thDa5a2bRunPreflightHarness) {
    delete window.thDa5a2bRunPreflightHarness;
}

async function thArchiveCallPairedReview() {
    const user = firebase.auth().currentUser;
    if (!user) throw new Error('Sign in is required.');
    if (!thArchiveCenterCanShow(currentRoles)) {
        throw new Error('System Admin access is required.');
    }
    await thApprovalPinLoadFunctionsSdk();
    const functionsService = firebase.app && firebase.app().functions
        ? firebase.app().functions(TH_APPROVAL_PIN_FUNCTIONS_REGION)
        : firebase.functions(TH_APPROVAL_PIN_FUNCTIONS_REGION);
    const fn = functionsService.httpsCallable(TH_ARCHIVE_PAIR_REVIEW_FUNCTION);
    const result = await fn({
        activeJobId: TH_ARCHIVE_PAIR_REVIEW_TARGET.activeJobId,
        appointmentId: TH_ARCHIVE_PAIR_REVIEW_TARGET.appointmentId
    });
    return result && result.data ? result.data : {};
}

async function thArchiveLoadPairApprovalStatus() {
    if (!db || !thArchiveCenterCanShow(currentRoles)) return null;
    const snap = await db.collection('Archive_Review_Approvals').doc(TH_ARCHIVE_PAIR_APPROVAL_ID).get();
    if (!snap.exists) {
        thArchivePreviewState.pairedApprovalStatus = null;
        return null;
    }
    const data = snap.data() || {};
    const status = { id: snap.id, ...data };
    thArchivePreviewState.pairedApprovalStatus = status;
    return status;
}

function thArchivePairDeltaMatches(value, expected) {
    const num = Number(value);
    return Number.isFinite(num) && Math.abs(num - expected) <= 0.005;
}

function thArchivePairDeltasMatch(result) {
    const deltas = result?.expectedDeltas || {};
    return thArchivePairDeltaMatches(deltas.netRevenue, TH_ARCHIVE_PAIR_EXPECTED_DELTAS.netRevenue)
        && thArchivePairDeltaMatches(deltas.tax, TH_ARCHIVE_PAIR_EXPECTED_DELTAS.tax)
        && thArchivePairDeltaMatches(deltas.paidAmount, TH_ARCHIVE_PAIR_EXPECTED_DELTAS.paidAmount)
        && thArchivePairDeltaMatches(deltas.commission, TH_ARCHIVE_PAIR_EXPECTED_DELTAS.commission)
        && thArchivePairDeltaMatches(deltas.completedJobs, TH_ARCHIVE_PAIR_EXPECTED_DELTAS.completedJobs);
}

function thArchivePairApprovalDeltasMatch(approval) {
    return thArchivePairDeltaMatches(approval?.expectedNetDelta, TH_ARCHIVE_PAIR_EXPECTED_DELTAS.netRevenue)
        && thArchivePairDeltaMatches(approval?.expectedTaxDelta, TH_ARCHIVE_PAIR_EXPECTED_DELTAS.tax)
        && thArchivePairDeltaMatches(approval?.expectedPaidDelta, TH_ARCHIVE_PAIR_EXPECTED_DELTAS.paidAmount)
        && thArchivePairDeltaMatches(approval?.expectedCommissionDelta, TH_ARCHIVE_PAIR_EXPECTED_DELTAS.commission)
        && thArchivePairDeltaMatches(approval?.expectedCompletedJobsDelta, TH_ARCHIVE_PAIR_EXPECTED_DELTAS.completedJobs);
}

function thArchivePairApprovalMatchesApproved(approval = thArchivePreviewState.pairedApprovalStatus) {
    return !!approval
        && String(approval.id || '') === TH_ARCHIVE_PAIR_APPROVAL_ID
        && String(approval.status || '').toLowerCase() === 'approved'
        && String(approval.scope || '') === 'real_active_job_paired_appointment_pilot'
        && String(approval.targetCollection || '') === 'Active_Jobs'
        && String(approval.targetDocId || '') === TH_ARCHIVE_PAIR_REVIEW_TARGET.activeJobId
        && String(approval.linkedAppointmentId || '') === TH_ARCHIVE_PAIR_REVIEW_TARGET.appointmentId
        && String(approval.linkedClientId || '') === TH_ARCHIVE_PAIR_REVIEW_TARGET.clientId
        && thArchivePairApprovalDeltasMatch(approval);
}

function thArchivePairReviewTargetsUnarchived(review = thArchivePreviewState.pairedReviewResult) {
    return !!review
        && String(review?.activeJob?.docId || '') === TH_ARCHIVE_PAIR_REVIEW_TARGET.activeJobId
        && String(review?.appointment?.docId || '') === TH_ARCHIVE_PAIR_REVIEW_TARGET.appointmentId
        && review?.activeJob?.archived !== true
        && review?.appointment?.archived !== true;
}

function thArchiveResetPairApprovalForm() {
    const form = document.getElementById('thArchivePairApprovalForm');
    const notes = document.getElementById('thArchivePairReviewNotes');
    const result = document.getElementById('thArchivePairApprovalResult');
    if (form) form.style.display = 'none';
    if (notes) notes.value = '';
    document.querySelectorAll('.th-archive-pair-approval-check').forEach(el => { el.checked = false; });
    if (result) result.innerHTML = '';
    thArchivePreviewState.pairedApprovalResult = null;
    thArchivePreviewState.pairedApprovalStatus = null;
    thArchiveResetPairFinalArchiveForm();
    thArchiveUpdatePairApprovalState();
}

function thArchivePairApprovalChecks() {
    return {
        linkedAppointmentReviewed: document.getElementById('thArchivePairLinkedAppointmentReviewed')?.checked === true,
        linkedClientReviewed: document.getElementById('thArchivePairLinkedClientReviewed')?.checked === true,
        postGoLiveImpactReviewed: document.getElementById('thArchivePairPostGoLiveReviewed')?.checked === true,
        fallbackRiskAccepted: document.getElementById('thArchivePairFallbackRiskAccepted')?.checked === true,
        expectedFinancialDeltaAccepted: document.getElementById('thArchivePairExpectedDeltaAccepted')?.checked === true
    };
}

function thArchivePairApprovalReady() {
    const review = thArchivePreviewState.pairedReviewResult;
    const notes = String(document.getElementById('thArchivePairReviewNotes')?.value || '').trim();
    const checks = thArchivePairApprovalChecks();
    return thArchiveCenterCanExecute(currentRoles)
        && !!review
        && review?.readOnly === true
        && thArchiveNumber(review?.firestoreWrites, 0) === 0
        && thArchiveNumber(review?.firestoreDeletes, 0) === 0
        && review?.eligibility?.eligible === true
        && thArchivePairDeltasMatch(review)
        && !thArchivePreviewState.pairedApprovalResult?.approvalId
        && !thArchivePairApprovalMatchesApproved()
        && !!notes
        && checks.linkedAppointmentReviewed
        && checks.linkedClientReviewed
        && checks.postGoLiveImpactReviewed
        && checks.fallbackRiskAccepted
        && checks.expectedFinancialDeltaAccepted;
}

function thArchiveUpdatePairApprovalState() {
    const form = document.getElementById('thArchivePairApprovalForm');
    const button = document.getElementById('thArchivePairCreateApprovalBtn');
    const summary = document.getElementById('thArchivePairApprovalSummary');
    const review = thArchivePreviewState.pairedReviewResult;
    if (!form || !button) return;

    const canShow = !!review;
    form.style.display = canShow ? 'block' : 'none';
    const ready = thArchivePairApprovalReady();
    button.disabled = !ready;
    button.style.background = ready ? 'var(--primary)' : '#9ca3af';

    if (summary) {
        if (!canShow) {
            summary.textContent = 'Load the paired review before approval can be prepared.';
        } else if (!thArchiveCenterCanExecute(currentRoles)) {
            summary.textContent = 'Only exact System Admin can create the approval record.';
        } else if (review?.readOnly !== true || thArchiveNumber(review?.firestoreWrites, 0) !== 0 || thArchiveNumber(review?.firestoreDeletes, 0) !== 0) {
            summary.textContent = 'Approval requires a read-only paired review with zero writes and zero deletes.';
        } else if (review?.eligibility?.eligible !== true) {
            summary.textContent = 'This pair is not eligible for approval creation.';
        } else if (!thArchivePairDeltasMatch(review)) {
            summary.textContent = 'Expected financial deltas do not match the approved DA-3H target.';
        } else if (thArchivePairApprovalMatchesApproved()) {
            summary.textContent = `Existing approval ${TH_ARCHIVE_PAIR_APPROVAL_ID} is approved. Use the Final Retained Archive section below.`;
        } else if (thArchivePreviewState.pairedApprovalResult?.approvalId) {
            summary.textContent = 'Approval record has been prepared. No archive or rollback has run.';
        } else if (!String(document.getElementById('thArchivePairReviewNotes')?.value || '').trim()) {
            summary.textContent = 'Enter reviewer notes and complete every safety confirmation.';
        } else if (!Object.values(thArchivePairApprovalChecks()).every(Boolean)) {
            summary.textContent = 'Complete every safety confirmation before approval creation is enabled.';
        } else {
            summary.textContent = 'Approval creation is ready. This will create an approval record only; it will not archive or rollback records.';
        }
    }
}

function thArchiveResetPairFinalArchiveForm() {
    const section = document.getElementById('thArchivePairFinalArchiveSection');
    const confirmation = document.getElementById('thArchivePairFinalConfirmation');
    const result = document.getElementById('thArchivePairFinalArchiveResult');
    if (section) section.style.display = 'none';
    if (confirmation) confirmation.value = '';
    if (result) result.innerHTML = '';
    thArchivePreviewState.pairedFinalArchiveResult = null;
    thArchiveUpdatePairFinalArchiveState();
}

function thArchivePairFinalConfirmationText() {
    return String(document.getElementById('thArchivePairFinalConfirmation')?.value || '').trim();
}

function thArchivePairFinalArchiveReady() {
    const review = thArchivePreviewState.pairedReviewResult;
    return thArchiveCenterCanExecute(currentRoles)
        && !!review
        && review?.readOnly === true
        && thArchiveNumber(review?.firestoreWrites, 0) === 0
        && thArchiveNumber(review?.firestoreDeletes, 0) === 0
        && review?.eligibility?.eligible === true
        && thArchivePairDeltasMatch(review)
        && thArchivePairReviewTargetsUnarchived(review)
        && thArchivePairApprovalMatchesApproved()
        && thArchivePairFinalConfirmationText() === TH_ARCHIVE_PAIR_FINAL_CONFIRMATION
        && !thArchivePreviewState.pairedFinalArchiveResult?.archiveBatchId;
}

function thArchivePairFinalArchivePayload() {
    return {
        approvalId: TH_ARCHIVE_PAIR_APPROVAL_ID,
        activeJobId: TH_ARCHIVE_PAIR_REVIEW_TARGET.activeJobId,
        appointmentId: TH_ARCHIVE_PAIR_REVIEW_TARGET.appointmentId,
        confirmationText: TH_ARCHIVE_PAIR_FINAL_CONFIRMATION
    };
}

function thArchiveUpdatePairFinalArchiveState() {
    const section = document.getElementById('thArchivePairFinalArchiveSection');
    const button = document.getElementById('thArchivePairFinalArchiveBtn');
    const summary = document.getElementById('thArchivePairFinalArchiveSummary');
    const review = thArchivePreviewState.pairedReviewResult;
    if (!section || !button) return;

    const canShow = !!review;
    section.style.display = canShow ? 'block' : 'none';
    const ready = thArchivePairFinalArchiveReady();
    button.disabled = !ready;
    button.style.background = ready ? 'var(--error)' : '#9ca3af';

    if (summary) {
        if (!canShow) {
            summary.textContent = 'Load the paired review before final archive can be evaluated.';
        } else if (!thArchiveCenterCanExecute(currentRoles)) {
            summary.textContent = 'Only exact System Admin can execute the final retained archive.';
        } else if (review?.readOnly !== true || thArchiveNumber(review?.firestoreWrites, 0) !== 0 || thArchiveNumber(review?.firestoreDeletes, 0) !== 0) {
            summary.textContent = 'Final archive requires a read-only paired review with zero writes and zero deletes.';
        } else if (review?.eligibility?.eligible !== true) {
            summary.textContent = 'This pair is not currently eligible for final archive.';
        } else if (!thArchivePairReviewTargetsUnarchived(review)) {
            summary.textContent = 'Both paired records must be currently unarchived before final archive.';
        } else if (!thArchivePairDeltasMatch(review)) {
            summary.textContent = 'Expected financial deltas do not match the approved DA-3H target.';
        } else if (!thArchivePairApprovalMatchesApproved()) {
            summary.textContent = `Approval ${TH_ARCHIVE_PAIR_APPROVAL_ID} must exist, be approved, and match this exact pair.`;
        } else if (thArchivePreviewState.pairedFinalArchiveResult?.archiveBatchId) {
            summary.textContent = `Final archive completed as ${thArchivePreviewState.pairedFinalArchiveResult.archiveBatchId}. Rollback remains available but has not been executed.`;
        } else if (thArchivePairFinalConfirmationText() !== TH_ARCHIVE_PAIR_FINAL_CONFIRMATION) {
            summary.textContent = `Type ${TH_ARCHIVE_PAIR_FINAL_CONFIRMATION} exactly to enable the final archive button.`;
        } else {
            summary.textContent = 'Final archive execution path is armed for this approved pair only. Clicking the button will archive the Active Job and linked Appointment.';
        }
    }
}

function thArchiveRenderPairFinalArchiveResult(result) {
    const container = document.getElementById('thArchivePairFinalArchiveResult');
    if (!container) return;
    container.innerHTML = `
        <div style="border:1px solid #b8e0c2; background:#f0fff4; color:#1f6f3b; border-radius:8px; padding:10px 12px; font-size:0.84rem; margin-top:10px;">
            <strong>Final retained archive completed.</strong><br>
            Archive Batch ID: <span style="font-family:monospace;">${thArchiveEscape(result?.archiveBatchId || '--')}</span><br>
            Archived Count: ${thArchiveCount(result?.archivedCount)}<br>
            Failed Count: ${thArchiveCount(result?.failedCount)}<br>
            Firestore Deletes: ${thArchiveCount(result?.firestoreDeletes)}<br>
            Source Records Deleted: ${result?.sourceRecordsDeleted === true ? 'true' : 'false'}<br>
            Rollback remains available through Archive Batch History.
        </div>
    `;
}

function thArchivePairApprovalPayload() {
    const notes = String(document.getElementById('thArchivePairReviewNotes')?.value || '').trim();
    return {
        activeJobId: TH_ARCHIVE_PAIR_REVIEW_TARGET.activeJobId,
        appointmentId: TH_ARCHIVE_PAIR_REVIEW_TARGET.appointmentId,
        linkedClientId: TH_ARCHIVE_PAIR_REVIEW_TARGET.clientId,
        reviewNotes: notes,
        linkedAppointmentReviewed: true,
        linkedClientReviewed: true,
        postGoLiveImpactReviewed: true,
        fallbackRiskAccepted: true,
        riskAccepted: true,
        expectedNetDelta: TH_ARCHIVE_PAIR_EXPECTED_DELTAS.netRevenue,
        expectedTaxDelta: TH_ARCHIVE_PAIR_EXPECTED_DELTAS.tax,
        expectedPaidDelta: TH_ARCHIVE_PAIR_EXPECTED_DELTAS.paidAmount,
        expectedCommissionDelta: TH_ARCHIVE_PAIR_EXPECTED_DELTAS.commission,
        expectedCompletedJobsDelta: TH_ARCHIVE_PAIR_EXPECTED_DELTAS.completedJobs
    };
}

function thArchiveRenderPairApprovalResult(result) {
    const container = document.getElementById('thArchivePairApprovalResult');
    if (!container) return;
    container.innerHTML = `
        <div style="border:1px solid #b8e0c2; background:#f0fff4; color:#1f6f3b; border-radius:8px; padding:10px 12px; font-size:0.84rem; margin-top:10px;">
            <strong>Approval prepared.</strong><br>
            Approval ID: <span style="font-family:monospace;">${thArchiveEscape(result?.approvalId || '--')}</span><br>
            Status: approved<br>
            Approved By: ${thArchiveEscape(currentUserEmail || '--')}<br>
            Approved At: ${thArchiveEscape(new Date().toLocaleString())}<br>
            Archive Executed: ${result?.archiveExecuted === true ? 'true' : 'false'}
        </div>
    `;
}

function thArchiveRenderPairRecord(title, record) {
    if (!record) {
        return `
            <div style="border:1px solid var(--border); border-radius:8px; padding:12px; background:#fff;">
                <strong style="color:var(--primary);">${thArchiveEscape(title)}</strong>
                <p style="margin:8px 0 0; color:#7a2d20;">Record not returned.</p>
            </div>
        `;
    }
    const rows = [
        ['Collection', record.collection],
        ['Document ID', record.docId],
        ['Business Date', record.businessDate],
        ['Status', record.status],
        ['Payment Status', record.paymentStatus],
        ['Client', record.clientName],
        ['Phone', record.clientPhone],
        ['Service', record.service],
        ['Technician', record.assignedTechName || record.assignedTechEmail],
        ['Booked Price', thArchiveMoney(record.bookedPrice)],
        ['Grand Total', thArchiveMoney(window.thFinancialEvidence.read(record).gross)],
        ['Paid Amount', thArchiveMoney(window.thFinancialEvidence.read(record).paid)],
        ['Receipt Ref', record.receiptRef || '--'],
        ['Group ID', record.groupId || '--'],
        ['Archived', record.archived === true ? 'true' : 'false'],
        ['Source Appointment', record.sourceAppointmentId || '--']
    ];
    return `
        <div style="border:1px solid var(--border); border-radius:8px; padding:12px; background:#fff;">
            <strong style="display:block; color:var(--primary); margin-bottom:8px;">${thArchiveEscape(title)}</strong>
            <table style="width:100%; border-collapse:collapse; font-size:0.8rem;">
                <tbody>
                    ${rows.map(([label, value]) => `
                        <tr>
                            <td style="padding:6px 8px 6px 0; color:#777; border-bottom:1px solid #f1f1f1; width:34%;">${thArchiveEscape(label)}</td>
                            <td style="padding:6px 0; color:#333; border-bottom:1px solid #f1f1f1; word-break:break-word;">${thArchiveEscape(value ?? '--')}</td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>
        </div>
    `;
}

function thArchiveRenderPairClient(client) {
    if (!client) return '<p style="font-size:0.84rem; color:#7a2d20; margin:0;">Linked Client was not returned.</p>';
    return `
        <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(160px,1fr)); gap:10px; font-size:0.82rem;">
            <div><strong>Client ID</strong><br>${thArchiveEscape(client.docId || TH_ARCHIVE_PAIR_REVIEW_TARGET.clientId)}</div>
            <div><strong>Name</strong><br>${thArchiveEscape(client.name || '--')}</div>
            <div><strong>Phone</strong><br>${thArchiveEscape(client.phone || '--')}</div>
            <div><strong>Email</strong><br>${thArchiveEscape(client.email || '--')}</div>
        </div>
    `;
}

function thArchiveRenderPairReview(result) {
    const container = document.getElementById('thArchivePairedReviewResult');
    if (!container) return;
    thArchivePreviewState.pairedReviewResult = result || null;
    const deltas = result?.expectedDeltas || {};
    const eligibility = result?.eligibility || {};
    const warnings = Array.isArray(result?.warnings) ? result.warnings : [];
    const fallbackWarnings = Array.isArray(result?.fallbackRiskSummary) ? result.fallbackRiskSummary : [];
    const allWarnings = [...fallbackWarnings, ...warnings];
    const postGoLive = result?.postGoLiveClientActivity || {};
    const writeSummary = `readOnly: ${result?.readOnly === true ? 'true' : 'false'} | Firestore writes: ${thArchiveCount(result?.firestoreWrites)} | Firestore deletes: ${thArchiveCount(result?.firestoreDeletes)}`;

    container.innerHTML = `
        <div style="border:1px solid #b8e0c2; background:#f0fff4; color:#1f6f3b; border-radius:8px; padding:10px 12px; margin-bottom:12px; font-size:0.84rem;">
            ${thArchiveEscape(writeSummary)}
        </div>
        <div class="grid-2" style="align-items:start; margin-bottom:12px;">
            ${thArchiveRenderPairRecord('Active Job', result?.activeJob)}
            ${thArchiveRenderPairRecord('Linked Appointment', result?.appointment)}
        </div>
        <div style="border:1px solid var(--border); border-radius:8px; padding:12px; background:#fff; margin-bottom:12px;">
            <strong style="display:block; color:var(--primary); margin-bottom:8px;">Linked Client</strong>
            ${thArchiveRenderPairClient(result?.linkedClient)}
        </div>
        <div class="grid-3" style="margin-bottom:12px;">
            <div class="metric-card"><div style="font-size:0.74rem; text-transform:uppercase; color:#666;">Net Revenue Delta</div><div class="metric-value" style="font-size:1.3rem;">${thArchiveMoney(deltas.netRevenue)}</div></div>
            <div class="metric-card"><div style="font-size:0.74rem; text-transform:uppercase; color:#666;">Tax Delta</div><div class="metric-value" style="font-size:1.3rem;">${thArchiveMoney(deltas.tax)}</div></div>
            <div class="metric-card"><div style="font-size:0.74rem; text-transform:uppercase; color:#666;">Paid Amount Delta</div><div class="metric-value" style="font-size:1.3rem;">${thArchiveMoney(deltas.paidAmount)}</div></div>
            <div class="metric-card"><div style="font-size:0.74rem; text-transform:uppercase; color:#666;">Commission Delta</div><div class="metric-value" style="font-size:1.3rem;">${thArchiveMoney(deltas.commission)}</div></div>
            <div class="metric-card"><div style="font-size:0.74rem; text-transform:uppercase; color:#666;">Completed Jobs Delta</div><div class="metric-value" style="font-size:1.3rem;">${thArchiveEscape(deltas.completedJobs ?? '--')}</div></div>
            <div class="metric-card"><div style="font-size:0.74rem; text-transform:uppercase; color:#666;">Post-Go-Live Activity</div><div class="metric-value" style="font-size:1.3rem;">${thArchiveCount(postGoLive.count)}</div></div>
        </div>
        <div style="border:1px solid ${eligibility.eligible ? '#b8e0c2' : '#e5b5aa'}; background:${eligibility.eligible ? '#f0fff4' : '#fff1ef'}; color:${eligibility.eligible ? '#1f6f3b' : '#7a2d20'}; border-radius:8px; padding:12px; margin-bottom:12px;">
            <strong>Eligibility:</strong> ${eligibility.eligible ? 'Eligible for manual approval review' : 'Not eligible'}
            ${Array.isArray(eligibility.errors) && eligibility.errors.length
                ? `<ul style="margin:8px 0 0; padding-left:18px;">${eligibility.errors.map(error => `<li>${thArchiveEscape(error)}</li>`).join('')}</ul>`
                : ''}
        </div>
        <div style="border:1px solid #ead7a6; background:#fff8e5; color:#66561d; border-radius:8px; padding:12px;">
            <strong>Fallback / Reintroduction Warnings</strong>
            <ul style="margin:8px 0 0; padding-left:18px;">
                ${(allWarnings.length ? allWarnings : ['No warnings returned.']).map(item => `<li>${thArchiveEscape(item)}</li>`).join('')}
            </ul>
        </div>
    `;
    const form = document.getElementById('thArchivePairApprovalForm');
    if (form) form.style.display = 'block';
    thArchiveUpdatePairApprovalState();
    thArchiveUpdatePairFinalArchiveState();
}

window.thArchiveLoadPairedReview = async function() {
    if (!thArchiveCenterCanShow(currentRoles)) {
        thArchiveSetStatus('System Admin access is required for paired review.', 'error');
        return;
    }
    const container = document.getElementById('thArchivePairedReviewResult');
    thArchivePreviewState.pairedReviewResult = null;
    thArchiveResetPairApprovalForm();
    if (container) {
        container.innerHTML = '<p style="font-size:0.84rem; color:#777; margin:0;">Loading read-only paired review...</p>';
    }
    thArchiveSetBusy(true);
    thArchiveSetStatus('Loading read-only paired Active Job review...', 'info');
    try {
        const result = await thArchiveCallPairedReview();
        await thArchiveLoadPairApprovalStatus();
        thArchiveRenderPairReview(result);
        thArchiveSetStatus(
            `Paired review loaded. Read-only: ${result?.readOnly === true ? 'true' : 'false'}. Firestore writes: ${thArchiveCount(result?.firestoreWrites)}. Deletes: ${thArchiveCount(result?.firestoreDeletes)}.`,
            result?.eligibility?.eligible ? 'success' : 'info'
        );
    } catch (error) {
        console.warn('Paired Active Job review failed', error);
        if (container) {
            container.innerHTML = `<p style="font-size:0.84rem; color:#7a2d20; margin:0;">${thArchiveEscape(thArchiveSafeErrorMessage(error))}</p>`;
        }
        thArchiveSetStatus(thArchiveSafeErrorMessage(error), 'error');
    } finally {
        thArchiveSetBusy(false);
    }
};

window.thArchivePairApprovalInputChanged = function() {
    thArchiveUpdatePairApprovalState();
};

window.thArchivePairFinalConfirmationChanged = function() {
    thArchiveUpdatePairFinalArchiveState();
};

window.thArchiveCreatePairApproval = async function() {
    if (!thArchivePairApprovalReady()) {
        thArchiveSetStatus('Complete paired review notes and every safety confirmation before creating approval.', 'error');
        thArchiveUpdatePairApprovalState();
        return;
    }
    const resultContainer = document.getElementById('thArchivePairApprovalResult');
    if (resultContainer) {
        resultContainer.innerHTML = '<p style="font-size:0.84rem; color:#777; margin:10px 0 0;">Creating approval record only...</p>';
    }
    thArchiveSetBusy(true);
    thArchiveSetStatus('Creating paired review approval record only. No archive or rollback will run.', 'info');
    try {
        const result = await thArchiveCallExecution(TH_ARCHIVE_PAIR_APPROVAL_FUNCTION, thArchivePairApprovalPayload());
        thArchivePreviewState.pairedApprovalResult = result || null;
        thArchiveRenderPairApprovalResult(result || {});
        thArchiveSetStatus(
            `Approval record created: ${result?.approvalId || 'unknown'}. Archive executed: ${result?.archiveExecuted === true ? 'true' : 'false'}. Deletes: ${thArchiveCount(result?.firestoreDeletes)}.`,
            'success'
        );
    } catch (error) {
        console.warn('Paired approval creation failed', error);
        if (resultContainer) {
            resultContainer.innerHTML = `<p style="font-size:0.84rem; color:#7a2d20; margin:10px 0 0;">${thArchiveEscape(thArchiveSafeErrorMessage(error))}</p>`;
        }
        thArchiveSetStatus(thArchiveSafeErrorMessage(error), 'error');
    } finally {
        thArchiveSetBusy(false);
    }
};

window.thArchiveFinalArchiveApprovedPair = async function() {
    if (!thArchivePairFinalArchiveReady()) {
        thArchiveSetStatus('Final archive is not armed. Load the paired review, confirm the approved status, and type the exact confirmation.', 'error');
        thArchiveUpdatePairFinalArchiveState();
        return;
    }
    const resultContainer = document.getElementById('thArchivePairFinalArchiveResult');
    if (resultContainer) {
        resultContainer.innerHTML = '<p style="font-size:0.84rem; color:#777; margin:10px 0 0;">Executing final retained archive for the approved pair only...</p>';
    }
    thArchiveSetBusy(true);
    thArchiveSetStatus('Executing final retained archive for the approved paired records only.', 'info');
    try {
        const result = await thArchiveCallExecution(TH_ARCHIVE_PAIR_FINAL_ARCHIVE_FUNCTION, thArchivePairFinalArchivePayload());
        thArchivePreviewState.pairedFinalArchiveResult = result || {};
        thArchiveRenderPairFinalArchiveResult(result || {});
        thArchiveSetStatus(
            `Final archive completed: ${result?.archiveBatchId || 'unknown'}. Archived: ${thArchiveCount(result?.archivedCount)}. Deletes: ${thArchiveCount(result?.firestoreDeletes)}.`,
            'success'
        );
    } catch (error) {
        console.warn('Final paired archive failed', error);
        if (resultContainer) {
            resultContainer.innerHTML = `<p style="font-size:0.84rem; color:#7a2d20; margin:10px 0 0;">${thArchiveEscape(thArchiveSafeErrorMessage(error))}</p>`;
        }
        thArchiveSetStatus(thArchiveSafeErrorMessage(error), 'error');
    } finally {
        thArchiveSetBusy(false);
    }
};

function thArchiveBatchCount(batch) {
    if (!batch) return 0;
    if (Number.isFinite(Number(batch.archivedCount))) return Number(batch.archivedCount);
    if (Number.isFinite(Number(batch.requestedCount))) return Number(batch.requestedCount);
    if (Array.isArray(batch.recordIds)) return batch.recordIds.length;
    return 0;
}

function thArchiveBatchSortValue(batch) {
    const value = batch?.createdAt || batch?.completedAt || '';
    if (typeof value?.toMillis === 'function') {
        try { return value.toMillis(); } catch(e) { return 0; }
    }
    if (typeof value?.seconds === 'number') return value.seconds * 1000;
    const parsed = Date.parse(String(value || ''));
    return Number.isFinite(parsed) ? parsed : 0;
}

function thArchiveRenderBatchHistory(batches) {
    const container = document.getElementById('thArchiveBatchHistory');
    if (!container) return;
    const rows = Array.isArray(batches) ? batches : [];
    thArchivePreviewState.batches = rows;
    thArchivePreviewState.selectedBatch = null;
    if (!rows.length) {
        container.innerHTML = '<p style="font-size:0.84rem; color:#777; margin:0;">No pilot archive batches found yet.</p>';
        thArchiveUpdateRollbackState();
        return;
    }
    const canExecute = thArchiveCenterCanExecute(currentRoles);
    container.innerHTML = `
        <div style="overflow-x:auto;">
            <table style="width:100%; border-collapse:collapse; font-size:0.82rem;">
                <thead>
                    <tr style="background:#f7f4ec; color:var(--primary);">
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">Select</th>
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">Batch</th>
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">Collection</th>
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">Created</th>
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">By</th>
                        <th style="text-align:right; padding:8px; border-bottom:1px solid var(--border);">Records</th>
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">Status</th>
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">Reason</th>
                    </tr>
                </thead>
                <tbody>
                    ${rows.map(batch => {
                        const id = String(batch.archiveBatchId || batch.id || '');
                        const status = String(batch.status || '').toLowerCase();
                        const collection = thArchiveBatchDisplayCollection(batch);
                        const canRollback = canExecute && thArchiveBatchPilotScopeAllowed(batch) && status === 'archived';
                        const snapshotCount = thArchiveBatchSnapshotCount(batch);
                        return `
                            <tr>
                                <td style="padding:8px; border-bottom:1px solid var(--border);">
                                    <input type="radio"
                                        name="thArchiveBatchSelect"
                                        class="th-archive-batch-radio"
                                        data-batch-id="${thArchiveEscape(id)}"
                                        ${canRollback ? '' : 'disabled'}
                                        title="${canRollback ? 'Select for rollback' : 'Only archived pilot batches can be rolled back by System Admin'}">
                                </td>
                                <td style="padding:8px; border-bottom:1px solid var(--border);">${thArchiveEscape(id)}</td>
                                <td style="padding:8px; border-bottom:1px solid var(--border);">${thArchiveEscape(collection)}</td>
                                <td style="padding:8px; border-bottom:1px solid var(--border);">${thArchiveEscape(thArchiveDateText(batch.createdAt || batch.completedAt))}</td>
                                <td style="padding:8px; border-bottom:1px solid var(--border);">${thArchiveEscape(batch.createdBy || batch.archivedBy || '')}</td>
                                <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);" title="Snapshots/records retained for rollback">${thArchiveCount(snapshotCount)}</td>
                                <td style="padding:8px; border-bottom:1px solid var(--border);">${thArchiveEscape(batch.status || '')}</td>
                                <td style="padding:8px; border-bottom:1px solid var(--border);">${thArchiveEscape(batch.reason || batch.archiveReason || batch.policyId || '')}</td>
                            </tr>
                        `;
                    }).join('')}
                </tbody>
            </table>
        </div>
    `;
    container.querySelectorAll('.th-archive-batch-radio').forEach(input => {
        input.addEventListener('change', () => {
            const batchId = String(input.dataset.batchId || '');
            thArchivePreviewState.selectedBatch = rows.find(batch => String(batch.archiveBatchId || batch.id || '') === batchId) || null;
            thArchiveUpdateRollbackState();
        });
    });
    thArchiveUpdateRollbackState();
}

async function thArchiveLoadBatchHistory() {
    const container = document.getElementById('thArchiveBatchHistory');
    if (!container || !thArchiveCenterCanShow(currentRoles)) return;
    container.innerHTML = '<p style="font-size:0.84rem; color:#777; margin:0;">Loading pilot archive batch history...</p>';
    try {
        const snap = await db.collection('Archive_Batches').orderBy('createdAt', 'desc').limit(25).get();
        const batches = [];
        snap.forEach(doc => {
            const data = doc.data() || {};
            if (!thArchiveBatchShouldShow({ id: doc.id, ...data })) return;
            batches.push({ id: doc.id, ...data });
        });
        batches.sort((a, b) => thArchiveBatchSortValue(b) - thArchiveBatchSortValue(a));
        thArchiveRenderBatchHistory(batches);
    } catch (error) {
        console.warn('Archive batch history failed', error);
        container.innerHTML = '<p style="font-size:0.84rem; color:#7a2d20; margin:0;">Archive batch history could not be loaded. Rollback remains disabled.</p>';
        thArchivePreviewState.selectedBatch = null;
        thArchiveUpdateRollbackState();
    }
}

function thArchivePreGoLivePolicyPayload() {
    return {
        ...TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD,
        collections: TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD.collections.slice()
    };
}

function thArchivePreGoLiveTargetCount(result = thArchivePreviewState.policyPreviewResult) {
    return thArchiveNumber(result?.counts?.unarchivedTargetCount, 0);
}

function thArchivePreGoLiveAlreadyArchivedCount(result = thArchivePreviewState.policyPreviewResult) {
    return thArchiveNumber(result?.counts?.alreadyArchivedCount, 0);
}

function thArchivePreGoLiveProtectedPostGoLiveCount(result = thArchivePreviewState.policyPreviewResult) {
    return thArchiveNumber(result?.counts?.protectedPostGoLiveCount, 0);
}

function thArchivePreGoLivePostGoLiveTargetCount(result = thArchivePreviewState.policyPreviewResult) {
    const cutoffDate = String(result?.cutoffDate || TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD.cutoffDate || '').trim();
    const rows = Array.isArray(result?.targetRecords) ? result.targetRecords : [];
    if (!cutoffDate || !rows.length) return 0;
    return rows.filter(row => String(row?.businessDate || '').trim() >= cutoffDate).length;
}

function thArchivePreGoLiveCollectionTargetCount(result, collection) {
    return thArchiveNumber(result?.collectionsSummary?.[collection]?.unarchivedTargetCount, 0);
}

function thArchivePreGoLiveExpectedConfirmation(result = thArchivePreviewState.policyPreviewResult) {
    return `ARCHIVE PRE-GO-LIVE ${thArchivePreGoLiveTargetCount(result)} RECORDS`;
}

function thArchivePreGoLiveConfirmationText() {
    return String(document.getElementById('thArchivePolicyArchiveConfirmation')?.value || '').trim();
}

function thArchivePreGoLiveCollectionsMatch(result = thArchivePreviewState.policyPreviewResult) {
    const expected = TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD.collections.slice().sort();
    const returned = Array.isArray(result?.collections) ? result.collections.slice().sort() : [];
    return expected.length === returned.length && expected.every((collection, index) => collection === returned[index]);
}

function thArchivePreGoLiveArchivePayload(result = thArchivePreviewState.policyPreviewResult) {
    return {
        policyId: TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD.policyId,
        cutoffDate: TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD.cutoffDate,
        dateFrom: TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD.dateFrom,
        dateTo: TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD.dateTo,
        collections: TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD.collections.slice(),
        expectedCount: thArchivePreGoLiveTargetCount(result),
        expectedAlreadyArchivedCount: thArchivePreGoLiveAlreadyArchivedCount(result),
        confirmationText: thArchivePreGoLiveConfirmationText()
    };
}

function thArchivePreGoLiveArchiveGateResult(result = thArchivePreviewState.policyPreviewResult) {
    const reasons = [];
    const targetCount = thArchivePreGoLiveTargetCount(result);
    const targetRows = Array.isArray(result?.targetRecords) ? result.targetRecords : [];
    const postGoLiveTargetCount = thArchivePreGoLivePostGoLiveTargetCount(result);
    const expectedConfirmation = thArchivePreGoLiveExpectedConfirmation(result);

    if (!result) reasons.push('Run the owner-approved cutoff preview first.');
    if (!thArchiveCenterCanExecute(currentRoles)) reasons.push('Exact System Admin role is required.');
    if (result && result.readOnly !== true) reasons.push('Latest preview must be read-only.');
    if (result && result.previewOnly !== true) reasons.push('Latest preview must be preview-only.');
    if (result && thArchiveNumber(result.firestoreWrites, 0) !== 0) reasons.push('Latest preview reported Firestore writes.');
    if (result && thArchiveNumber(result.firestoreDeletes, 0) !== 0) reasons.push('Latest preview reported Firestore deletes.');
    if (result && String(result.policyId || '') !== TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD.policyId) reasons.push('Policy id mismatch.');
    if (result && String(result.cutoffDate || '') !== TH_ARCHIVE_PRE_GO_LIVE_POLICY_PAYLOAD.cutoffDate) reasons.push('Cutoff date mismatch.');
    if (result && !thArchivePreGoLiveCollectionsMatch(result)) reasons.push('Collection scope mismatch.');
    if (!targetCount) reasons.push('No target records are available to archive.');
    if (targetCount > TH_ARCHIVE_PRE_GO_LIVE_POLICY_MAX_TARGETS) reasons.push(`Target count exceeds ${TH_ARCHIVE_PRE_GO_LIVE_POLICY_MAX_TARGETS}.`);
    if (targetRows.length !== targetCount) reasons.push('Target record list does not match the latest preview count.');
    if (postGoLiveTargetCount !== 0) reasons.push('Post-go-live target records were detected.');
    if (thArchivePreviewState.policyExecutionResult?.archiveBatchId) reasons.push('Archive already executed from this preview. Refresh the preview before any further action.');
    if (thArchivePreGoLiveConfirmationText() !== expectedConfirmation) reasons.push(`Type exactly: ${expectedConfirmation}`);

    return {
        ready: reasons.length === 0,
        reasons,
        targetCount,
        alreadyArchivedCount: thArchivePreGoLiveAlreadyArchivedCount(result),
        protectedPostGoLiveCount: thArchivePreGoLiveProtectedPostGoLiveCount(result),
        postGoLiveTargetCount,
        expectedConfirmation
    };
}

function thArchivePolicyMetric(label, value, tone = 'var(--primary)') {
    return `
        <div class="metric-card">
            <div style="font-size:0.72rem; text-transform:uppercase; color:#666; letter-spacing:0.08em;">${thArchiveEscape(label)}</div>
            <div class="metric-value" style="font-size:1.24rem; color:${tone};">${thArchiveEscape(value)}</div>
        </div>
    `;
}

function thArchiveRenderPreGoLiveSummaryStrip(result) {
    const pairs = [
        ['readOnly', result?.readOnly === true ? 'true' : 'false'],
        ['previewOnly', result?.previewOnly === true ? 'true' : 'false'],
        ['firestoreWrites', thArchiveCount(result?.firestoreWrites)],
        ['firestoreDeletes', thArchiveCount(result?.firestoreDeletes)],
        ['policyId', result?.policyId || ''],
        ['policyLabel', result?.policyLabel || ''],
        ['scope', result?.scope || ''],
        ['cutoffDate', result?.cutoffDate || ''],
        ['generatedAt', result?.generatedAt || '']
    ];
    return `
        <div style="overflow-x:auto; margin-bottom:14px;">
            <table style="width:100%; border-collapse:collapse; font-size:0.8rem;">
                <tbody>
                    ${pairs.map(([label, value]) => `
                        <tr>
                            <td style="padding:7px 10px 7px 0; color:#777; border-bottom:1px solid #f1f1f1; width:180px;">${thArchiveEscape(label)}</td>
                            <td style="padding:7px 0; color:#333; border-bottom:1px solid #f1f1f1; word-break:break-word;">${thArchiveEscape(value || '--')}</td>
                        </tr>
                    `).join('')}
                </tbody>
            </table>
        </div>
    `;
}

function thArchiveRenderPreGoLiveCollectionsSummary(collectionsSummary) {
    const entries = Object.entries(collectionsSummary || {});
    if (!entries.length) return '<p style="font-size:0.84rem; color:#777; margin:0;">No collection summary returned.</p>';
    const totals = entries.reduce((acc, [, item]) => {
        acc.scanned += thArchiveNumber(item?.scannedCount, 0);
        acc.targets += thArchiveNumber(item?.unarchivedTargetCount, 0);
        acc.archived += thArchiveNumber(item?.alreadyArchivedCount, 0);
        acc.protected += thArchiveNumber(item?.protectedPostGoLiveCount, 0);
        acc.archivedPost += thArchiveNumber(item?.alreadyArchivedPostGoLiveCount, 0);
        acc.invalid += thArchiveNumber(item?.skippedInvalidDateCount, 0);
        acc.outside += thArchiveNumber(item?.outsideRequestedRangeCount, 0);
        return acc;
    }, { scanned: 0, targets: 0, archived: 0, protected: 0, archivedPost: 0, invalid: 0, outside: 0 });

    return `
        <div style="overflow-x:auto;">
            <table style="width:100%; border-collapse:collapse; font-size:0.8rem;">
                <thead>
                    <tr style="background:#f7f4ec; color:var(--primary);">
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">Collection</th>
                        <th style="text-align:right; padding:8px; border-bottom:1px solid var(--border);">Scanned</th>
                        <th style="text-align:right; padding:8px; border-bottom:1px solid var(--border);">Targets</th>
                        <th style="text-align:right; padding:8px; border-bottom:1px solid var(--border);">Already Archived</th>
                        <th style="text-align:right; padding:8px; border-bottom:1px solid var(--border);">Protected Post-Go-Live</th>
                        <th style="text-align:right; padding:8px; border-bottom:1px solid var(--border);">Archived Post-Go-Live</th>
                        <th style="text-align:right; padding:8px; border-bottom:1px solid var(--border);">Invalid Date</th>
                        <th style="text-align:right; padding:8px; border-bottom:1px solid var(--border);">Outside Range</th>
                    </tr>
                </thead>
                <tbody>
                    ${entries.map(([collection, item]) => `
                        <tr>
                            <td style="padding:8px; border-bottom:1px solid var(--border);">${thArchiveEscape(collection)}</td>
                            <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(item?.scannedCount)}</td>
                            <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(item?.unarchivedTargetCount)}</td>
                            <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(item?.alreadyArchivedCount)}</td>
                            <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(item?.protectedPostGoLiveCount)}</td>
                            <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(item?.alreadyArchivedPostGoLiveCount)}</td>
                            <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(item?.skippedInvalidDateCount)}</td>
                            <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(item?.outsideRequestedRangeCount)}</td>
                        </tr>
                    `).join('')}
                    <tr style="font-weight:900; color:var(--primary); background:#fffdf5;">
                        <td style="padding:8px; border-bottom:1px solid var(--border);">Total</td>
                        <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(totals.scanned)}</td>
                        <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(totals.targets)}</td>
                        <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(totals.archived)}</td>
                        <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(totals.protected)}</td>
                        <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(totals.archivedPost)}</td>
                        <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(totals.invalid)}</td>
                        <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(totals.outside)}</td>
                    </tr>
                </tbody>
            </table>
        </div>
    `;
}

function thArchiveRenderPreGoLiveFinancialImpact(financialImpact) {
    const item = financialImpact || {};
    return `
        <div class="grid-3" style="margin-bottom:0;">
            ${thArchivePolicyMetric('Net Revenue', thArchiveMoney(item.netRevenue))}
            ${thArchivePolicyMetric('Paid Amount', thArchiveMoney(item.paidAmount))}
            ${thArchivePolicyMetric('Completed Jobs', thArchiveCount(item.completedJobsCount))}
            ${thArchivePolicyMetric('Commission Estimate', thArchiveMoney(item.commissionEstimate))}
            ${thArchivePolicyMetric('Tax From TaxTotal', thArchiveMoney(item.taxFromTaxTotal))}
            ${thArchivePolicyMetric('Normalized Tax Estimate', thArchiveMoney(item.normalizedTaxEstimate))}
            ${thArchivePolicyMetric('Gross Service Value', thArchiveMoney(item.grossServiceValue))}
            ${thArchivePolicyMetric('Complimentary Waived', thArchiveMoney(item.complimentaryWaived))}
            ${thArchivePolicyMetric('Active Job Targets', thArchiveCount(item.activeJobTargetCount))}
        </div>
    `;
}

function thArchiveRenderPreGoLiveLinkedSummary(summary) {
    const item = summary || {};
    const appointmentSamples = Array.isArray(item.linkedAppointmentSamples) ? item.linkedAppointmentSamples : [];
    const clientSamples = Array.isArray(item.clientPostGoLiveActivitySamples) ? item.clientPostGoLiveActivitySamples : [];
    return `
        <div class="grid-3" style="margin-bottom:12px;">
            ${thArchivePolicyMetric('Linked Appointments', thArchiveCount(item.linkedAppointmentCount))}
            ${thArchivePolicyMetric('Linked Pre-Go-Live Appointments', thArchiveCount(item.linkedAppointmentPreGoLiveCount))}
            ${thArchivePolicyMetric('Linked Already Archived', thArchiveCount(item.linkedAppointmentAlreadyArchivedCount))}
            ${thArchivePolicyMetric('Group Linked', thArchiveCount(item.groupLinkedCount))}
            ${thArchivePolicyMetric('Receipt Linked', thArchiveCount(item.receiptLinkedCount))}
            ${thArchivePolicyMetric('Gift/Package/Promo/Split Risk', thArchiveCount(item.giftPackagePromoSplitRiskCount))}
            ${thArchivePolicyMetric('Client Post-Go-Live Activity', thArchiveCount(item.clientPostGoLiveActivityCount))}
            ${thArchivePolicyMetric('Active Jobs With Client Activity', thArchiveCount(item.activeJobTargetsWithPostGoLiveClientActivity))}
        </div>
        <div class="grid-2" style="align-items:start;">
            <div style="border:1px solid var(--border); border-radius:8px; padding:10px; background:#fff;">
                <strong style="display:block; color:var(--primary); margin-bottom:6px;">Linked Appointment Samples</strong>
                <ul style="margin:0; padding-left:18px; font-size:0.8rem; color:#555;">
                    ${(appointmentSamples.length ? appointmentSamples : [{ activeJobId: 'No samples returned.' }]).map(sample => `
                        <li>${thArchiveEscape(sample.activeJobId || '')}${sample.appointmentId ? ` -> ${thArchiveEscape(sample.appointmentId)}` : ''}${sample.appointmentBusinessDate ? ` (${thArchiveEscape(sample.appointmentBusinessDate)})` : ''}</li>
                    `).join('')}
                </ul>
            </div>
            <div style="border:1px solid var(--border); border-radius:8px; padding:10px; background:#fff;">
                <strong style="display:block; color:var(--primary); margin-bottom:6px;">Post-Go-Live Client Activity Samples</strong>
                <ul style="margin:0; padding-left:18px; font-size:0.8rem; color:#555;">
                    ${(clientSamples.length ? clientSamples : [{ docId: 'No samples returned.' }]).map(sample => `
                        <li>${thArchiveEscape(sample.targetActiveJobId || '')}${sample.collection || sample.docId ? ` -> ${thArchiveEscape(sample.collection || '')}/${thArchiveEscape(sample.docId || '')}` : ''}${sample.businessDate ? ` (${thArchiveEscape(sample.businessDate)})` : ''}</li>
                    `).join('')}
                </ul>
            </div>
        </div>
    `;
}

function thArchiveRenderPreGoLivePostProtection(summaryRows) {
    const rows = Array.isArray(summaryRows) ? summaryRows : [];
    if (!rows.length) return '<p style="font-size:0.84rem; color:#777; margin:0;">No post-go-live protection summary returned.</p>';
    return `
        <div style="overflow-x:auto;">
            <table style="width:100%; border-collapse:collapse; font-size:0.8rem;">
                <thead>
                    <tr style="background:#f7f4ec; color:var(--primary);">
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">Collection</th>
                        <th style="text-align:right; padding:8px; border-bottom:1px solid var(--border);">Protected</th>
                        <th style="text-align:right; padding:8px; border-bottom:1px solid var(--border);">Already Archived Post-Go-Live</th>
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">Archived Samples</th>
                        <th style="text-align:left; padding:8px; border-bottom:1px solid var(--border);">Warning</th>
                    </tr>
                </thead>
                <tbody>
                    ${rows.map(row => {
                        const archivedSamples = Array.isArray(row.sampleArchivedPostGoLiveRows) ? row.sampleArchivedPostGoLiveRows : [];
                        return `
                            <tr>
                                <td style="padding:8px; border-bottom:1px solid var(--border);">${thArchiveEscape(row.collection || '')}</td>
                                <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(row.protectedCount)}</td>
                                <td style="padding:8px; text-align:right; border-bottom:1px solid var(--border);">${thArchiveCount(row.alreadyArchivedPostGoLiveCount)}</td>
                                <td style="padding:8px; border-bottom:1px solid var(--border);">${archivedSamples.length
                                    ? archivedSamples.map(sample => `${thArchiveEscape(sample.collection || row.collection || '')}/${thArchiveEscape(sample.docId || '')}`).join('<br>')
                                    : '--'}</td>
                                <td style="padding:8px; border-bottom:1px solid var(--border); color:${row.warning ? '#7a2d20' : '#555'};">${thArchiveEscape(row.warning || '')}</td>
                            </tr>
                        `;
                    }).join('')}
                </tbody>
            </table>
        </div>
    `;
}

