window.thArchivePreviewNextPage = function() {
    const nextToken = thArchivePreviewState.nextPageToken;
    if (!nextToken) return;
    const nextIndex = thArchivePreviewState.pageIndex + 1;
    thArchivePreviewState.pageTokens[nextIndex] = nextToken;
    return thArchiveRunPreview(nextToken, nextIndex, true);
};

window.thArchivePreviewPreviousPage = function() {
    const previousIndex = Math.max(0, thArchivePreviewState.pageIndex - 1);
    const previousToken = thArchivePreviewState.pageTokens[previousIndex] || '';
    return thArchiveRunPreview(previousToken, previousIndex, true);
};

