window.clearFohForm = function() { 
    window.THURAYA_SELECTED_FOH_CLIENT_ID = '';
    ['f_forename', 'f_surname', 'f_tel', 'f_altTel', 'f_gender', 'f_email', 'f_dob'].forEach(id => { 
        if(document.getElementById(id)) document.getElementById(id).value = ''; 
    }); 
    if (typeof thPhoneSetRegistrationCountry === 'function') thPhoneSetRegistrationCountry('GH');
    if (typeof thPhoneResetAlternativeCountryFollow === 'function') thPhoneResetAlternativeCountryFollow();
}

window.registerClientOnly = async function() {
    const btn = document.getElementById('btnRegisterClient');
    const f_forename = document.getElementById('f_forename').value.trim(); 
    const f_surname = document.getElementById('f_surname').value.trim();
    const phoneInfo = typeof thPhoneRegistrationPhone === 'function' ? thPhoneRegistrationPhone() : null;
    const altPhoneInfo = typeof thPhoneRegistrationAlternativePhone === 'function' ? thPhoneRegistrationAlternativePhone() : null;
    const f_tel = phoneInfo?.legacyPhone || document.getElementById('f_tel').value.replace(/\D/g, '');
    const f_altTel = altPhoneInfo?.hasValue ? (altPhoneInfo.legacyPhone || document.getElementById('f_altTel').value.replace(/\D/g, '')) : '';
    const f_gender = document.getElementById('f_gender').value; 

    if(!f_forename || !f_surname || !f_tel || !f_gender) { alert("Please fill in all required fields (*)."); return; }
    if(!phoneInfo || !phoneInfo.valid) { alert(phoneInfo?.error || "Enter a valid primary telephone number."); return; }
    if(altPhoneInfo?.hasValue && !altPhoneInfo.valid) { alert(altPhoneInfo.error || "Enter a valid alternative telephone number."); return; }
    
    btn.innerText = "Saving..."; btn.disabled = true;

    try {
        const duplicateClient = typeof thPhoneFindDuplicateClient === 'function' ? await thPhoneFindDuplicateClient(phoneInfo) : null;
        const selectedClientId = window.THURAYA_SELECTED_FOH_CLIENT_ID || '';
        const duplicateId = duplicateClient?.id || duplicateClient?.Tel_Number || duplicateClient?.clientPhone || '';
        const isSelectedDuplicate = duplicateClient && selectedClientId && (
            duplicateId === selectedClientId ||
            duplicateClient.Tel_Number === selectedClientId ||
            duplicateClient.clientPhone === selectedClientId
        );
        if (duplicateClient && !isSelectedDuplicate) {
            const duplicateName = `${duplicateClient.Forename || ''} ${duplicateClient.Surname || ''}`.trim() || 'an existing client';
            if (typeof window.selectClientForFOH === 'function') window.selectClientForFOH(duplicateClient);
            alert(`This telephone number already belongs to ${duplicateName}. The existing client has been loaded instead of creating a duplicate.`);
            return;
        }

        const clientMasterData = {
            Forename: f_forename,
            Surname: f_surname,
            Tel_Number: f_tel,
            Tel_Number_Alt: f_altTel,
            Gender: f_gender,
            Email: document.getElementById('f_email').value.trim(),
            DOB: th_normalizeDateForInput(document.getElementById('f_dob').value),
            countryIso2: phoneInfo.countryIso2,
            countryCallingCode: phoneInfo.countryCallingCode,
            phoneNational: phoneInfo.phoneNational,
            phoneE164: phoneInfo.phoneE164,
            phoneAliases: phoneInfo.phoneAliases,
            legacyPhone: phoneInfo.legacyPhone,
            altCountryIso2: altPhoneInfo?.hasValue ? altPhoneInfo.countryIso2 : '',
            altCountryCallingCode: altPhoneInfo?.hasValue ? altPhoneInfo.countryCallingCode : '',
            altPhoneNational: altPhoneInfo?.hasValue ? altPhoneInfo.phoneNational : '',
            altPhoneE164: altPhoneInfo?.hasValue ? altPhoneInfo.phoneE164 : '',
            altPhoneAliases: altPhoneInfo?.hasValue ? altPhoneInfo.phoneAliases : [],
            altLegacyPhone: altPhoneInfo?.hasValue ? altPhoneInfo.legacyPhone : '',
            Last_Updated: firebase.firestore.FieldValue.serverTimestamp()
        };

        await db.collection("Clients").doc(f_tel).set(clientMasterData, { merge: true });
        
        const cachedClient = { id: f_tel, ...clientMasterData };
        let existingIdx = allClientsCache.findIndex(c => (c.id || c.Tel_Number) === f_tel);
        if(existingIdx >= 0) { allClientsCache[existingIdx] = cachedClient; }
        else { allClientsCache.push(cachedClient); }
        
        alert(`Success! ${f_forename} ${f_surname} has been saved to the database. 

Please proceed to the Book Appointment tab to assign them a service and Technician.`);
        window.clearFohForm(); 
        document.getElementById('fohSearchPhone').value = ''; 
        document.getElementById('fohSearchMsg').innerText = '';
    } catch (error) { alert("Error saving client: " + error.message); } finally { btn.innerText = "Save Client Record"; btn.disabled = false; }
}

function thFohStatusKey(value){
    return String(value || '').trim().toLowerCase();
}

function thFohIsTerminalAppointmentStatus(value){
    const s = thFohStatusKey(value);
    return ['cancelled','canceled','no show','noshow','closed','completed','complete','ready for payment','paid'].includes(s);
}

function thFohIsTerminalActiveJobStatus(value){
    const s = thFohStatusKey(value);
    return ['cancelled','canceled','no show','noshow','closed','completed','complete','ready for payment','paid'].includes(s);
}

function thFohIsReturnedAppointment(appt){
    const d = appt || {};
    const s = thFohStatusKey(d.status);
    if (thFohIsTerminalAppointmentStatus(s)) return false;
    return (
        d.needsFOHAttention === true ||
        d.needsFohReview === true ||
        d.requiresFohAction === true ||
        d.rescheduleRequested === true ||
        d.requestReschedule === true ||
        d.pendingReschedule === true ||
        d.returnedToFOH === true ||
        d.returnToFoh === true ||
        d.fohAction === 'Reschedule Requested' ||
        s === 'action required' ||
        s === 'foh review'
    );
}

function thFohClearReturnFlagsPayload(){
    const FieldValue = firebase.firestore.FieldValue;
    return {
        needsFOHAttention: false,
        rescheduleRequested: false,
        fohAction: FieldValue.delete(),
        returnedToFOHAt: FieldValue.delete(),
        returnedToFOHBy: FieldValue.delete(),
        rescheduleRequestedAt: FieldValue.delete(),
        rescheduleRequestedBy: FieldValue.delete(),
        needsFohReview: FieldValue.delete(),
        requiresFohAction: FieldValue.delete(),
        requestReschedule: FieldValue.delete(),
        pendingReschedule: FieldValue.delete(),
        returnedToFOH: FieldValue.delete(),
        returnToFoh: FieldValue.delete()
    };
}

async function thFohResolveAppointmentRefForJob(job){
    const data = job || {};
    const sourceId = String(data.sourceAppointmentId || data.appointmentId || data.appointmentDocId || '').trim();
    if (sourceId) {
        try {
            const ref = db.collection('Appointments').doc(sourceId);
            const snap = await ref.get();
            if (snap.exists) {
                const appt = snap.data() || {};
                if (isArchivedRecord(appt) || thFohIsTerminalAppointmentStatus(appt.status)) {
                    console.warn('THURAYA FOH return skipped terminal/archived source appointment', { sourceAppointmentId: sourceId, status: appt.status || '' });
                    return null;
                }
                return { ref, id: sourceId, data: appt, method: 'sourceAppointmentId' };
            }
            console.warn('THURAYA FOH return sourceAppointmentId appointment not found', { sourceAppointmentId: sourceId });
        } catch(e) {
            console.warn('THURAYA FOH return sourceAppointmentId lookup failed', e);
        }
    }

    const phone = String(data.clientPhone || '').trim();
    const date = String(data.dateString || '').trim();
    const tech = String(data.assignedTechEmail || '').trim();
    const time = String(data.timeString || data.startTime || '').trim();
    if (!phone || !date || !tech) {
        console.warn('THURAYA FOH return skipped appointment update: insufficient fallback correlation fields');
        return null;
    }

    try {
        const snap = await db.collection('Appointments')
            .where('clientPhone', '==', phone)
            .where('dateString', '==', date)
            .where('assignedTechEmail', '==', tech)
            .get();
        const candidates = [];
        snap.forEach(doc => {
            const appt = doc.data() || {};
            if (isArchivedRecord(appt) || thFohIsTerminalAppointmentStatus(appt.status)) return;
            if (time && String(appt.timeString || appt.startTime || '').trim() !== time) return;
            candidates.push({ ref: doc.ref, id: doc.id, data: appt, method: 'client/date/tech/time fallback' });
        });
        if (candidates.length === 1) return candidates[0];
        console.warn('THURAYA FOH return skipped appointment update: unsafe fallback match count', {
            count: candidates.length,
            hasClientPhone: !!phone,
            dateString: date,
            assignedTechEmail: tech,
            timeString: time
        });
    } catch(e) {
        console.warn('THURAYA FOH return fallback appointment lookup failed', e);
    }
    return null;
}

function startExpectedTodayListener() {
    const listDiv = document.getElementById('expectedTodayList');
    try {
        const expectedTodayDateStr = (typeof getLocalDateString === 'function') ? getLocalDateString() : todayDateStr;
        expectedTodayListener = window.ThurayaSessionResources.listen('expected-today', db.collection('Appointments').where('dateString', '==', expectedTodayDateStr), snap => {
            if(snap.empty) { listDiv.innerHTML = '<p style="color: #999; font-style: italic;">No appointments scheduled for today.</p>'; return; }
            
            let todaysAppts = [];
            let returnedToFOH = [];
            snap.forEach(doc => {
                let appt = doc.data();
                if (isArchivedRecord(appt)) return;
                const normalizedAppt = {id: doc.id, ...appt};

                if (thFohIsTerminalAppointmentStatus(appt.status)) return;

                if(thFohIsReturnedAppointment(appt)) {
                    returnedToFOH.push(normalizedAppt);
                    return;
                }

                if(appt.status === 'Scheduled') todaysAppts.push(normalizedAppt);
            });

            todaysAppts.sort((a, b) => {
                let timeA = a.timeString || ""; let timeB = b.timeString || "";
                return timeA.localeCompare(timeB);
            });

            let html = '';

            if(todaysAppts.length === 0 && returnedToFOH.length === 0) {
                listDiv.innerHTML = '<p style="color: #999; font-style: italic;">No appointments scheduled for today.</p>';
                return;
            }

            if(returnedToFOH.length > 0){
                returnedToFOH.sort((a,b)=> (a.timeString || '').localeCompare(b.timeString || ''));

                html += `
                    <div style="margin-bottom:14px; border:1px solid rgba(0,0,0,.08); border-radius:14px; overflow:hidden; background:#fff8f2;">
                        <div style="padding:12px 14px; background:#111; color:#fff; display:flex; justify-content:space-between; align-items:center; gap:12px;">
                            <div>
                                <div style="font-size:.72rem; letter-spacing:.18em; text-transform:uppercase; opacity:.7;">Front Of House Queue</div>
                                <div style="font-size:1rem; font-weight:800;">Returned To FOH · Needs Attention</div>
                            </div>
                            <div style="font-size:.82rem; font-weight:700; background:#fff; color:#111; border-radius:999px; padding:6px 10px;">${returnedToFOH.length} Pending</div>
                        </div>
                        <div style="padding:12px; display:flex; flex-direction:column; gap:10px;">
                            ${returnedToFOH.map(appt => {
                                const timeParts = (appt.timeString || '00:00').split(':');
                                const hr = parseInt(timeParts[0]) || 0;
                                const min = timeParts[1] || '00';
                                const ampm = hr >= 12 ? 'PM' : 'AM';
                                let hr12 = hr % 12; if(hr12 === 0) hr12 = 12;
                                const displayMins = parseInt(min) < 10 ? '0' + parseInt(min) : min;

                                return `
                                    <div class="ticket" style="border-color:#d97706; background:#fff; padding:10px; display:flex; justify-content:space-between; align-items:center; gap:10px;">
                                        <div style="flex-grow:1; min-width:0;">
                                            <h4 style="margin:0; font-size:1rem; color:#111;">${appt.clientName || 'Unknown'}${appt.isGroupBooking ? `<span class="group-badge">👥 GROUP · ${appt.groupSize}</span>` : ''}</h4>
                                            <p style="margin:4px 0 0; font-size:.82rem; color:#333;">💅 <strong>${appt.bookedService || 'N/A'}</strong></p>
                                            <p style="margin:4px 0 0; font-size:.8rem; color:#555;">⏰ ${hr12}:${displayMins} ${ampm} | Previous Tech: ${appt.assignedTechName || 'Unknown'}</p>
                                            <p style="margin:4px 0 0; font-size:.78rem; color:#b45309; font-weight:700;">↩ Returned to FOH for reschedule review</p>
                                        </div>
                                        <div style="display:flex; flex-direction:column; gap:5px; width:96px;">
                                            <button class="btn" style="width:100%; padding:6px; font-size:.74rem;" onclick="editAppointment('${appt.id}')">Review</button>
                                            <button class="btn btn-secondary" style="width:100%; padding:6px; font-size:.74rem; color:var(--error); border-color:var(--error);" onclick="cancelAppointment('${appt.id}')">Cancel</button>
                                        </div>
                                    </div>
                                `;
                            }).join('')}
                        </div>
                    </div>
                `;
            }

            let validCount = 0;

            todaysAppts.forEach(appt => {
                let timeParts = (appt.timeString || "00:00").split(':');
                let hr = parseInt(timeParts[0]) || 0; let min = timeParts[1] || "00";

                validCount++;
                let ampm = hr >= 12 ? 'PM' : 'AM'; let hr12 = hr % 12; if(hr12 === 0) hr12 = 12;
                let displayMins = parseInt(min) < 10 ? '0' + parseInt(min) : min;
                let displayAmt = parseFloat(appt.grandTotal || appt.bookedPrice || 0).toFixed(2);
                
                html += `
                    <div class="ticket" style="border-color: var(--accent); padding: 10px; display:flex; justify-content:space-between; align-items:center;">
                        <div style="flex-grow:1;">
                            <h4 style="margin:0; font-size:1rem;">${appt.clientName || 'Unknown'}${appt.isGroupBooking ? `<span class="group-badge">👥 GROUP · ${appt.groupSize}</span>` : ''}</h4>
                            <p style="margin:0; font-size:0.8rem; color: var(--primary);">💅 <strong>${appt.bookedService || 'N/A'}</strong></p>
                            <p style="margin:0; font-size:0.8rem;">⏰ ${hr12}:${displayMins} ${ampm} | Tech: ${appt.assignedTechName || 'Unknown'} | 📞 ${appt.clientPhone || 'N/A'}</p>
                            
                        </div>
                        <div style="display:flex; flex-direction:column; gap:5px; width:80px;">
                            <button class="btn" data-checkin-appointment-id="${appt.id}" style="width:100%; padding:5px; font-size:0.75rem;" onclick="checkInAppointment('${appt.id}')">Check-In</button>
                            <button class="btn btn-secondary" style="width:100%; padding:5px; font-size:0.75rem;" onclick="editAppointment('${appt.id}')">Edit</button>
                            <button class="btn btn-secondary" style="width:100%; padding:5px; font-size:0.75rem; color:var(--error); border-color:var(--error);" onclick="cancelAppointment('${appt.id}')">Cancel</button>
                            ${window.ThurayaNoShow?.buttons(appt) || ''}
                        </div>
                    </div>`;
            });
            
            if(validCount === 0 && returnedToFOH.length === 0) {
                listDiv.innerHTML = '<p style="color: #999; font-style: italic;">No more appointments expected today.</p>';
            } else {
                listDiv.innerHTML = html;
            }
        });
    } catch(e) { console.error(e); }
}


// HF90C — Group check-in choice modal (replaces browser confirm for safer FOH operation)
(function(){
    if (window.thurayaGroupCheckinChoice) return;

    function ensureGroupCheckinModalStyles(){
        if (document.getElementById('thuraya-group-checkin-modal-styles')) return;
        const style = document.createElement('style');
        style.id = 'thuraya-group-checkin-modal-styles';
        style.textContent = `
            .thuraya-group-checkin-backdrop{
                position:fixed; inset:0; z-index:99999; display:flex; align-items:center; justify-content:center;
                padding:24px; background:rgba(10,10,10,.54); backdrop-filter:blur(8px);
            }
            .thuraya-group-checkin-modal{
                width:min(560px, calc(100vw - 32px)); background:#fff; color:#111; border:1px solid rgba(17,17,17,.12);
                border-radius:26px; box-shadow:0 28px 90px rgba(0,0,0,.28); overflow:hidden;
                font-family:Inter, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
            }
            .thuraya-group-checkin-modal__head{ position:relative; padding:26px 58px 18px 28px; border-bottom:1px solid rgba(17,17,17,.08); }
            .thuraya-group-checkin-close{
                position:absolute; top:18px; right:20px; width:38px; height:38px; border-radius:999px;
                border:1px solid rgba(17,17,17,.12); background:#fff; color:#111; cursor:pointer;
                font-size:1.35rem; line-height:1; display:flex; align-items:center; justify-content:center;
            }
            .thuraya-group-checkin-close:hover{ border-color:#111; background:#f7f7f7; }
            .thuraya-group-checkin-eyebrow{ font-size:.72rem; letter-spacing:.22em; text-transform:uppercase; color:#9b7c25; font-weight:900; margin-bottom:10px; }
            .thuraya-group-checkin-title{ font-size:1.45rem; font-weight:900; letter-spacing:.02em; margin:0; }
            .thuraya-group-checkin-body{ padding:22px 28px 10px; }
            .thuraya-group-checkin-message{ color:#4c4c4c; line-height:1.55; margin:0 0 18px; font-size:1rem; }
            .thuraya-group-checkin-options{ display:grid; gap:12px; margin-top:16px; }
            .thuraya-group-checkin-option{
                width:100%; text-align:left; border-radius:18px; padding:18px 18px; cursor:pointer;
                border:1px solid rgba(17,17,17,.12); background:#fff; display:flex; justify-content:space-between; gap:16px; align-items:center;
                transition:transform .12s ease, box-shadow .12s ease, border-color .12s ease;
            }
            .thuraya-group-checkin-option:hover{ transform:translateY(-1px); box-shadow:0 14px 30px rgba(0,0,0,.10); border-color:#111; }
            .thuraya-group-checkin-option strong{ display:block; font-size:.98rem; letter-spacing:.06em; text-transform:uppercase; }
            .thuraya-group-checkin-option span{ display:block; color:#6a6a6a; margin-top:4px; font-size:.88rem; line-height:1.35; }
            .thuraya-group-checkin-option--person,
            .thuraya-group-checkin-option--group{ background:#fff; color:#111; border-color:rgba(17,17,17,.12); }
            .thuraya-group-checkin-option--person span,
            .thuraya-group-checkin-option--group span{ color:#6a6a6a; }
            .thuraya-group-checkin-arrow{ font-size:1.35rem; opacity:.7; }
            .thuraya-group-checkin-foot{ padding:10px 28px 24px; color:#777; font-size:.78rem; line-height:1.4; display:flex; justify-content:space-between; align-items:center; gap:12px; }
            .thuraya-group-checkin-cancel{
                border:0; background:transparent; color:#111; font-weight:900; letter-spacing:.08em; text-transform:uppercase;
                cursor:pointer; padding:10px 0; white-space:nowrap;
            }
            .thuraya-group-checkin-cancel:hover{ text-decoration:underline; }
            @media(max-width:640px){
                .thuraya-group-checkin-backdrop{ align-items:flex-end; padding:14px; }
                .thuraya-group-checkin-modal{ border-radius:24px; }
                .thuraya-group-checkin-modal__head,.thuraya-group-checkin-body,.thuraya-group-checkin-foot{ padding-left:20px; padding-right:20px; }
            }
        `;
        document.head.appendChild(style);
    }

    window.thurayaGroupCheckinChoice = function(appt){
        ensureGroupCheckinModalStyles();
        const clientName = appt?.clientName || 'This client';
        const groupSize = appt?.groupSize || '';
        const groupText = groupSize ? `${groupSize} people` : 'group booking';

        return new Promise(resolve => {
            const backdrop = document.createElement('div');
            backdrop.className = 'thuraya-group-checkin-backdrop';
            backdrop.innerHTML = `
                <div class="thuraya-group-checkin-modal" role="dialog" aria-modal="true" aria-labelledby="thurayaGroupCheckinTitle">
                    <div class="thuraya-group-checkin-modal__head">
                        <button type="button" class="thuraya-group-checkin-close" data-choice="cancel" aria-label="Close group check-in dialog">×</button>
                        <div class="thuraya-group-checkin-eyebrow">Group check-in</div>
                        <h3 class="thuraya-group-checkin-title" id="thurayaGroupCheckinTitle">How should this booking be checked in?</h3>
                    </div>
                    <div class="thuraya-group-checkin-body">
                        <p class="thuraya-group-checkin-message"><strong>${clientName}</strong> is part of a group booking (${groupText}). Choose the exact check-in action below.</p>
                        <div class="thuraya-group-checkin-options">
                            <button type="button" class="thuraya-group-checkin-option thuraya-group-checkin-option--person" data-choice="person">
                                <span><strong>Check in this person only</strong><span>Best when members arrive separately.</span></span>
                                <b class="thuraya-group-checkin-arrow">→</b>
                            </button>
                            <button type="button" class="thuraya-group-checkin-option thuraya-group-checkin-option--group" data-choice="group">
                                <span><strong>Check in entire group</strong><span>Use only when all group members have arrived.</span></span>
                                <b class="thuraya-group-checkin-arrow">→</b>
                            </button>
                        </div>
                    </div>
                    <div class="thuraya-group-checkin-foot">
                        <span>No check-in action will happen unless staff chooses one option.</span>
                        <button type="button" class="thuraya-group-checkin-cancel" data-choice="cancel">Cancel</button>
                    </div>
                </div>`;

            const cleanup = choice => {
                document.removeEventListener('keydown', onKeydown);
                backdrop.remove();
                // Safety: close/cancel must dismiss only. It must not fall through to person check-in.
                resolve(choice === 'person' || choice === 'group' ? choice : null);
            };
            const onKeydown = evt => { if (evt.key === 'Escape') cleanup(null); };
            backdrop.addEventListener('click', evt => {
                const button = evt.target.closest?.('[data-choice]');
                if (button) cleanup(button.getAttribute('data-choice'));
            });
            document.addEventListener('keydown', onKeydown);
            document.body.appendChild(backdrop);
            setTimeout(() => backdrop.querySelector('[data-choice="person"]')?.focus(), 30);
        });
    };
})();

window.checkInAppointment = async function(id) {
    try {
        const doc  = await db.collection('Appointments').doc(id).get();
        const appt = doc.data();

        // Check if this is part of a group — offer bulk check-in
        if (appt.groupId && appt.isGroupBooking) {
            const groupChoice = await window.thurayaGroupCheckinChoice(appt);
            if (!groupChoice) return;
            if (groupChoice === 'group') {
                await checkInGroupByGroupId(appt.groupId);
                return;
            }
        }

        // Individual check-in
        await _doCheckIn(id, appt);
        alert(`${appt.clientName} checked in and routed to ${appt.assignedTechName}!`);
    } catch(e) { alert("Error checking in: " + e.message); }
}

/** Check in all appointments sharing the same groupId */
async function checkInGroupByGroupId(groupId) {
    try {
        const snap = await db.collection('Appointments')
            .where('groupId', '==', groupId)
            .where('status', '==', 'Scheduled')
            .get();

        if (snap.empty) { alert('No scheduled group members found.'); return; }

        const batch = db.batch();
        const jobPromises = [];

        snap.forEach(doc => {
            // Update appointment status
            const appt = doc.data();
            if (isArchivedRecord(appt)) return;
            batch.update(doc.ref, { status: 'Arrived' });
            // Create Active_Job for each member
            const groupPaymentMeta = thNormalizeGroupPaymentResponsibility(appt);
            jobPromises.push(db.collection('Active_Jobs').add({
                clientPhone:       appt.clientPhone,
                clientName:        appt.clientName,
                assignedTechEmail: appt.assignedTechEmail,
                assignedTechName:  appt.assignedTechName,
                bookedService:     appt.bookedService  || 'N/A',
                bookedDuration:    appt.bookedDuration || '0',
                bookedPrice:       appt.bookedPrice    || '0',
                grandTotal:        appt.grandTotal     || '0',
                taxBreakdown:      appt.taxBreakdown   || '[]',
                serviceLineItems:   typeof window.thCopyServiceLineItems === 'function' ? window.thCopyServiceLineItems(appt) : (Array.isArray(appt.serviceLineItems) ? appt.serviceLineItems : []),
                serviceSubtotal:    appt.serviceSubtotal || appt.bookedPrice || '0',
                taxTotal:           appt.taxTotal || '',
                amountDue:          appt.amountDue || appt.grandTotal || '0',
                groupTotal:         appt.groupTotal || '',
                memberServiceTotal: appt.memberServiceTotal || appt.grandTotal || '',
                payableShare:       appt.payableShare || appt.amountDue || appt.grandTotal || '',
                groupId:           appt.groupId        || '',
                isGroupBooking:    true,
                groupSize:         appt.groupSize      || 1,
                groupRole:         appt.groupRole      || '',
                billingMode:       groupPaymentMeta.billingMode,
                payableBy:         groupPaymentMeta.payableBy,
                groupPaymentMode:  groupPaymentMeta.groupPaymentMode,
                groupPaymentLabel: groupPaymentMeta.groupPaymentLabel,
                paymentResponsibility: groupPaymentMeta.paymentResponsibility,
                amountDueByMember: groupPaymentMeta.amountDueByMember,
                status:            'Waiting',
                fohCreator:        currentUserEmail,
                createdAt:         firebase.firestore.FieldValue.serverTimestamp(),
                dateString:        todayDateStr
            }));
        });

        await batch.commit();
        await Promise.all(jobPromises);
        alert(`Group ${groupId} checked in — ${jobPromises.length} member(s) routed to the floor.`);
    } catch(e) { alert('Error checking in group: ' + e.message); }
}

/** Single appointment check-in helper */
async function _doCheckIn(id, appt) {
    if (isArchivedRecord(appt)) {
        alert('This appointment has been archived and is hidden from normal operations.');
        return;
    }
    await db.collection('Appointments').doc(id).update({ status: 'Arrived' });
    const groupPaymentMeta = thNormalizeGroupPaymentResponsibility(appt);
    await db.collection('Active_Jobs').add({
        clientPhone:       appt.clientPhone,
        clientName:        appt.clientName,
        assignedTechEmail: appt.assignedTechEmail,
        assignedTechName:  appt.assignedTechName,
        bookedService:     appt.bookedService  || 'N/A',
        bookedDuration:    appt.bookedDuration || '0',
        bookedPrice:       appt.bookedPrice    || '0',
        grandTotal:        appt.grandTotal     || '0',
        taxBreakdown:      appt.taxBreakdown   || '[]',
        serviceLineItems:   typeof window.thCopyServiceLineItems === 'function' ? window.thCopyServiceLineItems(appt) : (Array.isArray(appt.serviceLineItems) ? appt.serviceLineItems : []),
        serviceSubtotal:    appt.serviceSubtotal || appt.bookedPrice || '0',
        taxTotal:           appt.taxTotal || '',
        amountDue:          appt.amountDue || appt.grandTotal || '0',
        groupTotal:         appt.groupTotal || '',
        memberServiceTotal: appt.memberServiceTotal || appt.grandTotal || '',
        payableShare:       appt.payableShare || appt.amountDue || appt.grandTotal || '',
        groupId:           appt.groupId        || '',
        isGroupBooking:    appt.isGroupBooking  || false,
        groupSize:         appt.groupSize       || 1,
        groupRole:         appt.groupRole       || '',
        billingMode:       groupPaymentMeta.billingMode,
        payableBy:         groupPaymentMeta.payableBy,
        groupPaymentMode:  groupPaymentMeta.groupPaymentMode,
        groupPaymentLabel: groupPaymentMeta.groupPaymentLabel,
        paymentResponsibility: groupPaymentMeta.paymentResponsibility,
        amountDueByMember: groupPaymentMeta.amountDueByMember,
        status:            'Waiting',
        fohCreator:        currentUserEmail,
        createdAt:         firebase.firestore.FieldValue.serverTimestamp(),
        dateString:        todayDateStr
    });
    if (GOOGLE_CHAT_WEBHOOK !== "") {
        fetch(GOOGLE_CHAT_WEBHOOK, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ text: `🛎️ *Client Arrived*\n*Client:* ${appt.clientName}\n*Service:* ${appt.bookedService}\n*Assigned Tech:* ${appt.assignedTechName}\n_Please check your Dashboard._` })
        }).catch(err => console.error(err));
    }
}

// ==========================================
// TECH CONSULTATION & UPSELL ENGINE
// ==========================================
window.toggleMedNone = function(checkbox) {
    if(checkbox.checked) {
        document.querySelectorAll('.med-cb').forEach(cb => { cb.checked = false; cb.disabled = true; });
    } else {
        document.querySelectorAll('.med-cb').forEach(cb => { cb.disabled = false; });
    }
}



// HF91A — Consultation Compliance Validation
// Blocks only consultation completion/start when required safety assessment fields are missing.
function ensureConsultComplianceMessageBox() {
    const modal = document.getElementById('consultationModal');
    if(!modal) return null;
    let box = document.getElementById('consultComplianceErrors');
    if(!box) {
        const saveBtn = document.getElementById('btnConsultSaveStart');
        box = document.createElement('div');
        box.id = 'consultComplianceErrors';
        box.setAttribute('role', 'alert');
        box.style.display = 'none';
        box.style.margin = '14px 0';
        box.style.padding = '12px 14px';
        box.style.border = '1px solid rgba(160, 49, 49, 0.26)';
        box.style.borderRadius = '14px';
        box.style.background = '#fff7f7';
        box.style.color = '#8a2b2b';
        box.style.fontWeight = '700';
        box.style.fontSize = '0.9rem';
        box.style.lineHeight = '1.45';
        if(saveBtn && saveBtn.parentNode) saveBtn.parentNode.insertBefore(box, saveBtn);
        else modal.querySelector('.consult-modal')?.appendChild(box);
    }
    return box;
}

function clearConsultComplianceValidation() {
    const box = document.getElementById('consultComplianceErrors');
    if(box) {
        box.style.display = 'none';
        box.innerHTML = '';
    }
    document.querySelectorAll('[data-consult-required="true"]').forEach(el => {
        el.style.outline = '';
        el.style.borderRadius = '';
        el.removeAttribute('data-consult-required');
    });
}

function markConsultRequiredGroup(selector) {
    document.querySelectorAll(selector).forEach(input => {
        const wrap = input.closest('.checkbox-grid, .radio-group') || input.parentElement;
        if(wrap) {
            wrap.dataset.consultRequired = 'true';
            wrap.style.outline = '2px solid rgba(160, 49, 49, 0.26)';
            wrap.style.borderRadius = '12px';
        }
    });
}

function validateConsultComplianceBeforeStart() {
    clearConsultComplianceValidation();
    const missing = [];
    const hasMedicalSelection = !!document.querySelector('.med-cb:checked') || !!document.getElementById('med_none')?.checked;
    const hasCallus = !!document.querySelector('input[name="cond_callus"]:checked');
    const hasSkin = !!document.querySelector('input[name="cond_skin"]:checked');

    if(!hasMedicalSelection) {
        missing.push('Medical History & Safety assessment');
        markConsultRequiredGroup('.med-cb, #med_none');
    }
    if(!hasCallus) {
        missing.push('Callus Level');
        markConsultRequiredGroup('input[name="cond_callus"]');
    }
    if(!hasSkin) {
        missing.push('Skin Condition');
        markConsultRequiredGroup('input[name="cond_skin"]');
    }

    if(!missing.length) return true;

    const box = ensureConsultComplianceMessageBox();
    if(box) {
        box.innerHTML = `<div style="margin-bottom:6px;">Please complete the required consultation checks before starting service:</div><ul style="margin:0 0 0 18px;padding:0;">${missing.map(item => `<li>${item}</li>`).join('')}</ul>`;
        box.style.display = 'block';
        box.scrollIntoView({ behavior: 'smooth', block: 'center' });
    } else {
        alert('Please complete required consultation checks: ' + missing.join(', '));
    }
    return false;
}

function bindConsultComplianceClearHandlers() {
    document.querySelectorAll('.med-cb, #med_none, input[name="cond_callus"], input[name="cond_skin"]').forEach(input => {
        if(input.dataset.hf91aBound === 'true') return;
        input.dataset.hf91aBound = 'true';
        input.addEventListener('change', () => {
            if(validateConsultComplianceSoftComplete()) clearConsultComplianceValidation();
        });
    });
}

function validateConsultComplianceSoftComplete() {
    return (!!document.querySelector('.med-cb:checked') || !!document.getElementById('med_none')?.checked)
        && !!document.querySelector('input[name="cond_callus"]:checked')
        && !!document.querySelector('input[name="cond_skin"]:checked');
}

window.openConsultation = async function(id) {
    try {
        const doc = await db.collection('Active_Jobs').doc(id).get();
        if(!doc.exists) return;
        const consultJob = { id: doc.id, ...(doc.data() || {}) };
        if (isArchivedRecord(consultJob)) {
            alert('This job has been archived and is hidden from normal operations.');
            return;
        }
        currentConsultJobData = doc.data();
        currentConsultJobId = id;
        pendingUpsells = [];
        consultTicketItems = thConsultBuildTicketItemsFromJob(currentConsultJobData);
        thConsultSyncPendingUpsellsFromTicket();
        consultSelectedPrimaryService = null;

        document.getElementById('consultClientName').innerText = currentConsultJobData.clientName;
        document.getElementById('consultCurrentTicket').innerText = thConsultServiceTextFromItems() || currentConsultJobData.bookedService;
        hf91bEnsureConsultServicePanel();
        hf91bRefreshConsultTicketLabel();
        document.getElementById('consultProjectedTotal').innerText = parseFloat(currentConsultJobData.grandTotal || currentConsultJobData.bookedPrice || 0).toFixed(2) + ' GHC';
        document.getElementById('consultAddedUpsells').innerHTML = '';
        document.getElementById('consultUpsellSelect').value = '';
        renderConsultUpsells();
        
        let cr = currentConsultJobData.consultationRecord || {}; 
        let md = cr.medicalHistory || [];
        
        document.querySelectorAll('.med-cb').forEach(cb => { 
            cb.checked = md.includes(cb.value); 
            cb.disabled = false; 
        });
        if(document.getElementById('med_none')){ 
            document.getElementById('med_none').checked = md.includes("None"); 
            if(md.includes("None")) document.querySelectorAll('.med-cb').forEach(c=>c.disabled=true); 
        }

        document.getElementById('med_allergies').value = cr.allergies || '';
        document.getElementById('med_other').value = cr.otherMedical || '';
        document.querySelectorAll('input[name="cond_callus"]').forEach(r => r.checked = (r.value===cr.callusLevel));
        document.querySelectorAll('input[name="cond_skin"]').forEach(r => r.checked = (r.value===cr.skinCondition));
        document.getElementById('cond_notes').value = cr.visualNotes || '';
        
        document.getElementById('consultReassignTech').value = '';
        updateConsultReassignState();

        // DYNAMIC FORM POPULATION
        let cf = cr.customFields || {};
        let dynHtml = '';
        consultTemplate.forEach(q => {
            dynHtml += `<div class="consult-section-title" style="margin-top:20px;font-size:0.95rem;">${q.label}</div><div style="margin-bottom:15px;">`;
            if(q.type === 'text') {
                dynHtml += `<input type="text" id="ans_${q.id}" value="${cf[q.id] || ''}" style="width:100%;padding:10px;border:1px solid var(--border);border-radius:4px;">`;
            } else if(q.type === 'checkbox') {
                dynHtml += `<div class="checkbox-grid">`;
                let vArr = cf[q.id] || [];
                q.options.forEach(o => { dynHtml += `<label><input type="checkbox" class="ans_cb_${q.id}" value="${o}" ${vArr.includes(o) ? 'checked' : ''}> ${o}</label>`; });
                dynHtml += `</div>`;
            } else if(q.type === 'radio') {
                dynHtml += `<div class="radio-group">`;
                let vStr = cf[q.id] || '';
                q.options.forEach(o => { dynHtml += `<label><input type="radio" name="ans_rd_${q.id}" value="${o}" ${vStr === o ? 'checked' : ''}> ${o}</label>`; });
                dynHtml += `</div>`;
            }
            dynHtml += `</div>`;
        });
        let dynamicFormDiv = document.getElementById('dynamicConsultForm');
        if (dynamicFormDiv) dynamicFormDiv.innerHTML = dynHtml;

        let btn = document.getElementById('btnConsultSaveStart');
        if(btn) btn.innerText = (currentConsultJobData.status === 'In Progress') ? "Update Record" : "Save & Start Service";

        clearConsultComplianceValidation();
        bindConsultComplianceClearHandlers();
        document.getElementById('consultationModal').style.display = 'block';
    } catch(e) { alert("Error opening consultation: " + e.message); }
}

window.closeConsultation = function() {
    document.getElementById('consultationModal').style.display = 'none';
    currentConsultJobId = null;
    currentConsultJobData = null;
    pendingUpsells = [];
    consultTicketItems = [];
    consultSelectedPrimaryService = null;
    clearConsultComplianceValidation();
}
window.closeConsult = window.closeConsultation;
window.openConsult = window.openConsultation;


// HF91B — Consultation Service Adjustment (safe layer)
// Allows tech to select a final agreed primary service during consultation while preserving the original booking snapshot.
let consultSelectedPrimaryService = null;

function hf91bMoney(value) {
    const n = parseFloat(value || 0);
    return Number.isFinite(n) ? n.toFixed(2) : '0.00';
}
function hf91bServiceName(s) {
    return String(s?.name || s?.serviceName || s?.service || s?.title || 'Selected service').trim();
}
function hf91bServicePrice(s) {
    const n = parseFloat(s?.price ?? s?.servicePrice ?? s?.amount ?? 0);
    return Number.isFinite(n) ? n : 0;
}
function hf91bServiceDuration(s) {
    const n = parseInt(s?.duration ?? s?.serviceDuration ?? s?.minutes ?? 0, 10);
    return Number.isFinite(n) ? n : 0;
}
function hf91bSafeText(value) {
    return (typeof _thEscapeHtml === 'function') ? _thEscapeHtml(String(value || '')) : String(value || '').replace(/[&<>'\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[c]));
}
function thConsultNameKey(value) {
    return String(value || '')
        .normalize('NFKD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/\s*\(x\s*\d+\)\s*$/i, '')
        .replace(/\s*(?:[xX]|\u00d7)\s*\d+\s*$/i, '')
        .replace(/&/g, ' and ')
        .replace(/[^a-z0-9]+/gi, ' ')
        .trim()
        .toLowerCase();
}
function thConsultParseServicePart(value) {
    let name = String(value || '').trim();
    let qty = 1;
    const qtyMatch = name.match(/\s*(?:\(|)?(?:[xX]|\u00d7)\s*(\d+)\)?\s*$/);
    if (qtyMatch) {
        qty = Math.max(1, parseInt(qtyMatch[1], 10) || 1);
        name = name.replace(/\s*(?:\(|)?(?:[xX]|\u00d7)\s*\d+\)?\s*$/, '').trim();
        name = name.replace(/\s*(?:[xX]|\u00d7)\s*\d+\s*$/, '').trim();
    }
    return name ? { name, qty } : null;
}
function thConsultSplitServiceText(value) {
    return String(value || '').split(',').map(thConsultParseServicePart).filter(Boolean);
}
function thConsultMenuServices() {
    try {
        return Array.isArray(allMenuServicesCache) ? allMenuServicesCache : [];
    } catch(e) {
        return [];
    }
}
function thConsultFindMenuServiceByName(name) {
    const key = thConsultNameKey(name);
    if (!key) return null;
    return thConsultMenuServices().find(s => thConsultNameKey(hf91bServiceName(s)) === key) || null;
}
function thConsultLineQty(item) {
    const q = parseInt(item?.qty ?? item?.quantity ?? item?.count ?? 1, 10);
    return Number.isFinite(q) && q > 0 ? q : 1;
}
function thConsultUnitPrice(item) {
    const direct = item?.unitPriceAtBooking ?? item?.unitPrice ?? item?.basePrice ?? item?.price ?? item?.amount;
    if (direct !== undefined && direct !== null && direct !== '') {
        const n = parseFloat(direct);
        return Number.isFinite(n) ? n : 0;
    }
    const lineTotal = parseFloat(item?.lineTotal ?? item?.totalPrice ?? 0);
    const qty = thConsultLineQty(item);
    return Number.isFinite(lineTotal) ? lineTotal / qty : 0;
}
function thConsultFinancialInput(item) {
    const source = item || {};
    const value = keys => {
        const key = keys.find(key => Object.prototype.hasOwnProperty.call(source, key) && source[key] !== undefined);
        return key === undefined ? undefined : source[key];
    };
    const rawQty = value(['qty','quantity','count']);
    const qty = rawQty === undefined ? 1 : window.thFinancialEvidence.amount(rawQty);
    const rawPrice = value(['unitPriceAtBooking','unitPrice','basePrice','price','servicePrice','amount']);
    const price = rawPrice === undefined
        ? window.thFinancialEvidence.amount(value(['lineTotal','totalPrice']))
        : window.thFinancialEvidence.amount(rawPrice);
    const lineAmount = rawPrice === undefined ? price : price * qty;
    const valid = Number.isSafeInteger(qty) && qty > 0 && price !== null &&
        Number.isSafeInteger(Math.round(lineAmount * 100)) && !source.financialInputError;
    return { valid, qty, unitPrice: rawPrice === undefined && qty > 0 ? price / qty : price,
        error: valid ? '' : source.financialInputError || JSON.stringify([rawQty, rawPrice, value(['lineTotal','totalPrice'])]) };
}
function thRequireProspectiveFinancialEdit(source, rows) {
    if (window.thFinancialEvidence.read(source).contradictions.length) throw new Error('TRANSACTION_FINANCIAL_EVIDENCE_CONFLICT');
    const inputs = rows.map(thConsultFinancialInput);
    const totalCents = inputs.reduce((sum, input) => sum + Math.round(input.unitPrice * input.qty * 100), 0);
    if (!inputs.length || inputs.some(input => !input.valid) || !Number.isSafeInteger(totalCents)) throw new Error('FINANCIAL_SELECTED_INPUT_INVALID');
}
function thConsultNormalizeTicketItem(item) {
    const input = thConsultFinancialInput(item);
    const qty = thConsultLineQty(item);
    const unitPrice = input.valid ? input.unitPrice : thConsultUnitPrice(item);
    const duration = parseInt(item?.durationAtBooking ?? hf91bServiceDuration(item), 10) || 0;
    const normalized = {
        ...item,
        ...(!input.valid ? { financialInputError: input.error } : {}),
        id: item?.id || item?.serviceId || '',
        name: hf91bServiceName(item),
        serviceName: hf91bServiceName(item),
        duration,
        price: unitPrice * qty,
        unitPrice,
        basePrice: unitPrice,
        qty,
        quantity: qty,
        totalPrice: unitPrice * qty,
        lineTotal: unitPrice * qty,
        inputType: item?.inputType || item?.selection || '',
        pricingType: item?.pricingType || item?.pricingModel || '',
        department: item?.department || item?.appliesTo || '',
        category: item?.category || item?.mainCategory || '',
        subCategory: item?.subCategory || '',
        source: item?.source || 'consultation_ticket'
    };
    return normalized;
}
function thConsultFallbackTicketItem(job) {
    const evidence = window.thFinancialEvidence.read(job || {});
    const listed = evidence.mode === 'inclusive' ? evidence.gross : evidence.mode === 'exclusive' ? evidence.net : null;
    return thConsultNormalizeTicketItem({
        name: job?.bookedService || 'Booked service', duration: parseInt(job?.bookedDuration || 0, 10) || 0,
        price: listed, qty: 1, priceMode: evidence.mode, aggregateEvidenceOnly: true,
        financialDetailUnavailable: listed === null, source: 'persisted_aggregate'
    });
}
function thConsultBuildTicketItemsFromJob(job) {
    const saved = [job?.serviceLineItems, job?.checkoutReviewItems, job?.consultationTicketItems]
        .find(rows => Array.isArray(rows) && rows.length);
    if (saved) return saved.map(thConsultNormalizeTicketItem);
    return job?.bookedService ? [thConsultFallbackTicketItem(job)] : [];
}
function thConsultFinalTicketItems() {
    return (Array.isArray(consultTicketItems) ? consultTicketItems : [])
        .map(thConsultNormalizeTicketItem)
        .filter(item => item.name);
}
function thConsultSyncPendingUpsellsFromTicket() {
    consultTicketItems = thConsultFinalTicketItems();
    pendingUpsells = consultTicketItems.slice(1).map(item => thConsultNormalizeUpsell({ ...item }));
}
function thConsultServiceTextFromItems(items) {
    const rows = Array.isArray(items) ? items : thConsultFinalTicketItems();
    return rows.map(item => item.qty > 1 ? `${item.name} (x${item.qty})` : item.name).join(', ');
}
function thConsultTicketMenuTotal(items) {
    return (Array.isArray(items) ? items : thConsultFinalTicketItems()).reduce((sum, item) => sum + (parseFloat(item.price || 0) || 0), 0);
}
function thConsultTicketDuration(items) {
    return (Array.isArray(items) ? items : thConsultFinalTicketItems()).reduce((sum, item) => {
        const duration = parseInt(item.duration || 0, 10) || 0;
        return sum + (duration * thConsultLineQty(item));
    }, 0);
}
function thConsultTicketItemsForSave() {
    const rows = thConsultFinalTicketItems();
    if (!rows.length) return [];
    const upsells = (Array.isArray(pendingUpsells) ? pendingUpsells : []).map(thConsultNormalizeUpsell);
    return [rows[0], ...upsells].map(thConsultNormalizeTicketItem).filter(item => item.name);
}
function thConsultTaxRatesFromRows(taxRows) {
    if (typeof window.thCanonicalTaxRatesFromBreakdown === 'function') {
        return window.thCanonicalTaxRatesFromBreakdown(taxRows);
    }
    return (Array.isArray(taxRows) ? taxRows : [])
        .map(row => ({
            name: row?.name || 'Tax',
            rate: parseFloat(row?.rate || 0) || 0
        }))
        .filter(row => row.rate > 0);
}
function thConsultSameFinancialItems(left, right) {
    const signature = rows => (rows || []).map(thConsultNormalizeTicketItem).map(row => [
        row.menuItemId || row.serviceId || row.id || '', row.name, row.qty,
        Math.round(row.unitPrice * 100), Math.round(row.lineTotal * 100), row.financialInputError || ''
    ]);
    return JSON.stringify(signature(left)) === JSON.stringify(signature(right));
}
function thConsultCanonicalFinancials(ticketItems, jobData) {
    const source = jobData || {};
    const rows = (Array.isArray(ticketItems) ? ticketItems : []).map(thConsultNormalizeTicketItem).filter(item => item.name);
    const originalRows = thConsultBuildTicketItemsFromJob(source);
    if (thConsultSameFinancialItems(rows, originalRows)) {
        return { ...window.thCopyFinancialEvidence(source), bookedService: source.bookedService,
            bookedDuration: source.bookedDuration, bookedPrice: source.bookedPrice,
            ...(source.serviceLineItems ? { serviceLineItems: source.serviceLineItems } : {}),
            preserveFinancialEvidence: true };
    }
    if (originalRows.some(row => row.aggregateEvidenceOnly || row.financialDetailUnavailable)) {
        throw new Error('TRANSACTION_SERVICE_DETAIL_UNAVAILABLE');
    }
    thRequireProspectiveFinancialEdit(source, rows);
    if (source.isGroupBooking || source.groupId) throw new Error('GROUP_FINANCIAL_EDIT_REQUIRES_REVIEW');
    if (source.hasPromoApplied || source.isPackageRedemption || source.hasComplimentaryAdjustment ||
        source.complimentaryTotalsApplied || Number(source.adjustmentTotal) > 0 ||
        (source.finalTotal != null && source.grandTotal != null && Number(source.finalTotal) !== Number(source.grandTotal))) {
        throw new Error('ADJUSTED_FINANCIAL_EDIT_REQUIRES_REVIEW');
    }
    const policy = window.thTransactionTaxPolicy(source);
    const canonical = window.thBuildCanonicalFinancialShape({
        serviceLineItems: rows.map(item => ({ ...item, durationAtBooking: item.duration,
            unitPriceAtBooking: item.unitPrice, lineTotal: item.unitPrice * item.qty, priceMode: policy.pricingMode })),
        pricingMode: policy.pricingMode, taxRates: policy.rates,
        compatibility: { includeMemberTotals: true, includePayableShare: true }
    });
    return { ...canonical, financialPolicySnapshot: source.financialPolicySnapshot || policy, preserveFinancialEvidence: false };
}
function thConsultFinancialUpdate(financials) {
    if (financials.preserveFinancialEvidence) return {};
    const { preserveFinancialEvidence, ...result } = financials;
    return { ...result, taxBreakdown: JSON.stringify(result.taxBreakdown) };
}
function hf91bCurrentPrimaryService() {
    const ticketItems = thConsultFinalTicketItems();
    if (ticketItems.length) return ticketItems[0];
    if (consultSelectedPrimaryService) return consultSelectedPrimaryService;
    return {
        id: currentConsultJobData?.bookedServiceId || currentConsultJobData?.serviceId || '',
        name: currentConsultJobData?.bookedService || 'Booked service',
        price: parseFloat(currentConsultJobData?.bookedPrice || 0) || 0,
        duration: parseInt(currentConsultJobData?.bookedDuration || 0, 10) || 0,
        source: 'original_booking'
    };
}
function hf91bOriginalBookingSnapshot(fieldValue=firebase.firestore.FieldValue) {
    const existing = currentConsultJobData?.originalBookingSnapshot || currentConsultJobData?.consultationOriginalBookingSnapshot;
    if (existing && typeof existing === 'object') return existing;
    return {
        serviceId: currentConsultJobData?.bookedServiceId || currentConsultJobData?.serviceId || '',
        serviceName: currentConsultJobData?.bookedService || '',
        price: parseFloat(currentConsultJobData?.bookedPrice || 0) || 0,
        duration: parseInt(currentConsultJobData?.bookedDuration || 0, 10) || 0,
        assignedTechEmail: currentConsultJobData?.assignedTechEmail || '',
        assignedTechName: currentConsultJobData?.assignedTechName || '',
        capturedAt: fieldValue.serverTimestamp()
    };
}
function hf91bPopulatePrimaryServiceSelect() {
    const select = document.getElementById('consultPrimaryServiceSelect');
    if (!select) return;
    const services = Array.isArray(allMenuServicesCache) ? allMenuServicesCache : [];
    const currentName = String(currentConsultJobData?.bookedService || '').trim();
    select.innerHTML = '<option value="">Keep original booked service</option>';
    services.forEach(s => {
        const name = hf91bServiceName(s);
        const price = hf91bMoney(hf91bServicePrice(s));
        const dur = hf91bServiceDuration(s);
        const opt = document.createElement('option');
        opt.value = String(s.id || '');
        opt.textContent = `${name} (${price} GHC${dur ? ', ' + dur + ' mins' : ''})`;
        if (consultSelectedPrimaryService && String(consultSelectedPrimaryService.id || '') === String(s.id || '')) opt.selected = true;
        else if (!consultSelectedPrimaryService && currentName && name === currentName) opt.selected = false;
        select.appendChild(opt);
    });
}
function hf91bEnsureConsultServicePanel() {
    const ticketEl = document.getElementById('consultCurrentTicket');
    if (!ticketEl) return;
    const ticketLine = ticketEl.closest('p');
    if (!ticketLine || document.getElementById('consultServiceAdjustPanel')) { hf91bPopulatePrimaryServiceSelect(); return; }
    const panel = document.createElement('div');
    panel.id = 'consultServiceAdjustPanel';
    panel.style.cssText = 'margin:12px 0 14px;padding:14px;border:1px solid #e3dccf;border-radius:16px;background:#fff;box-shadow:0 10px 24px rgba(47,55,70,0.04);';
    panel.innerHTML = `
        <div style="font-size:0.76rem;text-transform:uppercase;letter-spacing:0.12em;color:#7b7468;font-weight:900;margin-bottom:8px;">Final service after consultation</div>
        <div style="display:flex;gap:10px;align-items:stretch;flex-wrap:wrap;">
            <select id="consultPrimaryServiceSelect" style="flex:1;min-width:230px;min-height:46px;border-radius:12px;border:1px solid #ddd6c7;background:#fff;padding:0 12px;"></select>
            <button type="button" class="btn btn-secondary" style="width:auto;min-height:46px;border-radius:999px;padding:0 18px;" onclick="hf91bApplyConsultPrimaryService()">Apply Change</button>
            <button type="button" class="btn btn-secondary" style="width:auto;min-height:46px;border-radius:999px;padding:0 18px;" onclick="hf91bResetConsultPrimaryService()">Keep Original</button>
        </div>
        <div id="consultPrimaryServiceStatus" style="margin-top:9px;font-size:0.82rem;color:#6f6a60;font-weight:700;line-height:1.35;">Original booking is currently preserved.</div>`;
    ticketLine.insertAdjacentElement('afterend', panel);
    hf91bPopulatePrimaryServiceSelect();
}
function hf91bRefreshConsultTicketLabel() {
    const ticketEl = document.getElementById('consultCurrentTicket');
    const statusEl = document.getElementById('consultPrimaryServiceStatus');
    if (!currentConsultJobData) return;
    const original = String(currentConsultJobData.bookedService || 'Booked service');
    const finalTicketText = thConsultServiceTextFromItems() || original;
    if (ticketEl) {
        ticketEl.textContent = consultSelectedPrimaryService ? `${original} → ${hf91bServiceName(consultSelectedPrimaryService)}` : original;
    }
    if (ticketEl) ticketEl.textContent = finalTicketText;
    if (statusEl) {
        if (consultSelectedPrimaryService) {
            statusEl.innerHTML = `Original preserved: <strong>${hf91bSafeText(original)}</strong><br>Final agreed service: <strong>${hf91bSafeText(hf91bServiceName(consultSelectedPrimaryService))}</strong>`;
        } else {
            statusEl.textContent = 'Original booking is currently preserved.';
        }
        if (consultSelectedPrimaryService) {
            statusEl.innerHTML = `Original preserved: <strong>${hf91bSafeText(original)}</strong><br>Final agreed ticket: <strong>${hf91bSafeText(finalTicketText)}</strong>`;
        }
    }
}
window.hf91bApplyConsultPrimaryService = function() {
    const select = document.getElementById('consultPrimaryServiceSelect');
    const selectedId = select?.value;
    if (!selectedId) { hf91bResetConsultPrimaryService(); return; }
    const sObj = (Array.isArray(allMenuServicesCache) ? allMenuServicesCache : []).find(s => String(s.id || '') === String(selectedId));
    if (!sObj) { alert('Selected service could not be found. Please refresh and try again.'); return; }
    const rawPrice = Object.prototype.hasOwnProperty.call(sObj, 'price') ? sObj.price : sObj.servicePrice ?? sObj.amount ?? sObj.unitPrice;
    const input = thConsultFinancialInput({ price: rawPrice, qty: 1 });
    if (!input.valid) { alert('Selected service has invalid financial details.'); return; }
    consultSelectedPrimaryService = {
        id: sObj.id || '',
        name: hf91bServiceName(sObj),
        price: input.unitPrice,
        unitPrice: input.unitPrice,
        qty: 1,
        duration: hf91bServiceDuration(sObj),
        inputType: sObj.inputType || sObj.selection || '',
        pricingType: sObj.pricingType || sObj.pricingModel || '',
        department: sObj.department || sObj.dept || '',
        category: sObj.category || sObj.mainCategory || '',
        subCategory: sObj.subCategory || '',
        source: 'consultation_adjustment'
    };
    const rows = thConsultFinalTicketItems();
    if (rows.length) rows[0] = thConsultNormalizeTicketItem(consultSelectedPrimaryService);
    else rows.push(thConsultNormalizeTicketItem(consultSelectedPrimaryService));
    consultTicketItems = rows;
    thConsultSyncPendingUpsellsFromTicket();
    hf91bRefreshConsultTicketLabel();
    renderConsultUpsells();
};
window.hf91bResetConsultPrimaryService = function() {
    consultSelectedPrimaryService = null;
    consultTicketItems = thConsultBuildTicketItemsFromJob(currentConsultJobData || {});
    thConsultSyncPendingUpsellsFromTicket();
    const select = document.getElementById('consultPrimaryServiceSelect');
    if (select) select.value = '';
    hf91bRefreshConsultTicketLabel();
    renderConsultUpsells();
};

function thConsultUpsellIsCounterItem(item) {
    const raw = [
        item?.inputType,
        item?.selection,
        item?.pricingType,
        item?.unit,
        item?.unitLabel,
        item?.category,
        item?.subCategory,
        item?.name,
        item?.displayName
    ].map(v => String(v || '').toLowerCase()).join(' ');
    return raw.includes('counter') ||
           raw.includes('per nail') ||
           raw.includes('/ nail') ||
           raw.includes('per-nail') ||
           raw.includes('unit') ||
           raw.includes('stones') ||
           raw.includes('crystal') ||
           raw.includes('detailed art') ||
           raw.includes('simple art');
}

function thConsultUpsellUnitPrice(item) {
    const n = parseFloat(item?.unitPrice ?? item?.basePrice ?? item?.price ?? 0);
    return Number.isFinite(n) ? n : 0;
}

function thConsultUpsellQty(item) {
    const q = parseInt(item?.qty ?? item?.quantity ?? item?.count ?? 1, 10);
    return Number.isFinite(q) && q > 0 ? q : 1;
}

function thConsultNormalizeUpsell(item) {
    const input = thConsultFinancialInput(item);
    if (!input.valid) item.financialInputError = input.error;
    const qty = thConsultUpsellQty(item);
    const unitPrice = input.valid ? input.unitPrice : thConsultUpsellUnitPrice(item);
    item.qty = qty;
    item.quantity = qty;
    item.unitPrice = unitPrice;
    item.basePrice = unitPrice;
    item.price = unitPrice * qty;
    item.totalPrice = item.price;
    return item;
}

function renderConsultUpsells() {
    const listEl = document.getElementById('consultAddedUpsells');
    const totalEl = document.getElementById('consultProjectedTotal');
    if(!listEl || !totalEl || !currentConsultJobData) return;

    const safeHtml = (value) => (typeof _thEscapeHtml === 'function') ? _thEscapeHtml(String(value || '')) : String(value || '').replace(/[&<>'\"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[c]));

    consultTicketItems = thConsultFinalTicketItems();
    thConsultSyncPendingUpsellsFromTicket();

    if(!consultTicketItems.length) {
        listEl.innerHTML = `<div style="padding:10px 12px;border:1px dashed #d9d2c3;border-radius:14px;color:#7b7468;background:#fff;font-size:0.86rem;">No ticket items available. Add a service before updating the record.</div>`;
    } else {
        listEl.innerHTML = consultTicketItems.map((p, index) => {
            const name = safeHtml(p.name || p.displayName || 'Selected add-on');
            const isCounter = thConsultUpsellIsCounterItem(p);
            const qty = thConsultUpsellQty(p);
            const unitPrice = thConsultUpsellUnitPrice(p);
            const price = parseFloat(p.price || 0).toFixed(2);
            const subtitle = index === 0
                ? 'Base service'
                : (isCounter ? `Per nail / unit - ${qty} x ${unitPrice.toFixed(2)} GHC` : 'Ticket item');
            const counterHtml = isCounter ? `
                <div style="display:inline-flex;align-items:center;gap:8px;background:#f8f5ee;border:1px solid #e4dcc9;border-radius:999px;padding:4px 6px;">
                    <button type="button" aria-label="Reduce ${name}" onclick="changeConsultUpsellQty(${index}, -1)" style="border:0;background:#fff;color:#2f3746;border-radius:999px;width:28px;height:28px;font-weight:900;font-size:1rem;cursor:pointer;box-shadow:0 2px 6px rgba(0,0,0,.06);">−</button>
                    <strong style="min-width:22px;text-align:center;color:#2f3746;">${qty}</strong>
                    <button type="button" aria-label="Increase ${name}" onclick="changeConsultUpsellQty(${index}, 1)" style="border:0;background:#fff;color:#2f3746;border-radius:999px;width:28px;height:28px;font-weight:900;font-size:1rem;cursor:pointer;box-shadow:0 2px 6px rgba(0,0,0,.06);">+</button>
                </div>` : '';
            return `
                <div style="display:grid;grid-template-columns:1fr auto auto auto;align-items:center;gap:12px;margin:8px 0;padding:12px 14px;background:#fff;border:1px solid #e7e0cf;border-radius:16px;box-shadow:0 8px 22px rgba(47,55,70,0.05);">
                    <div style="min-width:0;">
                        <div style="color:#2f3746;font-weight:900;letter-spacing:0.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${index === 0 ? '' : '+ '}${name}</div>
                        <div style="color:#7b7468;font-size:0.78rem;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;margin-top:2px;">${safeHtml(subtitle)}</div>
                    </div>
                    ${counterHtml}
                    <div style="color:#4f9f59;font-weight:900;white-space:nowrap;">${price} GHC</div>
                    <button type="button" aria-label="Remove ${name}" onclick="removeUpsellFromTicket(${index})" style="border:1px solid #d9d2c3;background:#fff;color:#2f3746;border-radius:999px;width:34px;height:34px;display:inline-flex;align-items:center;justify-content:center;font-size:1.05rem;font-weight:900;cursor:pointer;line-height:1;">×</button>
                </div>`;
        }).join('');
    }

    try {
        const financials = thConsultCanonicalFinancials(consultTicketItems, currentConsultJobData);
        const total = window.thFinancialEvidence.firstAmount(financials, ['finalTotal','grandTotal']);
        totalEl.innerText = total === null ? 'Unavailable' : total.toFixed(2) + ' GHC';
    } catch(e) { totalEl.innerText = 'Financial review required'; }
    totalEl.style.transform = 'scale(1.035)';
    totalEl.style.transition = 'transform 160ms ease';
    setTimeout(() => { totalEl.style.transform = 'scale(1)'; }, 170);
}

window.addUpsellToTicket = function() {
    const select = document.getElementById('consultUpsellSelect');
    const btn = document.getElementById('btnConsultAddUpsell');
    const sId = select?.value;
    if(!sId) { alert('Please select an add-on before adding to the ticket.'); return; }
    if(btn?.disabled) return;

    const sObj = allMenuServicesCache.find(s => s.id === sId);
    if(!sObj) { alert('Selected add-on could not be found. Please refresh and try again.'); return; }

    const existingIndex = consultTicketItems.findIndex(p => String(p.id || '') === String(sId));
    if(existingIndex >= 0) {
        if (thConsultUpsellIsCounterItem(consultTicketItems[existingIndex])) {
            changeConsultUpsellQty(existingIndex, 1);
        } else {
            alert('This service is already on the ticket. Remove it first if this was a mistake.');
        }
        select.value = '';
        return;
    }

    const item = thConsultNormalizeUpsell({ ...sObj });
    setConsultButtonBusy(btn, true, 'Added');
    consultTicketItems.push(thConsultNormalizeTicketItem(item));
    renderConsultUpsells();
    select.value = '';
    window.ThurayaSessionResources.timeout(() => setConsultButtonBusy(btn, false), 350);
}

window.changeConsultUpsellQty = function(index, delta) {
    if(index < 0 || index >= consultTicketItems.length) return;
    const item = consultTicketItems[index];
    if(!thConsultUpsellIsCounterItem(item)) return;

    const nextQty = Math.max(1, thConsultUpsellQty(item) + (parseInt(delta, 10) || 0));
    item.qty = nextQty;
    item.quantity = nextQty;
    item.price = thConsultUpsellUnitPrice(item) * nextQty;
    item.totalPrice = item.price;
    renderConsultUpsells();
}

window.removeUpsellFromTicket = function(index) {
    if(index < 0 || index >= consultTicketItems.length) return;
    if(consultTicketItems.length <= 1) {
        alert('At least one service must remain on the ticket.');
        return;
    }
    consultTicketItems.splice(index, 1);
    renderConsultUpsells();
}

window.addUpsell = window.addUpsellToTicket;
window.removeUpsell = window.removeUpsellFromTicket;
window.changeUpsellQty = window.changeConsultUpsellQty;


function setConsultButtonBusy(btn, busy, busyText) {
    if(!btn) return;
    if(busy) {
        if(!btn.dataset.originalText) btn.dataset.originalText = btn.innerText;
        btn.disabled = true;
        if(busyText) btn.innerText = busyText;
        btn.style.opacity = '0.72';
        btn.style.pointerEvents = 'none';
    } else {
        btn.disabled = false;
        btn.innerText = btn.dataset.originalText || btn.innerText;
        btn.style.opacity = '1';
        btn.style.pointerEvents = '';
        delete btn.dataset.originalText;
    }
}

