window.requestReschedule = async function() {
    const btn = document.getElementById('btnConsultReqReschedule');
    if(btn?.disabled) return;
    if(!currentConsultJobId || !currentConsultJobData) {
        alert('No active service ticket is open. Please reopen the consultation.');
        return;
    }
    if(!confirm("Send this ticket back to Front of House for rescheduling review?\n\nNo booking will be cancelled.")) return;
    setConsultButtonBusy(btn, true, 'Sending to FOH...');
    try {
        const now = new Date().toISOString();
        const fohPayload = {
            status: 'FOH Review',
            serviceStatus: 'FOH Review',
            needsFOHAttention: true,
            fohAction: 'Reschedule Requested',
            rescheduleRequested: true,
            returnedToFOHAt: now,
            returnedToFOHBy: currentUserName || currentUserEmail || 'Staff',
            updatedAt: now
        };
        const apptTarget = await thFohResolveAppointmentRefForJob({ id: currentConsultJobId, ...currentConsultJobData });
        const batch = window.ThurayaManagedStaffOperations.batch('foh_reschedule',currentConsultJobId,{['Active_Jobs/'+currentConsultJobId]:currentConsultJobData});
        batch.update(db.collection('Active_Jobs').doc(currentConsultJobId), fohPayload);
        if(apptTarget && apptTarget.ref) {
            batch.set(apptTarget.ref, {
                status: 'Action Required',
                needsFOHAttention: true,
                fohAction: 'Reschedule Requested',
                rescheduleRequested: true,
                returnedToFOHAt: now,
                returnedToFOHBy: currentUserName || currentUserEmail || 'Staff',
                updatedAt: now
            }, { merge:true });
        } else {
            console.warn('THURAYA FOH return did not update Appointment because no safe unique appointment target was found', { activeJobId: currentConsultJobId });
        }
        await batch.commit();
        alert("Ticket sent to Front of House for rescheduling review. No cancellation was made.");
        closeConsultation();
    } catch(e) {
        alert("Error sending ticket to FOH: " + e.message);
        setConsultButtonBusy(btn, false, 'Request Reschedule');
    }
}
window.reqReschedule = window.requestReschedule;

window.saveConsultationAndStart = async function() {
    if(!currentConsultJobId || !currentConsultJobData) {
        alert("No active service ticket is open. Please reopen the consultation.");
        return;
    }

    if(!validateConsultComplianceBeforeStart()) return;

    const finalTicketItems = thConsultTicketItemsForSave();
    const primaryServiceForSave = finalTicketItems[0] || hf91bCurrentPrimaryService();
    const bookedServiceName = String(hf91bServiceName(primaryServiceForSave) || '').trim();
    const bookedPriceValue = hf91bServicePrice(primaryServiceForSave);
    const assignedTech = String(currentConsultJobData.assignedTechEmail || currentUserEmail || '').trim();

    if(!bookedServiceName) {
        alert("This ticket has no service attached. Please return it to Front of House before starting service.");
        return;
    }
    if(!Number.isFinite(bookedPriceValue) || bookedPriceValue < 0) {
        alert("This ticket has an invalid price. Please check the booking before starting service.");
        return;
    }
    if(!assignedTech) {
        alert("This ticket has no technician assigned. Please reassign it before starting service.");
        return;
    }

    const saveBtn = document.getElementById('btnConsultSaveStart');
    if(saveBtn?.disabled) return;
    setConsultButtonBusy(saveBtn, true, 'Saving...');

    let medChecks = [];
    document.querySelectorAll('.med-cb:checked').forEach(cb => medChecks.push(cb.value));
    if(document.getElementById('med_none').checked) medChecks = ["None"];

    let cust = {}; 
    consultTemplate.forEach(q => { 
        if(q.type === 'text') cust[q.id] = document.getElementById('ans_'+q.id)?.value || ''; 
        else if(q.type === 'checkbox') {
            let a = []; 
            document.querySelectorAll('.ans_cb_'+q.id+':checked').forEach(c => a.push(c.value)); 
            cust[q.id] = a;
        } else if(q.type === 'radio') {
            cust[q.id] = document.querySelector('input[name="ans_rd_'+q.id+'"]:checked')?.value || ''; 
        }
    });

    let consultData = {
        medicalHistory: medChecks,
        allergies: document.getElementById('med_allergies').value.trim(),
        otherMedical: document.getElementById('med_other').value.trim(),
        callusLevel: document.querySelector('input[name="cond_callus"]:checked')?.value || "Not specified",
        skinCondition: document.querySelector('input[name="cond_skin"]:checked')?.value || "Not specified",
        visualNotes: document.getElementById('cond_notes').value.trim(),
        customFields: cust,
        assessedAt: window.ThurayaManagedStaffOperations.FieldValue.serverTimestamp()
    };

    const finalPrimaryService = primaryServiceForSave;
    const ticketItemsForWrite = finalTicketItems.length
        ? finalTicketItems
        : [thConsultNormalizeTicketItem(finalPrimaryService)];
    try {
        const consultationFinancials = thConsultCanonicalFinancials(ticketItemsForWrite, currentConsultJobData);
        const financialUpdate = thConsultFinancialUpdate(consultationFinancials);
        const serviceAdjusted = !!consultSelectedPrimaryService;
        const shouldStampServiceStart = String(currentConsultJobData?.status || '') !== 'In Progress' && !currentConsultJobData?.serviceStartedAt;
        await window.ThurayaManagedStaffOperations.update('consultation',currentConsultJobId,db.collection('Active_Jobs').doc(currentConsultJobId),{
            status: 'In Progress',
            ...(shouldStampServiceStart ? { serviceStartedAt: window.ThurayaManagedStaffOperations.FieldValue.serverTimestamp() } : {}),
            consultationRecord: consultData,
            originalBookingSnapshot: hf91bOriginalBookingSnapshot(window.ThurayaManagedStaffOperations.FieldValue),
            consultationServiceAdjusted: serviceAdjusted,
            consultationAdjustedService: serviceAdjusted ? {
                serviceId: consultSelectedPrimaryService.id || '',
                serviceName: hf91bServiceName(consultSelectedPrimaryService),
                price: hf91bServicePrice(consultSelectedPrimaryService),
                duration: hf91bServiceDuration(consultSelectedPrimaryService),
                adjustedAt: window.ThurayaManagedStaffOperations.FieldValue.serverTimestamp(),
                adjustedBy: currentUserEmail || ''
            } : window.ThurayaManagedStaffOperations.FieldValue.delete(),
            ...financialUpdate,
            ...(consultationFinancials.preserveFinancialEvidence ? {} : {
                consultationTicketItems: ticketItemsForWrite
            })
        },currentConsultJobData,{activeJobReviewIntent:Object.keys(financialUpdate).length?{kind:'consultation',rows:ticketItemsForWrite}:undefined});
        closeConsultation();
    } catch(e) {
        alert("Error saving consultation: " + e.message);
        setConsultButtonBusy(saveBtn, false);
    }
}
window.saveConsult = window.saveConsultationAndStart;

let thTechQueueMessageSoundReady = false;
let thTechQueueMessageCache = new Map();
let thTechQueueLastSoundAt = 0;

function thPlayTechQueueNotificationSound() {
    try {
        const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextCtor) return;

        const nowMs = Date.now();
        if (nowMs - thTechQueueLastSoundAt < 1200) return;
        thTechQueueLastSoundAt = nowMs;

        const ctx = window.__thTechQueueAudioContext || new AudioContextCtor();
        window.__thTechQueueAudioContext = ctx;

        const play = () => {
            const start = ctx.currentTime;
            const master = ctx.createGain();
            master.gain.setValueAtTime(0.0001, start);
            master.gain.exponentialRampToValueAtTime(0.08, start + 0.03);
            master.gain.exponentialRampToValueAtTime(0.0001, start + 0.42);
            master.connect(ctx.destination);

            [880, 1174].forEach((freq, index) => {
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                const toneStart = start + (index * 0.14);
                osc.type = 'sine';
                osc.frequency.setValueAtTime(freq, toneStart);
                gain.gain.setValueAtTime(0.0001, toneStart);
                gain.gain.exponentialRampToValueAtTime(1, toneStart + 0.02);
                gain.gain.exponentialRampToValueAtTime(0.0001, toneStart + 0.16);
                osc.connect(gain);
                gain.connect(master);
                osc.start(toneStart);
                osc.stop(toneStart + 0.18);
            });
        };

        if (ctx.state === 'suspended') {
            ctx.resume().then(play).catch(() => {});
        } else {
            play();
        }
    } catch(e) {
        console.warn('Tech queue notification sound skipped:', e);
    }
}

function startTechQueueListener() {
    const queueDiv = document.getElementById('techLiveQueue');
    try {
        techQueueListener = window.ThurayaSessionResources.listen('tech-queue', db.collection('Active_Jobs')
            .where('assignedTechEmail', '==', currentUserEmail)
            .where('status', 'in', ['Waiting', 'In Progress']), snap => {
                const jobs = [];
                snap.forEach(doc => {
                    const job = doc.data() || {};
                    if (!isArchivedRecord(job)) jobs.push({ id: doc.id, ...job });
                });
                if(jobs.length === 0) {
                    queueDiv.innerHTML = '<p style="color: #999; font-style: italic;">Queue is currently empty.</p>';
                    thTechQueueMessageCache.clear();
                    thTechQueueMessageSoundReady = true;
                    return;
                }
                
                queueDiv.innerHTML = '';
                let shouldPlayMessageSound = false;
                jobs.forEach(job => {
                    const managerMessage = job.activeAtelierMessage || job.flagNote || '';
                    const previousMessage = thTechQueueMessageCache.get(job.id) || '';
                    if (managerMessage) {
                        if (thTechQueueMessageSoundReady && previousMessage !== managerMessage) {
                            shouldPlayMessageSound = true;
                        }
                        thTechQueueMessageCache.set(job.id, managerMessage);
                    } else {
                        thTechQueueMessageCache.delete(job.id);
                    }
                    
                    let div = document.createElement('div');
                    div.className = 'ticket';
                    div.style.borderColor = job.status === 'Waiting' ? 'var(--accent)' : 'var(--manager)';
                    
                    let infoDiv = document.createElement('div');
                    infoDiv.style.flexGrow = '1';
                    infoDiv.innerHTML = `
                        <h4 style="margin:0; font-size:1.1rem;">${job.clientName}</h4>
                        <span class="ticket-badge" style="background:${job.status === 'Waiting' ? '#f39c12' : '#2980b9'}; margin-bottom:5px;">${job.status.toUpperCase()}</span>
                        <p style="margin:0; font-size:0.85rem; color:var(--primary);">💅 <strong>${job.bookedService}</strong></p>
                    `;
                    if (managerMessage) {
                        infoDiv.insertAdjacentHTML('beforeend', `<div style="margin-top:8px; padding:8px 10px; border-left:4px solid var(--accent); background:#fffaf0; color:var(--primary); font-size:0.82rem;"><strong>Manager note:</strong> ${aa_escape(managerMessage)}</div>`);
                    }
                    
                    let btnWrapper = document.createElement('div');
                    btnWrapper.style.width = '140px';
                    
                    let btn = document.createElement('button');
                    btn.className = 'btn';
                    btn.style.width = '100%';
                    btn.style.padding = '8px';
                    btn.style.fontSize = '0.8rem';
                    
                    if (job.status === 'Waiting') {
                        btn.innerText = 'Consultation';
                        btn.addEventListener('click', () => window.openConsultation(job.id));
                    } else {
                        btn.innerText = 'Complete Job';
                        btn.style.background = 'var(--success)';
                        btn.addEventListener('click', async () => { 
                            try { await window.ThurayaManagedStaffOperations.update('ready_queue',job.id,db.collection('Active_Jobs').doc(job.id),{ status: 'Ready for Payment' }); }
                            catch(e) { alert("Error: " + e.message); }
                        });
                        
                        let btnEdit = document.createElement('button');
                        btnEdit.className = 'btn btn-secondary';
                        btnEdit.style.width = '100%';
                        btnEdit.style.padding = '5px';
                        btnEdit.style.marginBottom = '5px';
                        btnEdit.style.fontSize = '0.75rem';
                        btnEdit.innerText = 'Edit Record';
                        btnEdit.addEventListener('click', () => window.openConsultation(job.id));
                        btnWrapper.appendChild(btnEdit);
                    }
                    
                    btnWrapper.appendChild(btn);
                    div.appendChild(infoDiv);
                    div.appendChild(btnWrapper);
                    queueDiv.appendChild(div);
                });
                thTechQueueMessageSoundReady = true;
                if (shouldPlayMessageSound) thPlayTechQueueNotificationSound();
            });
    } catch(e) { console.error(e); }
}

function startFohBillingListener() {
    const listDiv = document.getElementById('fohPendingCheckoutList');
    try {
        fohBillingListener = db.collection('Active_Jobs')
            .where('status', '==', 'Ready for Payment')
            .onSnapshot(snap => {
                const jobs = [];
                snap.forEach(doc => {
                    const job = doc.data() || {};
                    if (!isArchivedRecord(job)) jobs.push({ id: doc.id, ...job });
                });
                if(jobs.length === 0) {
                    listDiv.innerHTML = '<p style="color: #999; font-style: italic;">No pending checkouts.</p>'; 
                    document.getElementById('checkoutPanel').style.display = 'none';
        window.THURAYA_CHECKOUT_JOB_DATA = null;
                    return; 
                }
                listDiv.innerHTML = '';
                jobs.forEach(job => {
                    
                    let taxes = [];
                    try { taxes = JSON.parse(job.taxBreakdown || '[]'); } catch(e){}
                    let subtotal = parseFloat(job.bookedPrice || 0).toFixed(2);
                    let originalTotal = parseFloat(job.originalTotal || job.grandTotal || job.bookedPrice || 0).toFixed(2);
                    let discountAmount = parseFloat(job.discountAmount || 0).toFixed(2);
                    let grandTotal = parseFloat(job.finalTotal || job.grandTotal || job.bookedPrice || 0).toFixed(2);
                    let hasPromo = !!(job.hasPromoApplied || job.promoCode);

                    let taxHtml = '';
                    taxes.forEach(t => { taxHtml += `<div style="display:flex; justify-content:space-between; font-size:0.8rem; color:#777;"><span>+ ${t.name}</span><span>${parseFloat(t.amount).toFixed(2)} GHC</span></div>`; });

                    let div = document.createElement('div');
                    div.className = 'ticket';
                    div.style.borderColor = 'var(--success)';
                    div.style.padding = '10px';
                    
                    let infoDiv = document.createElement('div');
                    infoDiv.style.flexGrow = '1';
                    infoDiv.innerHTML = `
                        <h4 style="margin:0; font-size:1rem; color:var(--success);">${job.clientName}</h4>
                        <p style="margin:0; font-size:0.8rem; margin-bottom:5px;">💅 ${job.bookedService}</p>
                        <div style="background:#f1f1f1; padding:8px; border-radius:4px; max-width:250px;">
                            <div style="display:flex; justify-content:space-between; font-size:0.8rem;"><span>Subtotal:</span><span>${subtotal} GHC</span></div>
                            ${taxHtml}
                            ${hasPromo ? `<div style="display:flex; justify-content:space-between; font-size:0.8rem; color:var(--accent);"><span>Promo ${job.promoCode || ''}:</span><span>- ${discountAmount} GHC</span></div>` : ''}
                            ${hasPromo ? `<div style="display:flex; justify-content:space-between; font-size:0.8rem; color:#777;"><span>Original:</span><span>${originalTotal} GHC</span></div>` : ''}
                            <div style="display:flex; justify-content:space-between; font-weight:bold; font-size:0.9rem; margin-top:3px; border-top:1px solid #ddd; padding-top:3px;"><span>Final Total:</span><span>${grandTotal} GHC</span></div>
                        </div>
                    `;
                    
                    let btn = document.createElement('button');
                    btn.className = 'btn';
                    btn.style.background = 'var(--success)';
                    btn.style.width = 'auto';
                    btn.style.padding = '5px 15px';
                    btn.style.fontSize = '0.8rem';
                    btn.innerText = 'Checkout';
                    btn.onclick = function() {
                        window.openCheckout(job.id, job.clientName, job.bookedService, subtotal, taxHtml, grandTotal, job);
                    };
                    
                    div.appendChild(infoDiv);
                    div.appendChild(btn);
                    listDiv.appendChild(div);
                });
            });
    } catch(e) { console.error(e); }
}

window.openCheckout = function(id, name, services, subtotal, taxHtml, grandTotal, jobData) {
    document.getElementById('checkoutJobId').value = id;
    document.getElementById('checkoutClientName').innerText = name;
    document.getElementById('checkoutServices').innerText = services;
    document.getElementById('checkoutSubtotal').innerText = subtotal + ' GHC';
    document.getElementById('checkoutTaxList').innerHTML = taxHtml;
    document.getElementById('checkoutTotal').innerText = grandTotal + ' GHC';
    document.getElementById('checkoutGrandTotalVal').value = grandTotal;
    const thGiftGrandV2 = document.getElementById('checkoutGrandTotalVal');
    if (thGiftGrandV2) thGiftGrandV2.dataset.originalGrandTotal = thGiftMoney(grandTotal).toFixed(2);
    document.getElementById('checkoutPaymentMethod').value = '';
    thGiftResetCheckout();
    document.getElementById('checkoutPanel').style.display = 'block';
    try { thGiftSyncCheckoutPaymentState(); } catch(e) {}
    renderCheckoutPromoNotice(jobData || {});
    window.THURAYA_CHECKOUT_JOB_DATA = { id, ...(jobData || {}) };
    document.getElementById('checkoutPanel').scrollIntoView({behavior: 'smooth'});
}

window.confirmPayment = async function() {
    const id = document.getElementById('checkoutJobId').value;
    let method = document.getElementById('checkoutPaymentMethod').value;
    const price = parseFloat(document.getElementById('checkoutGrandTotalVal').value) || 0; 
    
    if(!method) { alert("Please select a Payment Method."); return; }
    
    try {
        const checkoutJob = window.THURAYA_CHECKOUT_JOB_DATA || {};
        await db.collection('Active_Jobs').doc(id).update({
            status: 'Closed',
            paymentMethod: method,
            totalGHC: price,
            finalTotal: price,
            discountAmount: parseFloat(checkoutJob.discountAmount || 0),
            originalTotal: parseFloat(checkoutJob.originalTotal || price),
            promoCode: checkoutJob.promoCode || '',
            promoName: checkoutJob.promoName || '',
            promoType: checkoutJob.promoType || '',
            hasPromoApplied: !!(checkoutJob.hasPromoApplied || checkoutJob.promoCode),
            closedAt: firebase.firestore.FieldValue.serverTimestamp(),
            closedBy: currentUserEmail
        });

        await consumePackageWalletSession(checkoutJob, id);
        await recordSalesRedemption(checkoutJob, id, method);

        alert("Payment processed successfully!");
        document.getElementById('checkoutPanel').style.display = 'none';
    } catch(e) { alert("Error processing payment: " + e.message); }
}

window.generateReport = async function() {
    const start = document.getElementById('reportStart').value;
    const end = document.getElementById('reportEnd').value;
    if(!start || !end) { alert("Please select both a Start Date and End Date."); return; }

    try {
        const snap = await db.collection('Active_Jobs')
            .where('status', '==', 'Closed')
            .where('dateString', '>=', start)
            .where('dateString', '<=', end)
            .get();

        let totalRev = 0; let techStats = {};

        snap.forEach(doc => {
            const job = doc.data(); 
            if (isArchivedRecord(job)) return;
            totalRev = legacyReportAdd(totalRev, legacyReportRevenue(job));
        });

        document.getElementById('reportTotalRevenue').innerText = legacyReportMoney(totalRev) + " GHC";
        let tbody = '';
        for(const email in techStats) { tbody += `<tr><td><strong>${techStats[email].name}</strong></td><td style="text-align:center;">${techStats[email].count}</td><td style="text-align:right;">${techStats[email].rev.toFixed(2)} GHC</td></tr>`; }
        if(tbody === '') tbody = '<tr><td colspan="3" style="text-align:center; color: #999;">No completed services found in this date range.</td></tr>';
        
        document.getElementById('reportTechBody').innerHTML = tbody; document.getElementById('reportResults').style.display = 'block';
    } catch (e) { console.error(e); alert("Error generating report: " + e.message); }
}

function startFohFinancialListener() {
    try {
        fohFinancialListener = window.ThurayaSessionResources.listen('foh-financial', db.collection('Active_Jobs').where('status', '==', 'Closed').where('dateString', '==', todayDateStr), snap => {
            let totalRev = 0; let jobCount = 0;
            snap.forEach(doc => {
                const job = doc.data() || {};
                if (isArchivedRecord(job)) return;
                totalRev = legacyReportAdd(totalRev, legacyReportRevenue(job));
                jobCount++;
            });
            document.getElementById('fohDailyRevenue').innerText = legacyReportMoney(totalRev) + " GHC"; document.getElementById('fohDailyJobs').innerText = jobCount;
        });
    } catch(e) { console.error(e); }
}

function startTechFinancialListener() {
    try {
        techFinancialListener = window.ThurayaSessionResources.listen('tech-financial', db.collection('Active_Jobs')
            .where('status', '==', 'Closed')
            .where('dateString', '==', todayDateStr)
            .where('assignedTechEmail', '==', currentUserEmail), snap => {
                let techRev = 0; let serviceCount = 0;
                snap.forEach(doc => {
                    let job = doc.data();
                    if (isArchivedRecord(job)) return;
                    techRev = legacyReportAdd(techRev, legacyReportRevenue(job));
                    serviceCount++;
                });
                document.getElementById('techDailyRevenue').innerText = legacyReportMoney(techRev) + " GHC";
                document.getElementById('techServiceCount').innerText = serviceCount;
            });
    } catch(e) { console.error(e); }
}

function thFohRosterNormalizeEmail(value) {
    return String(value || '').trim().toLowerCase();
}

function thFohRosterDateValue(value) {
    if (!value) return '';
    if (typeof value === 'string') return value.slice(0, 10);
    if (value && typeof value.toDate === 'function') {
        try { return value.toDate().toISOString().slice(0, 10); } catch(e) {}
    }
    if (value instanceof Date) return value.toISOString().slice(0, 10);
    return '';
}

function thFohRosterMillis(value) {
    if (!value) return 0;
    if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
    if (value && typeof value.toMillis === 'function') {
        try { return value.toMillis(); } catch(e) {}
    }
    if (value && typeof value.toDate === 'function') {
        try { return value.toDate().getTime(); } catch(e) {}
    }
    if (value instanceof Date) return value.getTime();
    if (typeof value === 'string') {
        const parsed = Date.parse(value);
        return Number.isFinite(parsed) ? parsed : 0;
    }
    return 0;
}

function thFohRosterDayAbbr(dateStr) {
    const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    return days[new Date(dateStr + 'T12:00:00').getDay()];
}

function thFohRosterScheduleRecord(data, sourceOrder) {
    if (!data) return null;
    return {
        workingDays: Array.isArray(data.workingDays) ? data.workingDays : [],
        startTime: data.startTime || '08:00',
        endTime: data.endTime || '20:00',
        effectiveFrom: thFohRosterDateValue(data.effectiveFrom) || '0000-00-00',
        _savedMillis: Math.max(thFohRosterMillis(data.savedAt), thFohRosterMillis(data.updatedAt), thFohRosterMillis(data.savedAtMs)),
        _sourceOrder: sourceOrder || 0
    };
}

function thFohRosterScheduleRecordsFromData(data, sourceOrder) {
    if (!data) return [];
    const segments = [];
    if (Array.isArray(data.scheduleSegments)) {
        data.scheduleSegments.forEach(segment => {
            const record = thFohRosterScheduleRecord(segment, sourceOrder || 3);
            if (record && record.workingDays.length) segments.push(record);
        });
    }
    if (segments.length) return segments;

    const records = [];
    const current = thFohRosterScheduleRecord(data, sourceOrder || 2);
    if (current && current.workingDays.length) records.push(current);
    return records;
}

function thFohRosterCompareSchedules(a, b) {
    const eff = String(b.effectiveFrom || '').localeCompare(String(a.effectiveFrom || ''));
    if (eff) return eff;
    const saved = (b._savedMillis || 0) - (a._savedMillis || 0);
    if (saved) return saved;
    return (b._sourceOrder || 0) - (a._sourceOrder || 0);
}

function thFohRosterDefaultSchedule() {
    return {
        workingDays: ['Mon','Tue','Wed','Thu','Fri','Sat'],
        startTime: '08:00',
        endTime: '20:00',
        effectiveFrom: '0000-00-00',
        _isDefault: true
    };
}

function thFohRosterResolveScheduleForDate(records, dateStr) {
    const dayAbbr = thFohRosterDayAbbr(dateStr);
    const effective = (records || [])
        .filter(Boolean)
        .filter(s => !s.effectiveFrom || s.effectiveFrom <= dateStr)
        .sort(thFohRosterCompareSchedules);

    if (!effective.length) return thFohRosterDefaultSchedule();

    const latest = effective[0] || {};
    if ((latest.workingDays || []).includes(dayAbbr)) return latest;

    // The newest effective schedule is authoritative; older records must not revive a configured day off.
    return {
        ...latest,
        startTime: latest.startTime || '08:00',
        endTime: latest.endTime || '20:00',
        _isDayOff: true
    };
}

async function thFohRosterScheduleHistoryRecords(email) {
    try {
        const snap = await db.collection('Staff_Schedules').doc(email)
            .collection('history')
            .orderBy('savedAt', 'desc')
            .limit(60)
            .get();
        return snap.docs.flatMap(d => thFohRosterScheduleRecordsFromData(d.data(), 1)).filter(Boolean);
    } catch(e) {
        console.warn('FOH roster schedule history unavailable:', email, e);
        return [];
    }
}

async function thFohRosterBuildScheduleMapForDate(emails, dateStr, schedSnap) {
    const current = {};
    schedSnap.forEach(d => {
        const key = thFohRosterNormalizeEmail(d.id);
        if (key) current[key] = { id: d.id, data: d.data() || {} };
    });

    const cleanEmails = Array.from(new Set((emails || []).map(thFohRosterNormalizeEmail).filter(Boolean)));
    const entries = await Promise.all(cleanEmails.map(async email => {
        const records = [];
        if (current[email]) records.push(...thFohRosterScheduleRecordsFromData(current[email].data, 2));
        records.push(...await thFohRosterScheduleHistoryRecords(current[email]?.id || email));
        return [email, thFohRosterResolveScheduleForDate(records, dateStr)];
    }));

    return entries.reduce((map, [email, schedule]) => {
        map[email] = schedule || thFohRosterDefaultSchedule();
        return map;
    }, {});
}

function thFohRosterApprovedLeaveSet(dateStr, leaveSnap) {
    const onLeave = new Set();
    leaveSnap.forEach(d => {
        const leave = d.data() || {};
        const email = thFohRosterNormalizeEmail(leave.techEmail);
        const status = String(leave.status || 'Approved').trim();
        const startDate = thFohRosterDateValue(leave.startDate);
        const endDate = thFohRosterDateValue(leave.endDate);
        if (status === 'Approved' && email && startDate && endDate && startDate <= dateStr && endDate >= dateStr) {
            onLeave.add(email);
        }
    });
    return onLeave;
}

function thFohRosterAttendanceEmail(tech, docId, dateStr) {
    const email = thFohRosterNormalizeEmail(tech && tech.email);
    if (email) return email;
    const id = String(docId || '');
    const suffix = `_${dateStr}`;
    if (id.endsWith(suffix)) return thFohRosterNormalizeEmail(id.slice(0, -suffix.length));
    return thFohRosterNormalizeEmail(id.split('_')[0]);
}

function thFohRosterIsTechLike(tech) {
    const roles = Array.isArray(tech && tech.roles) ? tech.roles.join(',') : '';
    const roleString = String((tech && tech.roleString) || roles || '').toLowerCase();
    return roleString.includes('tech') || roleString.includes('test tech');
}

function startFohRosterListener() {
    if (!window.ThurayaSessionResources.active() || window.ThurayaSessionResources.has('foh-roster')) return;
    const rosterDiv = document.getElementById('fohRosterList');
    const attendanceApi = window.thurayaAttendance;
    if (!rosterDiv) return;
    if (!attendanceApi?.listenDay) {
        rosterDiv.innerHTML = '<p style="color:#999;font-style:italic;">Attendance aggregation is unavailable.</p>';
        return;
    }

    try {
        if (fohRosterListener) {
            try { fohRosterListener(); } catch(e) {}
        }

        fohRosterListener = window.ThurayaSessionResources.manage('foh-roster', (currentSession, stop) => attendanceApi.listenDay(db, todayDateStr, async (attendanceAgg) => {
            if (!currentSession()) return;
            try {
                const activeJobsSnap = await db.collection('Active_Jobs').where('status', 'in', ['Waiting', 'In Progress']).get();
                if (!currentSession()) return;
                const busyTechEmails = new Set();
                activeJobsSnap.forEach(job => {
                    const data = job.data() || {};
                    if (!isArchivedRecord(data)) busyTechEmails.add(thFohRosterNormalizeEmail(data.assignedTechEmail));
                });

                const scheduledSnap = await db.collection('Appointments').where('dateString', '==', todayDateStr).where('status', '==', 'Scheduled').get();
                if (!currentSession()) return;
                const now = new Date();
                const currentMins = now.getHours() * 60 + now.getMinutes();

                scheduledSnap.forEach(doc => {
                    const appt = doc.data() || {};
                    if (isArchivedRecord(appt)) return;
                    const aStart = timeToMins(appt.timeString);
                    const aEnd = aStart + parseInt(appt.bookedDuration || 0, 10);
                    if (currentMins >= aStart && currentMins < aEnd) {
                        busyTechEmails.add(thFohRosterNormalizeEmail(appt.assignedTechEmail));
                    }
                });

                const staffByEmail = new Map((typeof allTechs !== 'undefined' ? allTechs : []).map(t => [thFohRosterNormalizeEmail(t.email), t]));
                const aggregates = (attendanceAgg?.aggregates || [])
                    .filter(aggregate => aggregate?.isPresent)
                    .map(aggregate => {
                        const email = thFohRosterNormalizeEmail(aggregate.email || aggregate.technicianKey);
                        return { aggregate, email, staff: staffByEmail.get(email) || null };
                    })
                    .filter(row => row.email)
                    .filter(row => thFohRosterIsTechLike(row.aggregate) || thFohRosterIsTechLike(row.staff) || !!row.staff)
                    .sort((a, b) => String(a.aggregate.name || a.staff?.name || a.email).localeCompare(String(b.aggregate.name || b.staff?.name || b.email)));

                let html = '';
                aggregates.forEach(({ aggregate, email, staff }) => {
                    const name = aggregate.name || staff?.name || email;
                    const isBusy = aggregate.onLunch || busyTechEmails.has(email);
                    const statusDot = isBusy ? 'status-busy' : 'status-available';
                    const statusLabel = aggregate.onLunch ? 'ON LUNCH' : (isBusy ? 'BUSY' : 'AVAILABLE');
                    const statusColor = isBusy ? 'var(--error)' : 'var(--success)';
                    const statusText = `<span style="color:${statusColor}; font-size:0.8rem; font-weight:bold;">${statusLabel}</span>`;
                    const diagnostic = aggregate.multipleOpen ? ' title="Multiple open attendance sessions detected; showing one technician row."' : '';
                    html += `<div class="roster-item"${diagnostic}><div><strong>${attendanceApi.escapeHtml(name)}</strong></div><div style="display:flex; align-items:center;"><span class="status-dot ${statusDot}"></span> ${statusText}</div></div>`;
                });

                if (html === '') html = '<p style="color:#999;font-style:italic;">No Technicians currently on the floor.</p>';
                rosterDiv.innerHTML = html;
            } catch(e) {
                if (!currentSession()) return;
                console.warn('FOH roster aggregate render failed', e);
                rosterDiv.innerHTML = '<p style="color:#999;font-style:italic;">No Technicians currently on the floor.</p>';
            }
        }, err => { if (currentSession()) { stop(); console.error('FOH roster Attendance listener failed', err); } }));
    } catch(e) { console.error(e); }
}

function normalizeTherapyTypes(data = {}) {
    let raw = Array.isArray(data.therapyTypes) ? data.therapyTypes : [];
    raw = raw.map(v => String(v || '').toLowerCase().trim()).filter(Boolean);

    if (raw.includes('both')) return ['hand', 'foot'];
    raw = raw.filter(v => v === 'hand' || v === 'foot');

    const roles = Array.isArray(data.roles) ? data.roles : (data.role ? [data.role] : []);
    const isTech = roles.some(r => String(r || '').toLowerCase().includes('tech'));

    // Safe default: existing technicians are treated as Both until Admin assigns otherwise.
    if (!raw.length && isTech) return ['hand', 'foot'];
    return Array.from(new Set(raw));
}

function therapyLabelFromTypes(types = []) {
    const normalized = normalizeTherapyTypes({ therapyTypes: types, roles: ['Tech'] });
    if (normalized.includes('hand') && normalized.includes('foot')) return 'Both';
    if (normalized.includes('hand')) return 'Hand';
    if (normalized.includes('foot')) return 'Foot';
    return '—';
}

function getAdminTherapyTypes() {
    const hand = document.getElementById('admin_therapyHand')?.checked === true;
    const foot = document.getElementById('admin_therapyFoot')?.checked === true;
    const types = [];
    if (hand) types.push('hand');
    if (foot) types.push('foot');
    return types;
}

window.loadStaffDirectory = function() {
    const listDiv = document.getElementById('adminStaffList');
    if (!listDiv) return;

    listDiv.innerHTML = '<p style="color: #000; font-weight:bold;">Loading directory... Please wait.</p>';

    window.ThurayaSessionResources.listen('staff-directory', db.collection('Users'), (snap) => {
        if (snap.empty) { listDiv.innerHTML = '<p style="color: #999;">No staff found.</p>'; return; }

        listDiv.innerHTML = '';
        const table = document.createElement('table');
        table.className = 'breakdown-table'; table.style.marginTop = '0';
        const thead = document.createElement('thead');
        thead.innerHTML = '<tr><th>Profile</th><th>Google Email</th><th>Departments</th><th>Therapy</th><th>Staff ID</th><th style="text-align:center;">Client Visible</th><th style="text-align:center;">Action</th></tr>';
        table.appendChild(thead);
        const tbody = document.createElement('tbody');

        snap.forEach(doc => {
            try {
                let data = doc.data() || {};
                let name = data.name ? String(data.name).replace(/['"]/g, "") : "Unknown";
                let email = doc.id;
                let staffId = data.staffId || '';
                let photoUrl = data.photoUrl || '';

                let rolesArr = [];
                if (data.roles && Array.isArray(data.roles)) { rolesArr = data.roles; } 
                else if (data.roles && typeof data.roles === 'string') { rolesArr = [data.roles]; } 
                else if (data.role && typeof data.role === 'string') { rolesArr = [data.role]; }

                let validRoles = rolesArr.filter(r => r);
                let rolesStr = validRoles.join(',');
                let tagsHtml = validRoles.map(r => {
                    let c = (r.toLowerCase().includes('admin')) ? 'var(--admin)' : (r === 'Manager' ? 'var(--manager)' : (r === 'Supply Chain' ? 'var(--supply)' : (r === 'FOH' ? '#e74c3c' : 'var(--primary)')));
                    return `<span class="ticket-badge" style="background:${c}; margin-right: 5px; display:inline-block; margin-bottom:3px;">${r}</span>`;
                }).join('');

                let tr = document.createElement('tr');
                
                let tdName = document.createElement('td'); 
                tdName.innerHTML = `<div style="display:flex; align-items:center; gap:10px;">
                    <img src="${photoUrl || ''}" onerror="this.style.display='none';" style="width:38px; height:38px; border-radius:50%; object-fit:cover; border:1px solid var(--border); background:#f3f4f6;">
                    <div><strong>${name}</strong><br><span style="font-size:0.75rem; color:#777;">${data.phone || ''}</span></div>
                </div>`;
                let tdEmail = document.createElement('td'); tdEmail.style.color = '#666'; tdEmail.innerText = email;
                let tdRoles = document.createElement('td'); tdRoles.innerHTML = tagsHtml;
                const therapyTypes = normalizeTherapyTypes(data);
                let tdTherapy = document.createElement('td');
                tdTherapy.innerHTML = `<span class="therapy-badge therapy-badge-${therapyLabelFromTypes(therapyTypes).toLowerCase()}">${therapyLabelFromTypes(therapyTypes)}</span>`;
                let tdStaffId = document.createElement('td'); tdStaffId.innerText = staffId || '—';
                
                let tdAction = document.createElement('td');
                tdAction.style.textAlign = 'center'; tdAction.style.display = 'flex'; tdAction.style.gap = '5px'; tdAction.style.justifyContent = 'center';

                // visibleToClients toggle — only relevant for techs
                const isTechRow = validRoles.some(r => r.toLowerCase().includes('tech'));
                const isVisible = data.visibleToClients !== false;
                let tdVisible = document.createElement('td');
                tdVisible.style.textAlign = 'center';
                tdVisible.style.verticalAlign = 'middle';
                if (isTechRow) {
                    tdVisible.innerHTML = `<button onclick="window.toggleClientVisible('${email}', ${isVisible})"
                        style="border:none; background:${isVisible ? 'var(--success)' : '#ccc'}; color:white;
                        padding:4px 12px; border-radius:12px; cursor:pointer; font-size:0.75rem; font-weight:700;">
                        ${isVisible ? '✓ Visible' : '✕ Hidden'}
                    </button>`;
                } else {
                    tdVisible.innerHTML = '<span style="color:#ccc; font-size:0.75rem;">N/A</span>';
                }

                let btnEdit = document.createElement('button');
                btnEdit.className = 'btn'; btnEdit.style.cssText = 'padding:5px 10px; width:auto; font-size:0.75rem; background:var(--primary);';
                btnEdit.innerText = 'Edit'; btnEdit.onclick = function() { window.editStaff(email, name, rolesStr, data); };

                let btnRevoke = document.createElement('button');
                btnRevoke.className = 'btn btn-secondary'; btnRevoke.style.cssText = 'padding:5px 10px; width:auto; font-size:0.75rem; color:red; border-color:red;';
                btnRevoke.innerText = 'Del'; btnRevoke.onclick = function() { window.removeStaffAccount(email); };

                tdAction.appendChild(btnEdit); tdAction.appendChild(btnRevoke);
                tr.appendChild(tdName); tr.appendChild(tdEmail); tr.appendChild(tdRoles); tr.appendChild(tdTherapy); tr.appendChild(tdStaffId); tr.appendChild(tdVisible); tr.appendChild(tdAction);
                tbody.appendChild(tr);

            } catch(innerErr) { console.log("Skipped corrupted user:", doc.id); }
        });
        table.appendChild(tbody); listDiv.appendChild(table);
    }, (error) => {
        listDiv.innerHTML = `<div style="background:#ffebee; padding:15px; border:1px solid red; border-radius:4px; color:red;"><strong>Database Error!</strong><br>${error.message}</div>`;
    });
}

window.editStaff = function(email, name, rolesStr, profileData = {}) {
    document.getElementById('admin_newEmail').value = email;
    document.getElementById('admin_newName').value = name;
    document.getElementById('admin_newPassword').value = '';
    document.getElementById('admin_newPassword').placeholder = "(Leave blank to keep current password)";
    
    const safeRoles = rolesStr.toLowerCase().split(',');
    document.querySelectorAll('.role-checkbox').forEach(cb => { cb.checked = safeRoles.includes(cb.value.toLowerCase()); });

    const setProfile = (id, val) => {
        const el = document.getElementById(id);
        if (el) el.value = val || '';
    };
    setProfile('admin_staffId', profileData.staffId);
    setProfile('admin_staffPhone', profileData.phone);
    setProfile('admin_dateJoined', profileData.dateJoined);
    setProfile('admin_dateOfBirth', profileData.dateOfBirth);
    setProfile('admin_pensionNumber', profileData.pensionNumber);
    setProfile('admin_emergencyContactName', profileData.emergencyContactName);
    setProfile('admin_emergencyContactPhone', profileData.emergencyContactPhone);
    setProfile('admin_photoUrl', profileData.photoUrl);
    const therapyTypes = normalizeTherapyTypes(profileData);
    const therapyHandEl = document.getElementById('admin_therapyHand');
    const therapyFootEl = document.getElementById('admin_therapyFoot');
    if (therapyHandEl) therapyHandEl.checked = therapyTypes.includes('hand');
    if (therapyFootEl) therapyFootEl.checked = therapyTypes.includes('foot');
    previewStaffPhotoUrl();
    setStaffAccountFormMode('edit', email);

    window.scrollTo(0, 0);
}


window.uploadStaffPhoto = uploadStaffPhoto;
window.previewStaffPhotoUpload = previewStaffPhotoUpload;
window.previewStaffPhotoUrl = previewStaffPhotoUrl;
window.clearStaffPhotoUpload = clearStaffPhotoUpload;

function collectStaffAccountFormData() {
    const name = document.getElementById('admin_newName').value.trim();
    const email = document.getElementById('admin_newEmail').value.trim().toLowerCase();
    const password = document.getElementById('admin_newPassword').value;
    const selectedRoles = Array.from(document.querySelectorAll('.role-checkbox:checked')).map(cb => cb.value);
    const isTechnician = selectedRoles.some(r => String(r || '').toLowerCase().includes('tech'));
    let therapyTypes = getAdminTherapyTypes();
    if (isTechnician && therapyTypes.length === 0) therapyTypes = ['hand', 'foot'];

    return {
        name,
        email,
        password,
        selectedRoles,
        therapyTypes,
        staffId: document.getElementById('admin_staffId')?.value.trim() || '',
        phone: document.getElementById('admin_staffPhone')?.value.trim() || '',
        dateJoined: document.getElementById('admin_dateJoined')?.value || '',
        dateOfBirth: document.getElementById('admin_dateOfBirth')?.value || '',
        pensionNumber: document.getElementById('admin_pensionNumber')?.value.trim() || '',
        emergencyContactName: document.getElementById('admin_emergencyContactName')?.value.trim() || '',
        emergencyContactPhone: document.getElementById('admin_emergencyContactPhone')?.value.trim() || '',
        photoUrl: document.getElementById('admin_photoUrl')?.value.trim() || ''
    };
}

function buildStaffAccountPayload(form) {
    return {
        name: form.name,
        email: form.email,
        roles: form.selectedRoles,
        therapyTypes: form.therapyTypes,
        staffId: form.staffId,
        phone: form.phone,
        dateJoined: form.dateJoined,
        dateOfBirth: form.dateOfBirth,
        pensionNumber: form.pensionNumber,
        emergencyContactName: form.emergencyContactName,
        emergencyContactPhone: form.emergencyContactPhone,
        photoUrl: form.photoUrl,
        active: true,
        updatedBy: currentUserEmail,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    };
}

function resetStaffAccountFormAfterSave() {
    document.getElementById('admin_newName').value = '';
    document.getElementById('admin_newEmail').value = '';
    document.getElementById('admin_newPassword').value = '';
    document.querySelectorAll('.role-checkbox').forEach(cb => cb.checked = false);
    clearAdminProfileFields();
    clearStaffPhotoUpload();
    setStaffAccountFormMode('create');
}

window.addStaffAccount = async function() {
    const form = collectStaffAccountFormData();

    if(!form.name || !form.email || form.selectedRoles.length === 0) {
        alert("Please fill all required fields and select at least one department.");
        return;
    }

    try {
        const existingDoc = await db.collection('Users').doc(form.email).get();
        if (existingDoc.exists) {
            alert(`A staff profile already exists for ${form.email}. Use Edit, then Update Staff Profile.`);
            return;
        }
    } catch(checkErr) {
        alert("Could not verify duplicate staff profile: " + checkErr.message);
        return;
    }

    if (form.password) {
        try {
            await secondaryApp.auth().createUserWithEmailAndPassword(form.email, form.password);
            await secondaryApp.auth().signOut();
        } catch (authError) {
            if(authError.code !== 'auth/email-already-in-use') {
                alert(`Failed to create login credential.\n\nError: ${authError.message}`);
                return;
            }
        }
    }

    try {
        const payload = buildStaffAccountPayload(form);
        payload.createdBy = currentUserEmail;
        payload.createdAt = firebase.firestore.FieldValue.serverTimestamp();
        await db.collection('Users').doc(form.email).set(payload, { merge: false });
        alert(`Success! Staff profile created for ${form.name}.`);
        resetStaffAccountFormAfterSave();
        fetchAllTechs();
    } catch(dbError) {
        alert("Database Error: " + dbError.message);
    }
}

window.updateStaffAccount = async function() {
    const form = collectStaffAccountFormData();
    const originalEmail = String(adminEditingStaffEmail || window.adminEditingStaffEmail || '').trim().toLowerCase();

    if (!originalEmail) {
        alert('No staff profile is selected for update. Select Edit from the staff directory first.');
        return;
    }
    if(!form.name || !form.email || form.selectedRoles.length === 0) {
        alert("Please fill all required fields and select at least one department.");
        return;
    }
    if (form.email !== originalEmail) {
        alert('Email is locked during Edit Mode to prevent duplicate staff records. Cancel edit and create a new staff profile if the email must change.');
        return;
    }

    if (form.password) {
        const proceed = confirm('Updating a password from this screen may require Firebase Authentication permissions. Continue with profile update and attempt credential creation only if needed?');
        if (!proceed) return;
        try {
            await secondaryApp.auth().createUserWithEmailAndPassword(form.email, form.password);
            await secondaryApp.auth().signOut();
        } catch (authError) {
            if(authError.code !== 'auth/email-already-in-use') {
                alert(`Failed to create login credential.\n\nError: ${authError.message}`);
                return;
            }
        }
    }

    try {
        await db.collection('Users').doc(originalEmail).set(buildStaffAccountPayload(form), { merge: true });
        alert(`Success! Staff profile updated for ${form.name}.`);
        resetStaffAccountFormAfterSave();
        fetchAllTechs();
    } catch(dbError) {
        alert("Database Error: " + dbError.message);
    }
}


window.removeStaffAccount = async function(email) {
    if(email === currentUserEmail) { alert("You cannot revoke your own admin access from here."); return; }
    if(confirm(`Are you absolutely sure you want to permanently revoke system access for ${email}?`)) {
        try { await db.collection('Users').doc(email).delete(); alert("Access revoked."); fetchAllTechs(); } 
        catch(e) { alert("Error revoking access: " + e.message); }
    }
}

window.toggleClientVisible = async function(email, currentlyVisible) {
    const newVal = !currentlyVisible;
    const label  = newVal ? 'visible to clients' : 'hidden from clients';
    if (!confirm(`Set ${email} as ${label}?`)) return;
    try {
        await db.collection('Users').doc(email).update({ visibleToClients: newVal });
        fetchAllTechs();
    } catch(e) { alert('Error updating visibility: ' + e.message); }
}

