        document.querySelectorAll("div").forEach(el => {
            const txt = (el.innerText || "").trim();
            if (txt === "Closed jobs, pending jobs, revenue and status") {
                el.innerText = "Revenue jobs, pending jobs, revenue and status";
            }
        });
