// ============================================================================
// THURAYA PHASE 5.3A PATCH
// Targets Engine
// Adds staff revenue target calculations on top of Performance Intelligence.
// No UI layout changes yet.
// Collections:
// - Performance_Metrics: already used by performance engine
// - Staff_Targets: optional target settings per staff
// ============================================================================

(function () {
    const TARGETS53A = {
        cache: []
    };
    window.ThurayaSessionResources.onStop('targets-53-cache', () => { TARGETS53A.cache = []; });

    function t53_today() {
        try {
            if (typeof getLocalDateString === "function") return getLocalDateString();
        } catch(e) {}
        const d = new Date();
        return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
    }

    function t53_range(type) {
        const today = t53_today();
        const now = new Date(today + "T00:00:00");

        if (type === "week") {
            const day = now.getDay();
            const diff = day === 0 ? 6 : day - 1;
            const start = new Date(now);
            start.setDate(now.getDate() - diff);
            return { start: start.toISOString().slice(0,10), end: today, label: "This Week", type: "week" };
        }

        if (type === "month") {
            return {
                start: `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}-01`,
                end: today,
                label: "This Month",
                type: "month"
            };
        }

        return { start: today, end: today, label: "Today", type: "today" };
    }

    function t53_num(v, fallback = 0) {
        const n = parseFloat(v);
        return isNaN(n) ? fallback : n;
    }

    function t53_daysBetweenInclusive(startStr, endStr) {
        try {
            const start = new Date(startStr + "T00:00:00");
            const end = new Date(endStr + "T00:00:00");
            const diff = Math.floor((end - start) / 86400000) + 1;
            return Math.max(1, diff);
        } catch(e) {
            return 1;
        }
    }

    function t53_defaultTarget(range) {
        // Conservative defaults for staging/testing.
        // These can be overridden in Staff_Targets.
        const daily = 500;
        if (range.type === "today") return daily;
        if (range.type === "week") return daily * t53_daysBetweenInclusive(range.start, range.end);
        if (range.type === "month") return daily * t53_daysBetweenInclusive(range.start, range.end);
        return daily;
    }

    async function t53_getStaffTarget(email, range) {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        if (!email) return t53_defaultTarget(range);

        try {
            const ref = db.collection("Staff_Targets").doc(String(email).toLowerCase());
            const doc = await ref.get();
            if (!isCurrentSession()) return;

            if (!doc.exists) return t53_defaultTarget(range);

            const d = doc.data() || {};

            if (range.type === "today") {
                return t53_num(d.dailyTarget || d.targetDaily || d.revenueTargetDaily, t53_defaultTarget(range));
            }

            if (range.type === "week") {
                const explicit = t53_num(d.weeklyTarget || d.targetWeekly || d.revenueTargetWeekly, 0);
                if (explicit > 0) return explicit;

                const daily = t53_num(d.dailyTarget || d.targetDaily || d.revenueTargetDaily, 500);
                return daily * t53_daysBetweenInclusive(range.start, range.end);
            }

            if (range.type === "month") {
                const explicit = t53_num(d.monthlyTarget || d.targetMonthly || d.revenueTargetMonthly, 0);
                if (explicit > 0) return explicit;

                const daily = t53_num(d.dailyTarget || d.targetDaily || d.revenueTargetDaily, 500);
                return daily * t53_daysBetweenInclusive(range.start, range.end);
            }

            return t53_defaultTarget(range);

        } catch(e) {
            if (!isCurrentSession()) return;
            console.warn("Target lookup failed for", email, e);
            return t53_defaultTarget(range);
        }
        if (!isCurrentSession()) return;
    }

    function t53_status(percent) {
        if (percent >= 100) return "Achieved";
        if (percent >= 80) return "On Track";
        if (percent >= 50) return "Watch";
        return "Behind";
    }

    function t53_gap(revenue, target) {
        return Math.max(0, Math.round((target - revenue) * 100) / 100);
    }

    window.thuraya_buildTargetMetrics = async function(rangeType = "today") {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        const range = t53_range(rangeType);

        if (typeof window.thuraya_buildPerformanceMetrics !== "function") {
            throw new Error("Performance engine not found. Build Phase 5.2 first.");
        }

        const performanceRows = await window.thuraya_buildPerformanceMetrics(rangeType);
        if (!isCurrentSession()) return;

        const rows = [];

        for (const row of performanceRows) {
            const target = await t53_getStaffTarget(row.email, range);
            if (!isCurrentSession()) return;
            const revenue = t53_num(row.totalRevenue, 0);
            const achievementPercent = target > 0
                ? Math.round((revenue / target) * 1000) / 10
                : 0;

            rows.push({
                ...row,
                range: range.label,
                rangeType,
                targetRevenue: Math.round(target * 100) / 100,
                actualRevenue: revenue,
                achievementPercent,
                targetGap: t53_gap(revenue, target),
                targetStatus: t53_status(achievementPercent),
                targetRule: "Staff_Targets_or_Default"
            });
        }
        if (!isCurrentSession()) return;

        rows.sort((a,b) =>
            (b.achievementPercent - a.achievementPercent) ||
            (b.actualRevenue - a.actualRevenue) ||
            (b.efficiencyScore - a.efficiencyScore)
        );

        rows.forEach((r, i) => r.targetRank = i + 1);

        TARGETS53A.cache = rows;

        try {
            await t53_saveTargets(rows, rangeType, range);
            if (!isCurrentSession()) return;
        } catch(e) {
            if (!isCurrentSession()) return;
            console.warn("Target metrics save failed", e);
        }
        if (!isCurrentSession()) return;

        console.log("Phase 5.3A Target Metrics:", rows);
        return rows;
    };

    async function t53_saveTargets(rows, rangeType, range) {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        if (!rows || !rows.length) return;

        const batch = db.batch();

        rows.forEach(row => {
            const id = `${rangeType}_${range.start}_${range.end}_${row.email}`.replace(/[^a-zA-Z0-9@._-]/g, "_");
            const ref = db.collection("Target_Metrics").doc(id);

            batch.set(ref, {
                ...row,
                rangeType,
                calculatedAt: firebase.firestore.FieldValue.serverTimestamp(),
                source: "Phase_5_3A_TargetsEngine"
            }, { merge: true });
        });

        await batch.commit();
        if (!isCurrentSession()) return;
    }

    window.thuraya_setStaffTarget = async function(email, targets = {}) {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        if (!email) throw new Error("Staff email required.");

        const safeEmail = String(email).toLowerCase().trim();

        const payload = {
            dailyTarget: t53_num(targets.dailyTarget || targets.daily || 0, 0),
            weeklyTarget: t53_num(targets.weeklyTarget || targets.weekly || 0, 0),
            monthlyTarget: t53_num(targets.monthlyTarget || targets.monthly || 0, 0),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            updatedBy: (firebase.auth().currentUser?.email || currentUserEmail || "")
        };

        await db.collection("Staff_Targets").doc(safeEmail).set(payload, { merge: true });
        if (!isCurrentSession()) return;

        console.log("Staff target saved:", safeEmail, payload);
        return payload;
    };

    window.thuraya_debugTargetsToday = async function() {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        const rows = await window.thuraya_buildTargetMetrics("today");
        if (!isCurrentSession()) return;
        console.table(rows.map(r => ({
            staff: r.name,
            email: r.email,
            revenue: r.actualRevenue,
            target: r.targetRevenue,
            achievement: `${r.achievementPercent}%`,
            gap: r.targetGap,
            status: r.targetStatus
        })));
        return rows;
    };

    // Light auto-run for current day. No UI impact.
    window.ThurayaSessionResources.startupTimeout("app.js:18021:0", () => {
        try {
            if (firebase?.auth?.().currentUser) {
                window.thuraya_buildTargetMetrics("today");
            }
        } catch(e) {}
    }, 6000);

})();

// ============================================================================
// END THURAYA PHASE 5.3A PATCH
// ============================================================================


// ============================================================================
// THURAYA PHASE 5.3B PATCH
// Targets Dashboard UI
// Adds target vs actual visuals into the existing Performance Intelligence panel.
// Uses Phase 5.3A: thuraya_buildTargetMetrics(rangeType)
// No top-level auto-mount. No Admin layout disruption.
// ============================================================================

(function () {
    function tgSafe(v) {
        return String(v ?? "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;");
    }

    function tgMoney(v) {
        const n = parseFloat(v || 0);
        return `${n.toFixed(2)} GHC`;
    }

    function tgStatusColor(status) {
        const s = String(status || "").toLowerCase();
        if (s.includes("achieved")) return "#55a868";
        if (s.includes("on track")) return "#4b6cb7";
        if (s.includes("watch")) return "#d99a22";
        return "#c0392b";
    }

    function tgProgressBar(percent, status) {
        const p = Math.max(0, Math.min(100, parseFloat(percent || 0)));
        const color = tgStatusColor(status);

        return `
            <div style="width:100%;height:9px;background:#f0f0f0;border-radius:999px;overflow:hidden;margin-top:6px;">
                <div style="width:${p}%;height:100%;background:${color};border-radius:999px;"></div>
            </div>
        `;
    }

    function tgCard(label, value, sub, color) {
        return `
            <div style="border:1px solid #e4e4e4;border-radius:12px;padding:14px;background:#fff;">
                <div style="font-size:0.75rem;color:#777;text-transform:uppercase;letter-spacing:1.4px;margin-bottom:8px;">
                    ${label}
                </div>
                <div style="font-size:1.45rem;font-weight:800;color:${color || "#2f3b52"};">
                    ${value}
                </div>
                <div style="font-size:0.82rem;color:#777;margin-top:6px;">${sub || ""}</div>
            </div>
        `;
    }

    function tgFindPerformancePanel() {
        return document.getElementById("rptPerformancePanel52");
    }

    function tgEnsureSection(panel) {
        let section = document.getElementById("targetsDashboard53B");
        if (section) return section;

        section = document.createElement("div");
        section.id = "targetsDashboard53B";
        section.style.cssText = `
            margin-top:18px;
            border-top:1px solid #eee;
            padding-top:18px;
        `;

        section.innerHTML = `
            <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:12px;">
                <div>
                    <h3 style="margin:0;color:#2f3b52;letter-spacing:1.5px;text-transform:uppercase;">
                        Target Intelligence
                    </h3>
                    <p style="margin:6px 0 0;color:#666;">
                        Target vs actual revenue, achievement status and revenue gap.
                    </p>
                </div>
                <button class="btn btn-secondary btn-auto" onclick="thuraya_renderTargetsDashboard53B(window.P52_ACTIVE_RANGE || 'today')">
                    Refresh Targets
                </button>
            </div>

            <div id="tg53bStatus" style="font-size:0.85rem;color:#777;margin-bottom:12px;">Ready.</div>
            <div id="tg53bCards" style="display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:12px;margin-bottom:16px;"></div>

            <div style="overflow-x:auto;border:1px solid #eee;border-radius:12px;">
                <table style="width:100%;border-collapse:collapse;">
                    <thead>
                        <tr style="background:#f8f8f8;color:#2f3b52;text-transform:uppercase;font-size:0.78rem;letter-spacing:1px;">
                            <th style="padding:12px;text-align:left;">Rank</th>
                            <th style="padding:12px;text-align:left;">Staff</th>
                            <th style="padding:12px;text-align:right;">Actual</th>
                            <th style="padding:12px;text-align:right;">Target</th>
                            <th style="padding:12px;text-align:right;">Achievement</th>
                            <th style="padding:12px;text-align:right;">Gap</th>
                            <th style="padding:12px;text-align:left;">Status</th>
                        </tr>
                    </thead>
                    <tbody id="tg53bTable">
                        <tr><td colspan="7" style="padding:18px;text-align:center;color:#777;">Open Performance Intelligence to load targets.</td></tr>
                    </tbody>
                </table>
            </div>
        `;

        panel.appendChild(section);
        return section;
    }

    window.thuraya_renderTargetsDashboard53B = async function(rangeType = "today") {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        const panel = tgFindPerformancePanel();
        if (!panel || panel.style.display === "none") return;

        tgEnsureSection(panel);

        const status = document.getElementById("tg53bStatus");
        const cards = document.getElementById("tg53bCards");
        const table = document.getElementById("tg53bTable");

        if (status) status.innerText = "Calculating target metrics...";
        if (table) table.innerHTML = `<tr><td colspan="7" style="padding:18px;text-align:center;color:#777;">Loading...</td></tr>`;

        try {
            if (typeof window.thuraya_buildTargetMetrics !== "function") {
                throw new Error("Targets engine not found. Please apply Phase 5.3A first.");
            }

            const rows = await window.thuraya_buildTargetMetrics(rangeType);
            if (!isCurrentSession()) return;
            const rangeLabel = rows?.[0]?.range || (rangeType === "week" ? "This Week" : rangeType === "month" ? "This Month" : "Today");

            if (!rows.length) {
                if (status) status.innerText = `No target data found for ${rangeLabel}.`;
                if (cards) {
                    cards.innerHTML =
                        tgCard("Target Revenue", "0.00 GHC", rangeLabel) +
                        tgCard("Actual Revenue", "0.00 GHC", "No revenue yet", "#55a868") +
                        tgCard("Achievement", "0%", "No staff data", "#c0392b") +
                        tgCard("Target Gap", "0.00 GHC", "No gap data", "#d99a22");
                }
                if (table) {
                    table.innerHTML = `<tr><td colspan="7" style="padding:22px;text-align:center;color:#777;">No target records yet.</td></tr>`;
                }
                return;
            }

            const totalTarget = rows.reduce((s, r) => s + parseFloat(r.targetRevenue || 0), 0);
            const totalActual = rows.reduce((s, r) => s + parseFloat(r.actualRevenue || r.totalRevenue || 0), 0);
            const totalGap = Math.max(0, totalTarget - totalActual);
            const overallAchievement = totalTarget > 0 ? Math.round((totalActual / totalTarget) * 1000) / 10 : 0;

            const achievedCount = rows.filter(r => String(r.targetStatus || "").toLowerCase().includes("achieved")).length;
            const behindCount = rows.filter(r => String(r.targetStatus || "").toLowerCase().includes("behind")).length;

            if (status) {
                status.innerText = `Showing ${rangeLabel} target performance · ${rows.length} staff record(s)`;
            }

            if (cards) {
                cards.innerHTML =
                    tgCard("Target Revenue", tgMoney(totalTarget), rangeLabel, "#2f3b52") +
                    tgCard("Actual Revenue", tgMoney(totalActual), `${overallAchievement}% achieved`, "#55a868") +
                    tgCard("Target Gap", tgMoney(totalGap), "Revenue still needed", "#d99a22") +
                    tgCard("Status", `${achievedCount} Achieved`, `${behindCount} Behind`, achievedCount ? "#55a868" : "#c0392b");
            }

            if (table) {
                table.innerHTML = rows.map(r => {
                    const pct = parseFloat(r.achievementPercent || 0);
                    const statusColor = tgStatusColor(r.targetStatus);
                    const medal = r.targetRank === 1 ? "🏆" : r.targetRank === 2 ? "🥈" : r.targetRank === 3 ? "🥉" : "";

                    return `
                        <tr style="border-top:1px solid #eee;">
                            <td style="padding:12px;font-weight:800;">${medal} ${r.targetRank}</td>
                            <td style="padding:12px;">
                                <strong>${tgSafe(r.name)}</strong><br>
                                <span style="font-size:0.78rem;color:#777;">${tgSafe(r.email)}</span>
                            </td>
                            <td style="padding:12px;text-align:right;font-weight:700;">${tgMoney(r.actualRevenue || r.totalRevenue)}</td>
                            <td style="padding:12px;text-align:right;">${tgMoney(r.targetRevenue)}</td>
                            <td style="padding:12px;text-align:right;min-width:160px;">
                                <strong>${pct}%</strong>
                                ${tgProgressBar(pct, r.targetStatus)}
                            </td>
                            <td style="padding:12px;text-align:right;">${tgMoney(r.targetGap)}</td>
                            <td style="padding:12px;text-align:left;">
                                <span style="display:inline-block;padding:5px 9px;border-radius:999px;background:${statusColor};color:#fff;font-weight:800;font-size:0.8rem;">
                                    ${tgSafe(r.targetStatus)}
                                </span>
                            </td>
                        </tr>
                    `;
                }).join("");
            }

        } catch(e) {
            if (!isCurrentSession()) return;
            console.error("Targets dashboard error", e);
            if (status) status.innerText = "Targets dashboard error.";
            if (table) {
                table.innerHTML = `<tr><td colspan="7" style="padding:18px;text-align:center;color:#c0392b;">${tgSafe(e.message)}</td></tr>`;
            }
        }
        if (!isCurrentSession()) return;
    };

    // Hook into existing Performance module open function.
    setTimeout(() => {
        try {
            if (typeof window.rpt_openPerformance52 === "function" && !window.rpt_openPerformance52._tg53bWrapped) {
                const old = window.rpt_openPerformance52;
                const wrapped = async function(rangeType = "today") {
                    const isCurrentSession = window.ThurayaSessionResources.capture();
                    if (!isCurrentSession()) return;
                    const result = await old.apply(this, arguments);
                    if (!isCurrentSession()) return;
                    window.ThurayaSessionResources.timeout(() => window.thuraya_renderTargetsDashboard53B(rangeType), 500);
                    window.ThurayaSessionResources.timeout(() => window.thuraya_renderTargetsDashboard53B(rangeType), 1500);
                    return result;
                };
                wrapped._tg53bWrapped = true;
                window.rpt_openPerformance52 = wrapped;
            }
        } catch(e) {}
    }, 1200);

})();

// ============================================================================
// END THURAYA PHASE 5.3B PATCH
// ============================================================================


// ============================================================================
// THURAYA PHASE 5.3C PATCH
// Commission Engine
// Adds commission calculations on top of revenue-based Performance Intelligence.
// No UI layout changes yet.
// Collections:
// - Commission_Settings: optional per-staff or default commission configuration
// - Commission_Metrics: calculated commission snapshots
// ============================================================================

(function () {
    const COMM53C = {
        cache: []
    };
    window.ThurayaSessionResources.onStop('commission-53-cache', () => { COMM53C.cache = []; });

    function c53_today() {
        try {
            if (typeof getLocalDateString === "function") return getLocalDateString();
        } catch(e) {}
        const d = new Date();
        return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
    }

    function c53_range(type) {
        const today = c53_today();
        const now = new Date(today + "T00:00:00");

        if (type === "week") {
            const day = now.getDay();
            const diff = day === 0 ? 6 : day - 1;
            const start = new Date(now);
            start.setDate(now.getDate() - diff);
            return { start: start.toISOString().slice(0,10), end: today, label: "This Week", type: "week" };
        }

        if (type === "month") {
            return {
                start: `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}-01`,
                end: today,
                label: "This Month",
                type: "month"
            };
        }

        return { start: today, end: today, label: "Today", type: "today" };
    }

    function c53_num(v, fallback = 0) {
        const n = parseFloat(v);
        return isNaN(n) ? fallback : n;
    }

    function c53_round(v) {
        return Math.round(c53_num(v, 0) * 100) / 100;
    }

    async function c53_getDefaultSettings() {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        try {
            const doc = await window.ThurayaCommissionV2.legacySetting('default');
            if (!isCurrentSession()) return;
            if (doc.exists) return doc.data() || {};
        } catch(e) {
            if (!isCurrentSession()) return;
            console.warn("Default commission settings lookup failed", e);
        }
        if (!isCurrentSession()) return;

        return {};
    }

    async function c53_getStaffSettings(email) {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        const defaults = await c53_getDefaultSettings();
        if (!isCurrentSession()) return;

        if (!email) {
            return {
                ratePercent: c53_num(defaults.ratePercent || defaults.defaultRatePercent || 10, 10),
                threshold: c53_num(defaults.threshold || defaults.minimumRevenue || 0, 0),
                bonusPercent: c53_num(defaults.bonusPercent || 0, 0),
                bonusThreshold: c53_num(defaults.bonusThreshold || 0, 0),
                source: "default"
            };
        }

        try {
            const safeEmail = String(email).toLowerCase().trim();
            const doc = await window.ThurayaCommissionV2.legacySetting(safeEmail);
            if (!isCurrentSession()) return;

            if (doc.exists) {
                const d = doc.data() || {};
                return {
                    ratePercent: c53_num(d.ratePercent || d.commissionPercent || defaults.ratePercent || defaults.defaultRatePercent || 10, 10),
                    threshold: c53_num(d.threshold || d.minimumRevenue || defaults.threshold || defaults.minimumRevenue || 0, 0),
                    bonusPercent: c53_num(d.bonusPercent || defaults.bonusPercent || 0, 0),
                    bonusThreshold: c53_num(d.bonusThreshold || defaults.bonusThreshold || 0, 0),
                    source: "staff"
                };
            }
        } catch(e) {
            if (!isCurrentSession()) return;
            console.warn("Staff commission settings lookup failed", email, e);
        }
        if (!isCurrentSession()) return;

        return {
            ratePercent: c53_num(defaults.ratePercent || defaults.defaultRatePercent || 10, 10),
            threshold: c53_num(defaults.threshold || defaults.minimumRevenue || 0, 0),
            bonusPercent: c53_num(defaults.bonusPercent || 0, 0),
            bonusThreshold: c53_num(defaults.bonusThreshold || 0, 0),
            source: "default"
        };
    }

    function c53_calculateCommission(revenue, settings) {
        const rev = c53_num(revenue, 0);
        const threshold = c53_num(settings.threshold, 0);

        const eligibleRevenue = Math.max(0, rev - threshold);
        const baseRate = c53_num(settings.ratePercent, 10);
        const baseCommission = eligibleRevenue * (baseRate / 100);

        let bonusCommission = 0;
        const bonusThreshold = c53_num(settings.bonusThreshold, 0);
        const bonusPercent = c53_num(settings.bonusPercent, 0);

        if (bonusThreshold > 0 && rev >= bonusThreshold && bonusPercent > 0) {
            bonusCommission = rev * (bonusPercent / 100);
        }

        return {
            eligibleRevenue: c53_round(eligibleRevenue),
            baseRatePercent: baseRate,
            baseCommission: c53_round(baseCommission),
            bonusPercent,
            bonusThreshold,
            bonusCommission: c53_round(bonusCommission),
            totalCommission: c53_round(baseCommission + bonusCommission)
        };
    }

    window.thuraya_buildCommissionMetrics = async function(rangeType = "today") {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        const range = c53_range(rangeType);
        const commissionConfig = await window.ThurayaCommissionV2.refresh();
        if (!isCurrentSession()) return;
        if (commissionConfig.persons.some(person => person.enrollmentFrom <= range.end)) {
            throw new Error("Effective-dated commission must be viewed through Commissions; station-based metric recalculation is disabled for enrolled periods.");
        }

        if (typeof window.thuraya_buildPerformanceMetrics !== "function") {
            throw new Error("Performance engine not found. Build Phase 5.2 first.");
        }

        const performanceRows = await window.thuraya_buildPerformanceMetrics(rangeType);
        if (!isCurrentSession()) return;
        const rows = [];

        for (const row of performanceRows) {
            const settings = await c53_getStaffSettings(row.email);
            if (!isCurrentSession()) return;
            const totalRevenue = c53_num(row.totalRevenue, 0);
            const commission = c53_calculateCommission(totalRevenue, settings);

            rows.push({
                ...row,
                totalRevenue,
                range: range.label,
                rangeType,
                commissionRatePercent: commission.baseRatePercent,
                commissionThreshold: c53_num(settings.threshold, 0),
                eligibleRevenue: commission.eligibleRevenue,
                baseCommission: commission.baseCommission,
                bonusPercent: commission.bonusPercent,
                bonusThreshold: commission.bonusThreshold,
                bonusCommission: commission.bonusCommission,
                totalCommission: commission.totalCommission,
                commissionSettingsSource: settings.source,
                commissionRule: "RevenueBased"
            });
        }
        if (!isCurrentSession()) return;

        rows.sort((a,b) =>
            (b.totalCommission - a.totalCommission) ||
            (b.totalRevenue - a.totalRevenue) ||
            (b.efficiencyScore - a.efficiencyScore)
        );

        rows.forEach((r, i) => r.commissionRank = i + 1);

        COMM53C.cache = rows;

        try {
            await c53_saveCommissionMetrics(rows, rangeType, range);
            if (!isCurrentSession()) return;
        } catch(e) {
            if (!isCurrentSession()) return;
            console.warn("Commission metrics save failed", e);
        }
        if (!isCurrentSession()) return;

        console.log("Phase 5.3C Commission Metrics:", rows);
        return rows;
    };

    async function c53_saveCommissionMetrics(rows, rangeType, range) {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        if (!rows || !rows.length) return;

        const batch = db.batch();

        rows.forEach(row => {
            const id = `${rangeType}_${range.start}_${range.end}_${row.email}`.replace(/[^a-zA-Z0-9@._-]/g, "_");
            const ref = db.collection("Commission_Metrics").doc(id);

            batch.set(ref, {
                ...row,
                rangeType,
                calculatedAt: firebase.firestore.FieldValue.serverTimestamp(),
                source: "Phase_5_3C_CommissionEngine"
            }, { merge: true });
        });

        await batch.commit();
        if (!isCurrentSession()) return;
    }

    window.thuraya_setCommissionRate = async function(email, config = {}) {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        const safeEmail = email ? String(email).toLowerCase().trim() : "default";

        const payload = {
            ratePercent: c53_num(config.ratePercent || config.rate || config.commissionPercent || 10, 10),
            threshold: c53_num(config.threshold || config.minimumRevenue || 0, 0),
            bonusPercent: c53_num(config.bonusPercent || 0, 0),
            bonusThreshold: c53_num(config.bonusThreshold || 0, 0),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            updatedBy: (firebase.auth().currentUser?.email || currentUserEmail || "")
        };

        await db.collection("Commission_Settings").doc(safeEmail).set(payload, { merge: true });
        if (!isCurrentSession()) return;

        console.log("Commission setting saved:", safeEmail, payload);
        return payload;
    };

    window.thuraya_debugCommissionsToday = async function() {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        const rows = await window.thuraya_buildCommissionMetrics("today");
        if (!isCurrentSession()) return;
        console.table(rows.map(r => ({
            rank: r.commissionRank,
            staff: r.name,
            revenue: r.totalRevenue,
            rate: `${r.commissionRatePercent}%`,
            eligibleRevenue: r.eligibleRevenue,
            baseCommission: r.baseCommission,
            bonus: r.bonusCommission,
            totalCommission: r.totalCommission
        })));
        return rows;
    };

    // Commission calculations are explicit; loading a page must not recalculate stored metrics.

})();

// ============================================================================
// END THURAYA PHASE 5.3C PATCH
// ============================================================================

// ===============================
// PHASE 5.3D – ALERTS / ADVANCED INTELLIGENCE
// ===============================

// THURAYA ISSUE 5 - SHARED INTELLIGENCE PERIOD
(function () {
    const IC = window.ThurayaIntelligenceCanonical;
    let selected = null, frame = null, loading = null, pending = null;
    const checkpointSessions = new WeakMap();
    window.ThurayaSessionResources.onStop('intelligence-period-state', () => {
        selected = frame = loading = pending = null;
        ['intelligencePanel','phase62PredictiveOverview','phase64AiActionLayer'].forEach(id => {
            const panel = document.getElementById(id);
            if (panel) panel.style.visibility = '';
        });
        const bar = document.getElementById('intelligencePeriodBar');
        if (bar) {
            bar.setAttribute('aria-busy', 'false');
            bar.querySelectorAll('input,button').forEach(el => { el.disabled = false; });
        }
    });
    const today = () => getLocalDateString();
    const validDate = value => /^\d{4}-\d{2}-\d{2}$/.test(value || '') &&
        Number.isFinite(new Date(value + 'T12:00:00Z').getTime()) && new Date(value + 'T12:00:00Z').toISOString().slice(0,10) === value;
    function resolve(input = {}) {
        const mode = input.mode || 'monthly', anchorDate = input.anchorDate === undefined ? today() : input.anchorDate;
        if (!['daily','weekly','monthly','custom'].includes(mode)) throw new Error('Select a valid analysis period.');
        if (!validDate(anchorDate)) throw new Error('Select a valid analysis date.');
        const start = new Date(anchorDate + 'T12:00:00Z'), end = new Date(start);
        if (mode === 'weekly') start.setUTCDate(start.getUTCDate() - 6);
        const monthToDate = mode === 'monthly' && anchorDate.slice(0,7) === today().slice(0,7);
        if (mode === 'monthly') { start.setUTCDate(1); end.setUTCMonth(end.getUTCMonth()+1,0); }
        const startDate = mode === 'custom' ? input.startDate : start.toISOString().slice(0,10);
        const endDate = mode === 'custom' ? input.endDate : monthToDate ? today() : end.toISOString().slice(0,10);
        if (!validDate(startDate) || !validDate(endDate)) throw new Error('Select valid start and end dates.');
        if (endDate < startDate) throw new Error('End date must not be before start date.');
        const format = date => new Date(date + 'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
        const displayLabel = (startDate === endDate ? format(startDate) : `${format(startDate)} - ${format(endDate)}`) + (monthToDate ? ' (Month to Date)' : '');
        const days = Math.round((new Date(endDate+'T12:00:00Z')-new Date(startDate+'T12:00:00Z'))/86400000)+1;
        return Object.freeze({mode,anchorDate,startDate,endDate,displayLabel,days,monthToDate});
    }
    const get = () => pending || selected || (selected = resolve());
    const filter = (rows, period = get()) => rows.filter(row => {
        const date = IC.dateKey(row);
        return validDate(date) && date >= period.startDate && date <= period.endDate;
    });
    async function load(options = {}) {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        if (loading) return options.fresh ? loading.then(() => isCurrentSession() ? load(options) : undefined) : loading;
        if (frame && !options.fresh) return frame;
        const period = options.period || get();
        pending = period;
        const request = Promise.all([IC.readCollection('Active_Jobs'),IC.readCollection('Appointments')]).then(([jobs,appointments]) => {
            if (!isCurrentSession()) return;
            frame = Object.freeze({period,jobs:filter(jobs,period),appointments:filter(appointments,period),
                revenueRows:filter(IC.canonicalRevenueRows(jobs),period)});
            return frame;
        }).finally(() => { if (isCurrentSession() && loading === request) loading = null; });
        loading = request;
        return request;
    }
    async function read(name) {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        const data = await load();
        if (!isCurrentSession()) return;
        if (name === 'Active_Jobs') return data.revenueRows;
        if (name === 'Appointments') return data.appointments;
        throw new Error('Unsupported Intelligence population: '+name);
    }
    function controls(period) {
        const custom = period.mode === 'custom';
        return `<form data-intelligence-period-form><fieldset><legend>Analysis mode</legend>${['daily','weekly','monthly','custom'].map(mode=>`<label><input type="radio" name="intelligence-period-mode" value="${mode}" ${mode===period.mode?'checked':''}>${mode[0].toUpperCase()+mode.slice(1)}</label>`).join('')}</fieldset>
            <div class="intelligence-period-dates"><label ${custom?'hidden':''}>Analysis date<input name="anchorDate" type="date" value="${period.anchorDate}" ${custom?'':'required'}></label>
            <label ${custom?'':'hidden'}>Start Date<input name="startDate" type="date" value="${period.startDate}" ${custom?'required':''}></label><label ${custom?'':'hidden'}>End Date<input name="endDate" type="date" value="${period.endDate}" ${custom?'required':''}></label><button type="submit" class="btn btn-secondary" ${custom?'':'hidden'}>Apply</button></div></form>`;
    }
    function mount() {
        if (!window.ThurayaSessionResources.active()) return;
        const root = document.getElementById('intelligenceView');
        if (!root) return;
        let bar = document.getElementById('intelligencePeriodBar');
        if (!bar) {
            bar = document.createElement('section'); bar.id = 'intelligencePeriodBar'; root.prepend(bar);
            bar.addEventListener('change', event => {
                if (!['intelligence-period-mode','anchorDate'].includes(event.target.name)) return;
                const form = event.target.form;
                apply({...get(),mode:form.elements['intelligence-period-mode'].value,anchorDate:form.elements.anchorDate.value});
            });
            bar.addEventListener('submit', event => {
                event.preventDefault(); const form=event.target;
                apply({mode:form.elements['intelligence-period-mode'].value,anchorDate:form.elements.anchorDate.value,startDate:form.elements.startDate.value,endDate:form.elements.endDate.value});
            });
        }
        const period = get();
        bar.innerHTML = `<style>#intelligencePeriodBar{padding:16px 0;border-bottom:1px solid var(--border);margin-bottom:16px}#intelligencePeriodBar fieldset{display:flex;flex-wrap:wrap;gap:8px;border:0;padding:0;margin:0 0 12px}#intelligencePeriodBar fieldset label{display:flex;align-items:center;gap:6px;padding:8px;border:1px solid var(--border);border-radius:4px}#intelligencePeriodBar label:has(input:checked){background:var(--primary);color:white}#intelligencePeriodBar input[type=radio]{width:16px;height:16px;min-height:16px;margin:0}#intelligencePeriodBar .intelligence-period-dates{display:flex;flex-wrap:wrap;gap:12px;align-items:end}#intelligencePeriodBar label{min-width:0}#intelligencePeriodBar input[type=date]{max-width:100%;width:180px;box-sizing:border-box}#intelligencePeriodBar [hidden]{display:none!important}#intelligencePeriodBar p{overflow-wrap:anywhere}</style>
            <h3>Intelligence Analysis Period</h3>${controls(period)}<p data-intelligence-range data-mode="${period.mode}" data-start="${period.startDate}" data-end="${period.endDate}">${period.displayLabel} (inclusive)</p><p role="status"></p><p role="alert"></p>`;
        if (bar.getAttribute('aria-busy') === 'true') bar.querySelectorAll('input,button').forEach(el=>el.disabled=true);
    }
    async function apply(input) {
        const isCurrentSession = window.ThurayaSessionResources.capture();
        if (!isCurrentSession()) return;
        const bar=document.getElementById('intelligencePeriodBar');
        if (bar?.getAttribute('aria-busy')==='true') return;
        try {
            const period=resolve(input);
            if (bar) { bar.setAttribute('aria-busy','true');bar.querySelectorAll('input,button').forEach(el=>el.disabled=true);bar.querySelector('[role=status]').textContent='Updating Intelligence...';bar.querySelector('[role=alert]').textContent=''; }
            ['intelligencePanel','phase62PredictiveOverview','phase64AiActionLayer'].forEach(id=>{const el=document.getElementById(id);if(el) el.style.visibility='hidden';});
            if (!await window.thurayaRunIntelligenceEngine({period})) throw new Error('Intelligence could not refresh. Previous analysis remains unchanged.');
            if (!isCurrentSession()) return;
        } catch(error) {
            if (!isCurrentSession()) return;
            if(bar) bar.querySelector('[role=alert]').textContent=error.message;
        } finally {
            if (isCurrentSession()) {
                ['intelligencePanel','phase62PredictiveOverview','phase64AiActionLayer'].forEach(id=>{const el=document.getElementById(id);if(el) el.style.visibility='';});
                if(bar) {bar.setAttribute('aria-busy','false');bar.querySelectorAll('input,button').forEach(el=>el.disabled=false);bar.querySelector('[role=status]').textContent='';}
            }
        }
        if (!isCurrentSession()) return;
    }
    window.ThurayaIntelligencePeriod = {resolve,get,filter,validDate,load,read,mount,apply,
        checkpoint:()=>{const previous={selected,frame};checkpointSessions.set(previous,window.ThurayaSessionResources.capture());return previous;},
        commit:()=>{if(!window.ThurayaSessionResources.active() || !frame)return;selected=frame.period;pending=null;mount();},
        restore:previous=>{if(!checkpointSessions.get(previous)?.())return;selected=previous.selected;frame=previous.frame;pending=null;mount();},
        label:()=>({daily:'Selected Day',weekly:'Selected Week',monthly:get().monthToDate?'This Month':'Selected Month',custom:'Selected Period'}[get().mode])};
})();

let alertDataCache = [];
window.ThurayaSessionResources.onStop('intelligence-alert-cache', () => { alertDataCache = []; });

async function ai_loadAdvancedIntelligence() {
    const isCurrentSession = window.ThurayaSessionResources.capture();
    if (!isCurrentSession()) return;
    if (window.ThurayaIntelligencePeriod) return window.thurayaRunIntelligenceEngine?.();
    try {
        const today = todayDateStr;

        const [jobsSnap, targetSnap, commissionSnap] = await Promise.all([
            db.collection('Active_Jobs').where('dateString', '==', today).get(),
            db.collection('Staff_Targets').get(),
            window.ThurayaCommissionV2.legacySetting('default')
        ]);
        if (!isCurrentSession()) return;

        let revenueByStaff = {};
        let hoursByStaff = {};

        jobsSnap.forEach(doc => {
            const j = { id: doc.id, _collection: 'Active_Jobs', ...(doc.data() || {}) };
            if (isArchivedRecord(j) || !window.ThurayaIntelligenceCanonical.isCanonicalRevenueRecord(j)) return;
            const email = j.assignedTechEmail;

            const revenue = window.ThurayaIntelligenceCanonical.recognizedRevenue(j);
            const duration = window.ThurayaIntelligenceCanonical.serviceLineEntries(j).reduce((sum, line) => sum + line.duration, 0) || parseInt(j.bookedDuration || 0, 10) || 0;

            if (!email) return;

            revenueByStaff[email] = (revenueByStaff[email] || 0) + revenue;
            hoursByStaff[email] = (hoursByStaff[email] || 0) + (duration / 60);
        });

        let targets = {};
        targetSnap.forEach(doc => {
            targets[doc.id] = doc.data();
        });

        const commission = commissionSnap.exists ? commissionSnap.data() : {};
        const legacyEstimateAllowed = await window.ThurayaCommissionV2.allowLegacyEstimate();
        if (!isCurrentSession()) return;

        alertDataCache = [];

        Object.keys(revenueByStaff).forEach(email => {

            const revenue = revenueByStaff[email] || 0;
            const hours = hoursByStaff[email] || 1;
            const revenuePerHour = revenue / hours;

            const target = targets[email]?.dailyTarget || 0;
            const progress = target > 0 ? (revenue / target) * 100 : 0;

            let alertLevel = "normal";
            let alertMsg = "";

            if (progress < 60) {
                alertLevel = "danger";
                alertMsg = "At Risk";
            } else if (progress < 90) {
                alertLevel = "warning";
                alertMsg = "Behind Target";
            } else if (progress <= 110) {
                alertLevel = "success";
                alertMsg = "On Track";
            } else {
                alertLevel = "excellent";
                alertMsg = "Exceeding Target";
            }

            const commissionRate = parseFloat(commission.defaultRate || 0.1);
            const estimatedCommission = legacyEstimateAllowed ? revenue * commissionRate : null;

            alertDataCache.push({
                email,
                revenue,
                hours,
                revenuePerHour,
                target,
                progress,
                alertLevel,
                alertMsg,
                estimatedCommission
            });
        });

        ai_renderAlerts();

    } catch (e) {
        if (!isCurrentSession()) return;
        console.error("AI Alerts Error:", e);
    }
    if (!isCurrentSession()) return;
}

function ai_renderAlerts() {
    const container = document.getElementById('aiAlertsContainer');
    if (!container) return;

    if (alertDataCache.length === 0) {
        container.innerHTML = "<p style='color:#999;'>No alert data.</p>";
        return;
    }

    alertDataCache.sort((a,b) => b.revenue - a.revenue);

    let html = '';

    alertDataCache.forEach(staff => {

        let color = "#ccc";
        if (staff.alertLevel === "danger") color = "#e74c3c";
        if (staff.alertLevel === "warning") color = "#f39c12";
        if (staff.alertLevel === "success") color = "#27ae60";
        if (staff.alertLevel === "excellent") color = "#2ecc71";

        html += `
        <div style="background:white; border-left:5px solid ${color}; padding:12px; margin-bottom:10px; border-radius:8px;">
            <strong>${staff.email}</strong><br>
            Revenue: ${staff.revenue.toFixed(2)} GHC<br>
            Target: ${staff.target} GHC<br>
            Progress: ${staff.progress.toFixed(1)}%<br>
            Rev/Hr: ${staff.revenuePerHour.toFixed(2)}<br>
            Legacy Commission Estimate: ${staff.estimatedCommission === null ? 'View Commissions' : staff.estimatedCommission.toFixed(2)}<br>
            <span style="color:${color}; font-weight:bold;">${staff.alertMsg}</span>
        </div>`;
    });

    container.innerHTML = html;
}

// ===============================
// PHASE 5.4 – PREDICTIVE INTELLIGENCE
// ===============================

let predictiveCache = [];
window.ThurayaSessionResources.onStop('intelligence-predictive-cache', () => { predictiveCache = []; });

async function ai_loadPredictiveIntelligence() {
    const isCurrentSession = window.ThurayaSessionResources.capture();
    if (!isCurrentSession()) return;
    if (window.ThurayaIntelligencePeriod) return window.thurayaPhase62Render?.();
    try {
        const today = todayDateStr;

        const [jobsSnap, targetSnap, commissionSnap] = await Promise.all([
            db.collection('Active_Jobs').where('dateString', '==', today).get(),
            db.collection('Staff_Targets').get(),
            window.ThurayaCommissionV2.legacySetting('default')
        ]);
        if (!isCurrentSession()) return;

        let revenueByStaff = {};
        let hoursByStaff = {};

        jobsSnap.forEach(doc => {
            const j = { id: doc.id, _collection: 'Active_Jobs', ...(doc.data() || {}) };
            if (isArchivedRecord(j) || !window.ThurayaIntelligenceCanonical.isCanonicalRevenueRecord(j)) return;
            const email = j.assignedTechEmail;

            const revenue = window.ThurayaIntelligenceCanonical.recognizedRevenue(j);
            const duration = window.ThurayaIntelligenceCanonical.serviceLineEntries(j).reduce((sum, line) => sum + line.duration, 0) || parseInt(j.bookedDuration || 0, 10) || 0;

            if (!email) return;

            revenueByStaff[email] = (revenueByStaff[email] || 0) + revenue;
            hoursByStaff[email] = (hoursByStaff[email] || 0) + (duration / 60);
        });

        let targets = {};
        targetSnap.forEach(doc => {
            targets[doc.id] = doc.data();
        });

        const commission = commissionSnap.exists ? commissionSnap.data() : {};

        const legacyEstimateAllowed = await window.ThurayaCommissionV2.allowLegacyEstimate();
        if (!isCurrentSession()) return;
        const now = new Date();
        const currentHour = now.getHours() + (now.getMinutes() / 60);
        const workStart = 8;
        const workEnd = 20;

        const elapsed = Math.max(1, currentHour - workStart);
        const totalWorkHours = workEnd - workStart;
        const remainingHours = Math.max(0, totalWorkHours - elapsed);

        predictiveCache = [];

        Object.keys(revenueByStaff).forEach(email => {

            const revenue = revenueByStaff[email] || 0;
            const hours = hoursByStaff[email] || 1;

            const revenuePerHour = revenue / hours;

            const projectedRevenue = revenue + (revenuePerHour * remainingHours);

            const target = targets[email]?.dailyTarget || 0;

            const projectedGap = target - projectedRevenue;

            const commissionRate = parseFloat(commission.defaultRate || 0.1);
            const projectedCommission = legacyEstimateAllowed ? projectedRevenue * commissionRate : null;

            let riskLevel = "safe";
            let riskMsg = "";

            if (projectedRevenue < target * 0.7) {
                riskLevel = "danger";
                riskMsg = "Will Miss Target";
            } else if (projectedRevenue < target) {
                riskLevel = "warning";
                riskMsg = "At Risk";
            } else {
                riskLevel = "success";
                riskMsg = "Will Hit Target";
            }

            predictiveCache.push({
                email,
                revenue,
                projectedRevenue,
                revenuePerHour,
                target,
                projectedGap,
                projectedCommission,
                riskLevel,
                riskMsg
            });
        });

        ai_renderPredictive();

    } catch (e) {
        if (!isCurrentSession()) return;
        console.error("Predictive Engine Error:", e);
    }
    if (!isCurrentSession()) return;
}

function ai_renderPredictive() {
    const container = document.getElementById('aiPredictiveContainer');
    if (!container) return;

    if (predictiveCache.length === 0) {
        container.innerHTML = "<p style='color:#999;'>No predictive data.</p>";
        return;
    }

    predictiveCache.sort((a,b) => b.projectedRevenue - a.projectedRevenue);

    let html = '';

    predictiveCache.forEach(staff => {

        let color = "#ccc";
        if (staff.riskLevel === "danger") color = "#e74c3c";
        if (staff.riskLevel === "warning") color = "#f39c12";
        if (staff.riskLevel === "success") color = "#27ae60";

        html += `
        <div style="background:white; border-left:5px solid ${color}; padding:12px; margin-bottom:10px; border-radius:8px;">
            <strong>${staff.email}</strong><br>
            Current: ${staff.revenue.toFixed(2)} GHC<br>
            Projected: <strong>${staff.projectedRevenue.toFixed(2)} GHC</strong><br>
            Target: ${staff.target} GHC<br>
            Gap: ${staff.projectedGap.toFixed(2)} GHC<br>
            Rev/Hr: ${staff.revenuePerHour.toFixed(2)}<br>
            Legacy Commission Estimate (Projected): ${staff.projectedCommission === null ? 'View Commissions' : staff.projectedCommission.toFixed(2)}<br>
            <span style="color:${color}; font-weight:bold;">${staff.riskMsg}</span>
        </div>`;
    });

    container.innerHTML = html;
}

