        setValue('adv_sub_desc', s.categoryDescription || '');
        setValue('adv_type', s.serviceType || 'standard');
        setValue('adv_service_type_desc', s.serviceTypeDescription || '');
        setValue('adv_name', s.serviceName || '');
        setValue('adv_desc', s.desc || s.serviceDescription || '');
