    window.thurayaMapServicesToMenuCards = async function(){
        if (!window.db || !firebase?.firestore) { alert('Firebase is not ready. Refresh and try again.'); return; }
        if (!confirm('Map existing services into the approved Hand/Foot menu card structure?\n\nThis updates hierarchy fields and descriptions only. Existing edited prices/durations are preserved when already set.')) return;
        try {
            const snap = await db.collection(MENU_COLLECTION).get();
            if (snap.empty) { alert('No Menu_Settings_V2 services found.'); return; }
            let mapped = 0, skipped = 0;
            let batch = db.batch();
            let ops = 0;
            const now = firebase.firestore.FieldValue.serverTimestamp();
            for (const doc of snap.docs) {
                const raw = doc.data() || {};
                const patch = decidePatch(raw);
                if (!patch) { skipped++; continue; }
                batch.set(doc.ref, {...patch, updatedAt: now, updatedBy: currentUserEmail || 'menu-card-mapper'}, {merge:true});
                mapped++; ops++;
                if (ops >= 450) { await batch.commit(); batch = db.batch(); ops = 0; }
            }
            if (ops) await batch.commit();
            alert(`Menu card mapping complete.\n\nMapped: ${mapped}\nSkipped/unmatched: ${skipped}\n\nNow refresh Menu Settings and verify Hand + Foot hierarchy.`);
            try { if (typeof fetchLiveMenu === 'function') fetchLiveMenu(true); } catch(e) {}
        } catch(e) {
            console.error('HF44 menu card mapping failed:', e);
            alert('Menu card mapping failed: ' + e.message);
        }
    };
