            if (q('adv_service_type_desc')) q('adv_service_type_desc').value = raw.serviceTypeDescription || 'Primary bookable service selected as part of the client ritual.';
            if (q('adv_name')) q('adv_name').value = raw.serviceName || raw.name || '';
            if (q('adv_desc')) q('adv_desc').value = raw.serviceDescription || raw.desc || raw.description || '';
            if (q('adv_price')) q('adv_price').value = raw.price ?? 0;
            if (q('adv_duration')) q('adv_duration').value = raw.duration ?? 0;
            if (q('adv_selection')) q('adv_selection').value = inputTypeOf(raw.inputType || raw.selection || 'radio');
            if (q('adv_pricing_type')) q('adv_pricing_type').value = raw.pricingModel || priceModelOf('', inputTypeOf(raw.inputType));
            if (q('adv_priority')) q('adv_priority').value = raw.sortOrder || raw.priority || 9999;
            if (q('adv_status')) q('adv_status').value = statusOf(raw.status || (raw.isActive === false ? 'inactive' : 'active'));
